/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020924-5","meetingId":"h14-cm09","date":"2002年9月24日","dateIso":"2002-09-24","committee":"総務委員会","time":"午前１０時０５分～午後５時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を98件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"この１０社というか、２０社は。読まれるという言い方が正しいかどうかわからないけど、４億４，０００万円から上で勝負しようよという話ができているみたいな数字が並んでいる。いつも推測で言って業者の人には悪いかもしれないんだけど、素人として考えると、ここで競るんなら４億３，８００万円とかというのがあってもいいんじゃないのという気がするんですよ。ちょっとその辺の感想というか。","respondent":"西島経理課長","answer":"プラス、それに管理費とか、若干そういう関係が出てまいりますので、そのときに、では予定価格に対して幾らになったらばほかのところと勝負できるかというところの勝負になってきますので、そのところで、ここで言いますと、１００万円。","voiceIndex":7,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"きちんと正しくされているというふうには信じていますけれども、何か素人目に見ると、今も言われたように、きちんとしていればしているほど、４億３，９８０万円とかいう数字がなぜ出ないのかなと。もう１点は、別途工事のほうはこれからやるんですか。間に合うんですか、工事を進めていく中で。","respondent":"西島経理課長","answer":"予定ですけれども、電気設備と給排水設備に関しましては、１０月２１日に入札予定になっておりまして、外溝はもう少し遅れると思いますが、建築が先行するということで、それは十分間に合うということです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"きょう見てきたら解体をやっていたんですけど、あれは金額で幾らぐらいの値段か、解体だけで教えてください。ここと関係ないかもわからないけど、それだけ。","respondent":"西島経理課長","answer":"解体につきましては、６月１７日に入札をいたしまして、２，６４０万円で落札をしています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"３点質問します。先ほど予定価格の質問でしたけども、その金額を聞きたいんです。だから説明会もこれで終わりになったと思うんですけども、何かそうした近隣との関係ではきちっと解決されているんでしょうか。","respondent":"西島経理課長、片田施設担当課長","answer":"第２グループが区内のＢからＣと。Ｃの１０位ですね。ということで対象１９社ということで、区内の中小企業がこれに参加できるような入札の方法で実施したところです。解体工事に当たっての中では１件ほど振動についてのお話がございましたけれども、計画地から若干離れている方でございましたので、その辺は十分ご説明した中で一応ご了解はいただいてあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"最近の傾向としたものなのでしょうか。予定価格より全部１回目でも低いところに位置していますよね。大体こういう傾向なんでしょうか。そういう点では心配ないですかと聞くのもおかしいですけども、そういうところの心配りについてもお願いしたいなと思いますけど、その点１点と、それからこれは工事協定とかというのは結んだんでしょうか。","respondent":"西島経理課長、片田施設担当課長","answer":"１点目を私のほうからお答え申し上げます。予定価格に対しての落札率ですけども、今年度の状況はまだ８月末までの数字しか私はつかんでございませんけど、今年予定価格の事前公表を１，０００万円以上にいたしました。本体工事につきましては、これから１０月の末ぐらいになろうかと思いますけれども、改めて一応工事説明会を行った上で住民のほうのご意見を踏まえて、過去においても結んだ事例はあるとは聞いてありますけれども。","voiceIndex":16,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"単純な質問です。それから、中小、孫請け、下請けまで行きますと、その一番最後の段階で建設現場で働く皆さんに年金のカードというか何というか、証紙というのかな、そういうものが支給をされるものが十分にやられていない部分があるようなことが言われているんですけれども、ぜひそういうことはきちんと渡すように指導をしていただきたいと思うんですが、ご見解をください。","respondent":"片田施設担当課長、西島経理課長","answer":"これにつきましては、議案を提出する際に私どものほうでつくった資料が８月末ぐらいだと思ってございましたけれども、面積等々の最終確認をした上で補正をかけさせていただきましたので、今回ご報告させていただいた数字。２点目の質問ですけれど、その辺私ども国や都からも指導を受けてありますので、それについては再度年金の取り扱いについては働きかけてまいりたいというふうに思っております。","voiceIndex":19,"id":"exchange-006"},{"speaker":"藤田委員","kind":"確認","question":"確認なんですが、当該施設の隣にあります原っぱ公園、これは以前に荏原南公園で雨水対策として調整池を計画するに当たって、この原っぱ公園も将来は調整池をつくるんだと、そういうふうなお話を伺ったんですが、それは生きているのかどうか、それをまず最初にお伺いしたいと思います。","respondent":"矢部下水道河川課長","answer":"その件に関しましては、第２立会川幹線というものをなぎさ会館から工事を始めております。それの到達立坑として利用する予定になっております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"藤田委員","kind":"質問","question":"立坑というのは、調整池ではないということですか。","respondent":"矢部下水道河川課長","answer":"今の予定では、なぎさ会館から３，７５０mmのシールドを押します。２.７km先に原っぱ公園があるんですが、そこまでシールドをして、そこに立坑を事前に掘りまして、そこにシールドがドンとつくと、そういうような形の構造になっております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"藤田委員","kind":"質問","question":"結論的には、その計画を変更したんだということでしょうかね。調整池は変更したという認識でよろしいんでしょうか。それであれば、今この当該地が立会川に隣接していますので、何も原っぱ公園をこれから工事のために二重手間しなくても、この当該施設の地下を目黒川の調整池と同じような形でやれば十分可能ではないかなというそういう判断で今質問したわけですけども、調整池は変更したという認識をします。","respondent":"田村住宅課長","answer":"それ以外に知的障害者の一時のショートステイ施設が２室ということで、全体のバランスを考えますと、藤田委員ご指摘のとおり、個室１０室ということで約５割強個室を管理した上で、２人室、４人室というのを配備したものというふうに考えております。","voiceIndex":26,"id":"exchange-009"},{"speaker":"藤田委員","kind":"質問","question":"要するに２人部屋、複数部屋をこれだけ設けたという、今一つの福祉施設のあり方ですね。これは要する新聞紙上ですけれども、複数部屋をこれからやめようじゃないかという、そういう時代の流れですね。これは厚生委員会のほうでしょうかね。じゃ、改めてこれ伺います。もう一つ、屋上の緑化と言われていますけれども、それについては全く描かれてないんですが、それについても理由は何でしょうか。","respondent":"片田施設担当課長","answer":"全部合わせますと約１１０m2弱ほどですけれども、今回条例に比べると若干１０m2かそこら面積が足りない部分がありますけど、その辺は十分なる関係機関と協議の上、地上面の緑化をふやすということで一応対応しています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"林（宏）委員のほうからも質問のありましたことに関連しまして、一つは積算ですけれども、積算の費用というものはおおむねどの程度かかるものというふうに考えているかということをまずお聞きします。","respondent":"片田施設担当課長、西島経理課長","answer":"積算の費用の問題ですけれども、私どもは単価と言ってありますけれども、公共工事の積算単価といったものにつきましては、２３区と東京都全体ですけれども、現在私ども活用しているのは東京都の財務局が作成した積算費用。ただ、幾らというのは私どものほうで正確な数字はつかんでございませんので、機会がありましたら、どのぐらいしたんだろうということをつかんでまいりたいというふうに思っております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"こういう大型の受注が大変競争が激しくなって企業を圧縮しているのはご存知のとおりですけれども、確かにコンピュータ化されて見積もりにかかるコストが軽減されるのはわかるんですけれども、受注は１０見積もって一つとかそういうことになるわけですから、これが０．５％でもかなりの額になってくる。この際言っておきます。そういうことに対する防護策というのは基本的にどういうふうに考えているのか。","respondent":"西島経理課長","answer":"ただ、この決定は落札決定までに調査する時間がかかるといいうことで、ちょっと現実性に欠けるということがあります。ただ、一つの制度だというふうに私ども認識していますので、別途検討しています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"低入札調査制度というのが品川区ではかかっていないと。２０％を切ってしまったらこれは品質を疑わなきゃいけないというようなことが起こってくると思うんですけど、そういうものに対しては仕分けがあるんですか。この種類の工事に関しては１０％以下は全部だめ、そういうことをこちら発注側である程度線引きができているのかどうか。","respondent":"西島経理課長","answer":"というのは、仕入れ価格がかなり市場の価格が動いてまいります。そういうものについては最低制限価格を下回ることも考えられますので、その部分につきましては最低制限価格をはずすということでもう十分可能だろうということで実施をしています。","voiceIndex":35,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"今のお答えでそう思っていたんですが、というのは、こういうデフレの社会ですから、物に関してはかなりの低減が可能ですけれども、人件費に関してはダンピングでして、それがしわ寄せしわ寄せが下請け、孫請けに移って大変な状況が起こってきております。これで結構です。それに対応する契約内容になっているのかどうか、ちょっと教えていただきたいと思います。","respondent":"西島経理課長","answer":"これは解体するに当たりましては、現在既存の建物の図面をお出しをして、これはこういう建物になっているからここまで解体をしてくださいということの仕様を書いてお出ししていますので。","voiceIndex":37,"id":"exchange-014"},{"speaker":"塚本委員","kind":"意見","question":"この不確定要素を含む見直し情報の件で、現場で聞いたところによると、地下の図面というのはそんな詳しいものは出てきてなかったという話を聞いているんですが、違った構造物が入っていた、あるいは基礎が当たってみたらそこ抜かなきゃいけないとかいろいろあると思うんですが、そういうことに対しての条項が入っているのか。","respondent":"西島経理課長","answer":"契約書を定めたもの以外が出てきた場合は、甲乙両方で協議という条項は入っております。","voiceIndex":39,"id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"これを見ると駐車場がここにあります。下側に車の入り口がありますが、これは両方一方通行ですけども、駐車場の入り口とか出口はどうなっているんですか。","respondent":"片田施設担当課長","answer":"２ページ目の１階の平面図を再度ご確認いただければと思います。向かって左手が西側の原っぱ公園側ですけれども、これが朋優学園のほうから向かって北側に対して一方通行になってあります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"北側の立会側に２か所ということで、西側のほうは車が入ってきて回れるという感じのスペースなんでしょうか。","respondent":"片田施設担当課長","answer":"ご説明が十分でなかったところがありますけれども、まず住宅については今の５ページの図面でいきますと、まず建物の施設の入り口はエントランスホールの区営住宅というところがまず人の出入口になります。","voiceIndex":43,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"落札した松本建設のほうなんだけど、さっきも松本建設って出てきているんだけど、違う会社なんですか。","respondent":"西島経理課長","answer":"ご指摘のとおりでございまして、ＪＢを組んでおりますので、建設共同企業体というものが一緒でございまして、先ほどの部分は松本建設という会社で、こちらは松本組という別の会社です。","voiceIndex":52,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"なるほどね。それで１３ページに行きます。太い立杭が。左から流れてくるのがその１工事なのかな。前はその１、その２、その３って同じ会社がやらなきゃだめなんだというような話を前に聞いたことがあるんだけど、それとは違う仕様というか、内容の工事なんですか。この１３ページの絵でいって、真ん中の太い特殊人孔、真ん中の太いのから左側の工事と右側、上流工区と下流工区は別々の入札でできるんですか。","respondent":"西島経理課長","answer":"この部分と、それからこの斜めに下りてきます上流工区の部分、この部分をその１工事でシールド工事で実施をいたしました。それでその２工事はここの部分の表面をなだらかにする工事を主に行うという関係上、電気設備関係を共用できる。","voiceIndex":54,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"目黒川の左岸の工事のときに、要するに白金から下りてきたところから始まって五反田駅の地下からずっと３回に分けて工事やって、これは連続した管の工事だから同じ会社じゃないとだめだという説明を受けた覚えがあるんだけど、この立坑を一つの区切りとして、要するにシールドだからモグラ式に掘っていく。立坑を区切りにしてほかの会社がやっても可能だよという認識を持っていていいんですか。","respondent":"矢部下水道河川課長","answer":"シールド工事もその１工事、その２工事がどういう分け方になっているのかによっても、続けなきゃいけないか、分けられるかというのはあると思うんですけども、今回はその１、その２工事の場合は、今課長のほうから説明したとおり、一次巻き工事はその１工事でやりました。","voiceIndex":56,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"こんな話をするとこれから工事する人に失礼かもわからないんだけど、とかく水が出て困る。被害が出ていますよね、あちこち品川の場合は。なぜ水があふれちゃったのか。万が一出たときですよ。そういうことに対して、こういうふうに設計が違う人がやったときに、そういうことまで連携がされていて、それで何mm対応の下水になっているのかというのはなされているんですか。","respondent":"矢部下水道河川課長","answer":"ただ、思想的には１種類というふうに考えますので、その辺は大丈夫だと思います。","voiceIndex":58,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"確認","question":"最後に確認だけしておきます。あそこも首都高速が走っている下を通りますよね。そういうことに対してもこれから工事を始めていくわけだから、高速道路の水がどこに下りてきてどういうふうに流れ込むのかというのも一応検討しておいて、つくる下水がきちんと治水ということで役に立つようにお願いしておきます。確認だけど、内側の二次巻き工事はいつやるんですか。","respondent":"矢部下水道河川課長","answer":"二次巻きの工事はその４工事の中です。","voiceIndex":60,"id":"exchange-022"},{"speaker":"桜井委員","kind":"質問","question":"この辺もまだ完成はしているわけではないんですけども、その完成した後というのは効果というんですかね、どういうふうな具体的な効果が期待されるのかというのを知りたいんですね。今、立会川の流域の関係も、先ほどお話のあった第２幹線はちょっとまだこれからなんだけど、一応バイパスあそこも通るんですけど、なかなか効果がちょっとどうなのかというのが一つ心配なんですよね。二つご質問します。","respondent":"西島経理課長、矢部下水道河川課長","answer":"その１その２工事の金額は私のほうでお答えします。その１、その２工事合わせまして約１３億余です。そうしますと、今の効果に加えましてポンプ排水区になることの効果、両方合わさって浸水被害はかなり低減するのではないかと考えております。","voiceIndex":62,"id":"exchange-023"},{"speaker":"桜井委員","kind":"質問","question":"今のお話の続きですけど、確かにここのところ不動前のかむろ坂あたりの、平成１１年でしたかしら、２回にわたって浸水で大変私も心配したんですけども、そうするとそこの二日野の小学校から住宅のほうに流れて、あそこも大分問題になりましたよね。そこのところもかなり確かに被害があるところなんですけど、実際にバイパスが完成時というのは何年なんでしょうか。","respondent":"矢部下水道河川課長","answer":"それで完成の時期なんですけれども、全線の完成の時期、今回その３工事が平成１４年度、１５年度。その４は引き続き１５年度、１６年度という形で出す予定で考えておりますので、平成１６年度末には全線が一応は完成という予定にしております。","voiceIndex":65,"id":"exchange-024"},{"speaker":"土井委員","kind":"確認","question":"要するにこちらのほうのものもここに集めようということでこれからやるんですよという意味の部分ですねという確認をしたいと思います。もう一つは、先ほどちょっとお話がありました、高速道路は車も走るんですが、雨も走るということで、ちょっとこのあたりが両方から下がっているものですから、高速道路からじゃぶじゃぶ水が落っこちるという意味で問題になる地域なんですよね。ちょっと参考のために。","respondent":"矢部下水道河川課長","answer":"最初は、図面上の点線の部分ですけれども、その部分につきましても集水エリアになっておりまして、それは別途管渠を出す工事を出す予定にしております。","voiceIndex":67,"id":"exchange-025"},{"speaker":"土井委員","kind":"質問","question":"私がお伺いしたいのは、そのとおりだと思うんですよ。問題はその後。例えばいろいろ工事やりますけれども、これから高速道路できるかどうかわかりませんが、その種のものがつくられたときに、排水が新たに集中的に生ずるというと下の管渠に影響を与えるわけですね。そういうものの体制というのはどういう形になっているのかなということです。","respondent":"矢部下水道河川課長","answer":"これは過去の経験なんですけれども、練馬のほうで外環道路ができまして、そのときにやはり道路排水が大量に出るということで、下水道局の指導で雨水調整池、それを敷地内につくらせたというのは聞いております。","voiceIndex":69,"id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"わかりました。特にすぐ動けという問題ではないので、考え方を聞きたかったので。そういうときにはやはりお互いに協議をして地方自治体やそういう建設主体が協議をして、そのような対応、対処をいろいろ検討してやられるんだということがわかりました。は金をどこが負担するかはまたそのときですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-027"},{"speaker":"林（宏）委員","kind":"意見","question":"直接この話じゃなくて、立会川に東京駅から水を引っ張ってきて流したのは、地下の湧水が総武線の中に多く出ちゃって、それは処理するのに東京都に下水道料金を払うのに２億３億かかるから、こっちへ流すとＪＲのほうも費用コストが軽減できるし、世の中の役に立つということになった。地下から出た水はそういうふうに金かけるわけです。下水道と呼べるかどうか。それはやってほしいなと思いますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-028"},{"speaker":"桜井委員","kind":"質問","question":"今後の使い勝手というんでしょうか、考え方をお聞きしたいと思います。","respondent":"矢部下水道河川課長","answer":"そういう中で過去に下水道局と協議した結果、ここの上部利用につきましては、公園という形で利用していくという一つの方向性は出てあります。その中身については、まだ当分先になりますので、今後詳細については詰めていくというような考え方です。","voiceIndex":78,"id":"exchange-029"},{"speaker":"嶋委員","kind":"質問","question":"埋め立てについて近隣から私のほうも最初大変悪臭が強いということでの訴えという電話もなくなって、住民の方には大変喜ばしいと思います。きょうは護岸を見せていただいたんですけど、今まではあれが埋め立てる前は海上保安庁の社宅があって、中には入れなかったような記憶があるんです。今はずっと護岸に対して道ができていましたけど、あの道路は区道なんですか。","respondent":"矢部下水道河川課長","answer":"その辺の維持管理。持ち物については港湾局ということなんですが、維持管理についてちょっとその辺調べさせてください。","voiceIndex":80,"id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"というのは、請願とか陳情とかになったかどうかはあれですけれども、いろんな形で議論がされていた経過がありますから、区民の皆さんが、特に周辺の皆さんが一定のご理解を得ていくということが、またぞろ同じものがぞろぞろ出てくるというのも変なものですから、そこら辺はどこが対象という形で進めて、その到達レベルが公園ということなのかどうかということ。","respondent":"矢部下水道河川課長","answer":"それで地元の住民に対してどうかということなんですが、今回の埋立工事に関連しまして地元説明会をやっております。その中でもここについては将来的には公園になりますよということで説明しております。","voiceIndex":82,"id":"exchange-031"},{"speaker":"嶋委員","kind":"質問・要望","question":"今の上部のことなんですけど、私はこれ埋め立てる前のときに地域の方からご相談があって、どうなんでしょうかということで、そうやってお聞きしたときに、地域からは地域に集会所といいますか、町会もそういうみんなが集まるところがないので、ぜひそういうものをつくってもらいたいという要望を受けたことがあって、そのときに聞いたときには、下水道のところが管理するので無人になるので。","respondent":"矢部下水道河川課長","answer":"当時の議事録を見ますと、地元のほうから集会所の要望があったというのは記されております。","voiceIndex":84,"id":"exchange-032"},{"speaker":"塚本委員","kind":"意見","question":"写真を見ながら思い出したところですけれど、当該埋立地の入江の部分に係留してあった釣り舟等がどうかということなんですけれども、権利関係みたいなものはどう整理されているのか。当該のところから新しいところに移って、その権利はどことどういうふうに確定しているのか。その後勝島運河の使い勝手を制約するような約束事になるのかどうかを確かめたいと思います。","respondent":"矢部下水道河川課長","answer":"その持ち物につきまして、先日下水道局が持ち主にこれについては譲渡するというんですか、あなたのものですよという権利関係の引き継ぎ、それは終わったところです。","voiceIndex":86,"id":"exchange-033"},{"speaker":"塚本委員","kind":"意見","question":"これからのことを聞きたい。新しい約束事が文書でなされて、ここからここまでの部分は権利がこっちに移ったのだから改めて約束になっていますよということなのか、それは全体をこれから何らかの利用するときにその権利がどの程度影響するのかどうか、そのことを一番心配しているわけですけれども、そこのところ。","respondent":"矢部下水道河川課長","answer":"これに関しては、港湾局に対しては占用許可を提出いたしますので、その権利に関しましては従来と同じような形で、その持ち主に対して保護されるというんですか、そういう形になるかと思います。","voiceIndex":88,"id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"公有水面ですから、公益性が高いわけですよね。それで別の使い道、ヨットハーバーにしようじゃないかとか、あるいはいろいろな考え方、活用しようという大きな流れですから、そのときに今まで持っていた権利を取ってきたことがどういうふうな契約関係で、あるいは契約解除できるのかどうか、そういうことも含めてどういうふうになっているのかということです。きょうわからなかったら別の機会でもいいですよ。","respondent":"矢部下水道河川課長","answer":"今の件に関しまして、確かに航路等に支障がない場所ということで設定しているかと思いますが、その辺逆に言うと、勝島運河全体の使い勝手の中でどういうふうになるのかという委員のお尋ねかと思いますので、その辺はちょっと調べさせていただきまして、また改めてご報告します。","voiceIndex":90,"id":"exchange-035"},{"speaker":"桜井委員","kind":"質問","question":"その区有地に購入した経過というんでしょうか、まずそれを一つ聞きたいんです。それからこちらのサンウッド所有地のほうなんですけど、それも同じように、サンウッドの前はどなたが所有されていたのか、そのもともと前はどなただったのか、ちょっとそこのところの経過を、かなり飛び地なものですから、至った経過をまずお聞きしたいと思います。","respondent":"西島経理課長","answer":"区有地ですけれども、昭和６２年３月３１日に東京都から再開発事業用地として７億１，２００万円余で購入しています。それからサンウッドですけれども、もともとの持ち主は森ビルでございまして、その前はちょっと調べてありますけれども、後ほどわかればお答えしたいと思います。","voiceIndex":97,"id":"exchange-036"},{"speaker":"桜井委員","kind":"提案","question":"教えてください。それで都から区が購入した、再開発用地として区が７億円で購入したということですよね。実際に今計画がなく、今回議案に提案されているこうした建物を例えば区がつくって、そしてこうして創業にやるということではなかったと思うんですよね。ですからどういう経過が議論になってここに至ったのかというのを知りたいところなんですけれども、よろしくお願いします。","respondent":"南雲都市開発課長、西島経理課長","answer":"森ビルの前ですが、これは全国海苔貝類漁業共同組合連合会というところが所有していたということはわかっているんですが、いつというのははっきりしませんが。再開発が終了した以降は普通財産のほうに切り換えまして、この土地につきましては、賃貸でお貸しをいたしました。約十数年間になりますが、１億５，０００万円ほどここで収入を得ております。","voiceIndex":99,"id":"exchange-037"},{"speaker":"桜井委員","kind":"質問","question":"そうすると当時昭和６２年に７億円あって、単純に割り算すると平米単価１００万円ですね。それでその間今日まで貸していて１億５，０００万円収入があったと。今回の価格で見ると３億９，５９１万円。かなり下がっているんでしょうかね。その点が非常に疑問符になるところが１点できたと思うんです。それから先ほどの森ビルの関係で、その前は全国海苔貝類。サンウッドというのは森ビルの系列なんですか。","respondent":"南雲都市開発課長","answer":"このサンウッドといいますのは、森ビルの子会社という関係になってあります。","voiceIndex":102,"id":"exchange-038"},{"speaker":"桜井委員","kind":"質問","question":"事務所と、それから住宅とかって幾つか言いましたけど、１７ページで見ると、１７ページは２階部分で、この３階部分、それぞれの面積も一応教えてくれますか。さっき住宅を言っていましたね。１９ページのことなんでしょうか４階の。そうすると今の計画ですと、区が考えている総合支援の考え方だと、この住宅のところというのは居住に活用するということなんでしょうか。","respondent":"南雲都市開発課長","answer":"２０ページに立面図があります。これでいきますと、１階がエントランスで、２階、３階が事務所ということになっております。その間に免震の層があります。その上が住宅ということで、２階、３階がそれぞれ専有部分で、２７３.７５m2。","voiceIndex":104,"id":"exchange-039"},{"speaker":"桜井委員","kind":"質問","question":"この計画、実際の建物というのはいつ完成を予定しているんでしょうか。購入の時期というのはいつごろをめどにしているのでしょうか。","respondent":"南雲都市開発課長","answer":"今後いろいろな準備作業がありまして、今年の１１月には本体工事に着手をするという予定になっておりまして、工期としてはおおむね２年ということで、平成１６年１１月ごろには完成の予定になっております。","voiceIndex":106,"id":"exchange-040"},{"speaker":"嶋委員","kind":"質問","question":"海岸通りからずっと夜はタクシーが随分止まっているんですが、このパーキングはとても地域の方は利用されているんですが、これから地下１階になりますと、地下１階はパーキングかなと勝手に想像しておりますが、このようなパーキングを設置すると、地域から何か問題というか、そういうのはなかったのかどうかお聞きをしたいと思います。","respondent":"南雲都市開発課長","answer":"このパーキングにつきましては、森ビルが土地の暫定利用として時間貸しで駐車場を経営していたものでございまして、この天王洲周辺には大きなビルが建っておりますが、そのビルの地下などにも駐車場がありまして、ここも一部時間貸しなども行っておりますので。","voiceIndex":108,"id":"exchange-041"},{"speaker":"嶋委員","kind":"意見","question":"でも、実際問題、今ほとんど夜は駐車違反が二桁というふうにいつも止まっているわけですね。今、公開空地ができてくるようですけど、ここら辺もほとんど車で夜はこれからビルができたときに、想像するだけで危ないのかなと思いますが、地域からそういう問題が出たかどうかも。","respondent":"南雲都市開発課長","answer":"このように実際に駐車場があるのに路上に止めている場合には、やはり警察などとも協力して駐車違反の取り締まりをするというのが、これがどこの駅前であっても行われていることで。","voiceIndex":110,"id":"exchange-042"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました。私もそう思います。きっと空いていてもそこら辺に置きやすいので置いてしまうことなら、なるべく駐車ができないようないろんな形でぜひ配慮していただきたいと思いますので、交通安全をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-043"},{"speaker":"塚本委員","kind":"確認","question":"森ビルの件で確認したいんですが、建築会社はどこなのかということと、それから図面を見ますとこの辺一角をブロックで再開発したものがあると思うわけですけれども、現場へ行ってみると、堅固な建物ではないというようなことでありましたので、再開発のお話があったのかないのか、それについてのいきさつを。","respondent":"南雲都市開発課長","answer":"それから周辺につきましては、この隣、西側にマンションですとか、賃貸の集合住宅などがございまして、周辺もいろいろ調査をしたのですけれども、なかなか共同化をするのは権利関係も複雑になるということで、いろいろ検討した結果。","voiceIndex":113,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"他人の目から見ると、力の問題での権利関係も複雑だというふうなことを感じていますが、これは着工予定はいつでしたか。もう既に決まっているのかということと、それからもう１点あります。こういう政策的な目的があるから、この部分は下げていわゆる補助行政であるということの考え方を教えてください。","respondent":"小野政策担当課長、南雲都市開発課長","answer":"今までの企業をもとにして独立をする。こういう意味で新しい産業を起こすことによって、それで区内への商工業者へのいろんな広がりというのも増やすという意味で新しい部分ということで産業の支えとして取り組むです。着工の時期ですが、まだ細かい日時は決まっておりませんが、現在のところ、本年１１月の予定というふうに聞いております。","voiceIndex":115,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"わからないなら、今手元に情報がないならないと言えばいいんで、そのほかのことはみんな知っていることですからいいでしょうし、施工業者が２月前にわからないというのはちょっと信じられないですから、もう一度お願いします。","respondent":"南雲都市開発課長","answer":"施工会社についてはどこということはサンウッドに確認しておりません。","voiceIndex":118,"id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"等価交換ということなら、それのクオリティを心配するのは当たり前の話。まして３億９，５００万円ものお金でしょう。それはだれがつくるのかということは、情報を取るように注意しておきます。それから先ほど質問した大家業の件で答えが半分しかなくて、どういう長期的な判断で助成をするのかということ。どこの会社が来たのか。","respondent":"小野政策担当課長、市岡企画財政課長","answer":"現在、具体的な賃貸の金額とかそういうものについては産業振興課のほうで調査をかけて設定を検討しているという話であります。したがって私どもが例えば入居費用を決めるというよりは、この辺は産業振興課で進めておりますが、例えば商工会議所の品川支部と連携をして、むしろその中で選定委員会なり、あるいはここに進出する意欲のある企業に集まっていただいて。","voiceIndex":120,"id":"exchange-047"},{"speaker":"塚本委員","kind":"質問","question":"実際、こういう大家業をやることの是非というのはまた別途議論があると思いますけど、民間のほうから見れば、手を染めたなと見られるのは当たり前のことなんですから、自分たちがどういう決め事でどういうスタンスでやるんだということの説明。というのは、なぜかというと、民間の大家業の人たちが利益を出して、そこから税金を納めて、そのもとでやっていくんですから。そのことはどうなんですか。","respondent":"中尾根企画部長","answer":"それから活用の方策ですけど、これは施策として、先ほど言いましたような第２創業というようなことですけれど、実際上には一生懸命頑張っている企業が親や何かから独立しようとか、そういうような側面というのが一応それなりに調査をかけて動きがある。","voiceIndex":123,"id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"西大井にその施策を導入した経緯はある程度承知しています。しかしながら、区や自治体が大家業をやっていけない、計画選択として責務があるからこういう施策を入れるんだ、まちづくりのために先行的に導入策として必要だというならわかりますよ。品川区というのは調子がいいなという話になっちゃうわけですから、そこのところをしっかりしてほしいということを言っておきます。","respondent":"中尾根企画部長","answer":"いろいろ検討しましたけれども、そのときはいろいろ検討の中でも、もともと西大井には確かに創業をやっていたそういう人たちを基本的にどのように維持していくのか。","voiceIndex":125,"id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"土地はきょう見た品川区の土地と土地付建物を、平たく言うと等価交換しますよということで、この説明書の２番に、区が取得する土地つき区分建物というのに（１）と（２）、（３）は相手なんだけど、（１）の土地というところにいろんな数字が並んでいるんだけど、単純に何平米だというのはどこを見ればいいんですか。土地付区分建物の土地とは何平米と理解すればいいですか。この説明書の中で。","respondent":"西島経理課長","answer":"単純に登記簿上はこういう記載になるんですが、単純にやってしまえば、１，５３１.４１×７７万６，７７２分の６万４，７５０〔「計算してください」と呼ぶ者あり〕という数字になると思います。ちょっと計算機今ないんで、あればすぐ答えをお出しいたします。","voiceIndex":127,"id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問","question":"だからこことかこことか言うんじゃなくて、数字的に何平米、この数字、分数の掛け算すると、土地付区分建物という中の土地はどのぐらいの平米数があるんですかと聞いているわけ。でも２階から２、３、４と３フロアなんだよ。３フロア分。４階は何か電気の配線図みたいにいろいろ図がなっているんだけど、どういうふうな品川区のものになるのかを聞かせてください。","respondent":"西島経理課長","answer":"それで後段の部分ですけれども、説明が足りないところはつけ加えてお答えをしますけれども、この建物、４階から上は住居棟です。住居棟の入り口は全然別の入り口になりまして、１６ページの図で言いますと、右上のほうありますけれども、ここが住居棟の入り口になります。","voiceIndex":129,"id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると２階３階の平米数が幾らで、今４階は１００m2。そうすると単純にこれ６４７m2だから、５４７m2の２分の１が２階３階に当てはまって、その残りが１００m2という計算でいいのかどうか、後で。そういうふうにこの１９ページの図はそういうふうに読んでいいんですか。","respondent":"西島経理課長","answer":"４階の部分ですけど、これは基本計画図ということになっていまして、２３階の建物をつくったときにはこういうふうなということで出してきてありますので、このうちの６０.４７の部屋とどこかの部屋をもらうとか、そういうところについてはこれから詰めてまいりまして。","voiceIndex":131,"id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問","question":"そうするとそこはさっき言われた賃貸で貸し出すのか、住宅はどういうふうに使っていくのか。先ほどの２階３階の商業的産業振興に使うというのは、一応そこで埋まるのかなと思うけれども、使い方はわかったけど、４階の使い方はどうするんですか。","respondent":"西島経理課長","answer":"そこの部分はきちっと最後まで詰めているわけでございませんけども、例えば２階３階の事務所棟の住居棟部分として使うということも一つの方法ですし、先ほどお話ししましたように、お金でその部分について清算をするということも一つの方法ですし。","voiceIndex":133,"id":"exchange-053"},{"speaker":"林（宏）委員","kind":"質問","question":"４億円からの投資をして３フロアだけだけど、区が持ち分としてあるということに関してはちょっと無責任な気がしないでもないんで、もう少し真剣に取り組むように。内容はもちろんだけど、相手がつくってくれたのを、ああそうですか、でき上がりましたか、どうもありがとうありますって受け取るぐらいの気持ちしか今持っていらっしゃらないというふうに受け取りますけどね。","respondent":"中尾根企画部長","answer":"そういう意味ではちょっと表に出ていない、説明しない部分がいろいろありますけれども、そこのところを今一生懸命調整をしているということでご理解をぜひいただきたい。","voiceIndex":135,"id":"exchange-054"},{"speaker":"林（宏）委員","kind":"質問","question":"事情は、相手側は相手側のポリシーというか、目指すものがある。区側は今言われたように区として持っていなきゃいけない。これだけの土地を提供するわけですから。きょうはこういう契約の話だけど、中身についてはもう少し報告を引き続きしてほしいなというふうに思いますのでお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-055"},{"speaker":"桜井委員","kind":"質問","question":"この建物の総事業費は幾らでしょうか。例えば区がもし一定程度の権利はあるわけですから、そうすれば１フロア全部が事務所がこういうふうになるというのとか、言わば区が貸し出しをしていくとなれば管理しやすいというか、そういうことだってあり得ると思うんですよね。そうなれば、例えば１階とか２階とかね。事務所だってそうですよ。だから売り出しているんじゃないですか。どうなんでしょうか。","respondent":"南雲都市開発課長","answer":"総事業費、これが約４４億６，０００万円です。これが大まかな、まだ確定しておりませんが、総額です。","voiceIndex":138,"id":"exchange-056"},{"speaker":"桜井委員","kind":"質問","question":"それはちょっと私も思っているわけじゃないんですけど、いつから売り出しですか。それで住宅、分譲と事務所ということになると、それぞれの売り出しの仕方が違うと思うんですよね、多分ね。だからその辺の実際に経営者となるわけですよね、区が。土地を持っているわけですから。区分所有ですから。だから売り出しはいつからですか。売り出しだと森ビルの関係があるという理解なんでしょうか。","respondent":"南雲都市開発課長","answer":"これについては、まだサンウッドのほうからいつから売り出すという細かいことについてはサンウッドのほうからまだ確認しておりません。それから工事についても、これもまだどこの業者に発注というのはまだ確認ありません。","voiceIndex":140,"id":"exchange-057"},{"speaker":"嶋委員","kind":"確認","question":"確認だけお願いします。住宅に関しては分譲ということでサンウッドということで、住宅に関してはサンウッドが全部責任を持ってやるということで、区のほうは一切……。それだけ確認。地域にやっぱり住宅ができるということでは皆さん喜ぶ反面、区民で一般の人が手が届くかどうかわからない価格だったと思いますが、その辺を。","respondent":"南雲都市開発課長","answer":"分譲の部分の売り主はサンウッドということで、サンウッドが自分で所有する部分を分譲するです。","voiceIndex":142,"id":"exchange-058"},{"speaker":"桜井委員","kind":"意見","question":"今、経過の中でわかったように、購入の時期からしても問題を呈しておりまして、天王洲の再開発用地として都から高い買い物をして一体どう使うんだという、そういうところからも問題があったわけですし、使い勝手を見ましても、森ビルとの関係もありますし、４４億６，０００万円の総事業費のうち、実際評価価格が３億円というふうに言っているわけですけども、事実上独立創業支援というふうに言うけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":145,"id":"exchange-059"},{"speaker":"林（宏）委員","kind":"提案","question":"この提案されている議案のきょう賛成する部分というのを明確にしておきたいんですけど、土地と土地付区分建物の交換について、所在、地目、地積、評価額ということで、この金額で等価交換をしていくということについては賛成ですけれども、この条例のこの案でありますが、これの７行目、区長のお名前で、創業支援事業に充てるため、下記のとおり土地と土地付区分建物を交換するということですけども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-060"},{"speaker":"塚本委員","kind":"意見","question":"中身に入ります前に、第８条で本文があって、２、３と続きます。９条のところに本文があって、（１）（２）と。６条もそうですけれども。この番号のとり方はどういうことなのか。","respondent":"山田広報広聴課長","answer":"それでそのあとの２項、３項という形に位置づけ的にはなるということで、９条につきましては、最初の２行については１項でありまして、１項に関連する１号、２号というような意味合いということになりますので、ご理解いただきたいと思います。","voiceIndex":154,"id":"exchange-061"},{"speaker":"桜井委員","kind":"提案","question":"これに入る前にお聞きしたいんですが、今区民からの、先ほど趣旨の提案の説明のときに、いろんな意見とか不安とかというそういう触りもあったんですけど、今月時点で９月１３日というのがこの間いただいた数字ですけども、その内訳を聞きたいんですね。区民からの照会でどういう状況なのか主な点をまず聞きたいと思います。","respondent":"冨田戸籍住民課長","answer":"ご要望とかご質問とかいろいろありますけれども、例えばコードの用途、どういう用途に使うのかというものが１１６件、番号変更ができるのかとかいう内容のものが１２３件、受け取り拒否はどうすればいいのかというのが４２件、コード番号を抹消してほしいというのが６９件。","voiceIndex":157,"id":"exchange-062"},{"speaker":"桜井委員","kind":"質問・要望","question":"一つ二つ聞きたいんですけど、今回個人情報保護整備が国のほうで実施されていないということで、実際に今回の特別法的な内容で設置するというんですけども、ちょっとお聞きしたいのは、品川区の情報公開・個人情報保護条例の中で、第２６条なんですけど、第２６条と情報提供の２９条の第３項の関係なんですけど、この第２６条というのは、外部提供に伴う措置ということで、実施機関は入っているんですけども。","respondent":"山田広報広聴課長","answer":"区長に関しては、さきの定例会でもご答弁申し上げたとおり、あくまでも住民基本台帳法という法に基づいて実施をしていく市区町村の責務があるというふうにうたわれている中で、法を守るという立場でこれについては行っていくというふうに明言しておりますので。","voiceIndex":159,"id":"exchange-063"},{"speaker":"桜井委員","kind":"質問・要望","question":"ちょっとさかのぼってお聞きしたのは、別に今回の条例そのものについて、別につくることについてちょっとまた別の角度で質問したいんですけど、要するに今回条例をつくるに当たってもそうですし、当然お話があったように、今回のつなげていけば１億２，０００万人のネットになっていくというのは大量のやっぱり状態になっていくわけで、そのことのセキュリティってさっきからお話があったけども。","respondent":"山田広報広聴課長","answer":"最初の質問の部分でお答えしなきゃいけなかったんですけれども、情報公開等審議会の中で当然これについての区の状況、いわゆるセキュリティの具合であるとかいうのも、まさにきょうごらんいただいたとおり、コンピューター室も見学をいたしまして。","voiceIndex":161,"id":"exchange-064"},{"speaker":"桜井委員","kind":"提案","question":"そうするとこの問題について情報公開等審議会にかけたということでしょうか。それはもしかけたとすれば、その粛々とやっていくということがあって、それで今回条例を提案するに当たってはまた改めて情報公開等審議会におかけになったという理解なんでしょうか。そこをもう少し答弁していただきたいのと、それから先ほど言った第２６条との関係もそうなんですけど、こちらの今回の。","respondent":"山田広報広聴課長","answer":"桜井委員のおっしゃっている国の個人情報保護法が通らない前にこの条例はいかがなものかという点かと、または先に言うべきではないかということかと思いますけれども、現在個人情報保護法がない中での部分の穴埋めをするような形の条文を品川区でできる部分での条文を盛り込んで。","voiceIndex":163,"id":"exchange-065"},{"speaker":"塚本委員","kind":"質問","question":"切断するとか、市民の選択に任せるとか、何種類かに分かれると思うんですけれども、国が命じた部分というのは自治体としては従わなければならないんだろうけど、その関係を一つ教えてください。必ず従わなければいけないのか。あるいはある種異議申し立てをしていいのか、そういうことの関係をまず一つ聞きたいのと、今回他の自治体が従わないのは、法的にはどういうふうに解釈されるのかということ。","respondent":"山田広報広聴課長","answer":"ご存じのとおり、現在３，２００ほどある地方公共団体の中で五つの団体がいわゆる接続をしていない、または横浜市のように、市民の選択制にゆだねるということで実施をしているものということで、五つあります。","voiceIndex":165,"id":"exchange-066"},{"speaker":"塚本委員","kind":"意見","question":"指導しているかどうかは聞いていないので、法的にどういう関係にあるかということを。","respondent":"山田広報広聴課長、中尾根企画部長","answer":"済みません。説明が足りませんで。あくまでもこれは自治事務としてうたわれておりますので、基本的に実施をしなければいけないです。補足ですが、これは地方自治法の第２条の第１６項、「地方公共団体は法令に違反してその事務を処理してはならない」。なお、市町村及び特別区は、当該都道府県の条例に違反してその事務を処理してはならない。","voiceIndex":167,"id":"exchange-067"},{"speaker":"塚本委員","kind":"意見","question":"もう１点聞いたんですけれども、国がつくる法律はすべて正しいとは言えないわけで、これはもう自明のとおりですね。間違ったこと、だからこそ国に異議申し立ての件、いろんなことができるという仕組みになっているわけです。国と地方自治体間の関係はどうなっているかを知りたいわけです。","respondent":"中尾根企画部長","answer":"いわゆるできた法が通常言われるいい法律なのか、悪い法律なのか、悪法なのかという、そういう判断そのものにつきましては、もともと立法、法を立てた、要するに提案をし、それを議決した問題でございまして。","voiceIndex":170,"id":"exchange-068"},{"speaker":"塚本委員","kind":"質問","question":"ですから異議申し立てをしている自治体が今あるということは、それはにらみ合っていれば国が訴えるという事態も想定できる、司法の判断でやれるということも想定できるというふうに理解していいわけですか。","respondent":"中尾根企画部長","answer":"ただし、私どもの考えからしますと、やはりできた法律は不足の部分があったとしても適法であると、こういう判断ですので、それに通常であれば従わなければならないのではないかと。","voiceIndex":172,"id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"その自治体が微妙なことを巧妙に異議申し立てをしているというふうに理解してよろしいんですか。","respondent":"中尾根企画部長","answer":"条件ができるまではそこのところに参加しない、断絶するという言い方ですので、この条件というものの要するにとらえ方、範囲というものがあるというふうに考えております。","voiceIndex":174,"id":"exchange-070"},{"speaker":"塚本委員","kind":"意見","question":"ある種ずれといいますか、整合性のとれない事態が起こる可能性が考えられるわけですけれども、このことについてはどういうふうに理解を。","respondent":"山田広報広聴課長","answer":"これについては、私どものほうも国の個人情報保護法が成立され、ある意味では私どもの条例よりもより厳しい縛りがあるとか、さまざまな要件が乗ってきた場合は、こちらの条例を廃止することも含めて。","voiceIndex":176,"id":"exchange-071"},{"speaker":"林（宏）委員","kind":"提案","question":"条例の中に入らないという部分で話をしているので、同じような質問を。個人のそういう権利とかプライバシーを保護する法律化条例化というところが、今品川区では条例でここ品川区民の個人情報の権利というのか、保護しましょうよということの提案をされていると思うんですよね。その間に地方自治情報センターというのが入るけども、流れとしては国にも行くと。それをまずちょっと確認したいんだけど。","respondent":"山田広報広聴課長、冨田戸籍住民課長","answer":"それは法にうたった９３事務しかできませんよということで、国のどこか１カ所に全部があるということではなく、あくまでも共同開発をした地方自治情報センターというところにすべてがあると。今の説明、ちょっと補足なんですけれども、地方自治情報センターのほうに情報が行くのは、本人確認情報だけです。情報センターのほうでは、本人確認情報以外の記録はしません。","voiceIndex":178,"id":"exchange-072"},{"speaker":"林（宏）委員","kind":"確認","question":"でしょ。そこをはっきりしてほしいんだよ。やたら言葉を変えて、本人確認情報以外はセンターのほうは持てませんよと言葉を変えちゃうからややこしくなるんだ。どこにつながっているから、だれがその情報をもらえるんですかというふうに聞こうと思ったわけよ。それから国の機関も知り得る、都道府県も知り得る、２３区それぞれの区で知り得るということなんですねということだけ聞きたい。","respondent":"山田広報広聴課長","answer":"本人確認情報に関しては、ご指摘のとおりです。","voiceIndex":181,"id":"exchange-073"},{"speaker":"林（宏）委員","kind":"質問","question":"とすると、品川区で今度この条例を定めて、どのぐらいの自治体、自治体は三千二百幾つ、都道府県は４７、政令指定都市は１２、それから国の機関はちょっと幾つあるかわからない。８０か１００か２００か。その使える団体、いわゆる自治体であったり、省庁であったりという団体が林宏の情報を使えると。その団体全部にこの条例は行き渡るんですか。","respondent":"山田広報広聴課長","answer":"それとあわせて、先般朝日新聞で私どもが条例がつくるということで記事が載ったときに、東京都または国のほうからもぜひ欲しいということで、それから各自治体からもいっぱいお問い合わせがありまして、ご通知を差し上げているところですけれども。","voiceIndex":183,"id":"exchange-074"},{"speaker":"林（宏）委員","kind":"質問","question":"１回目の最後にします。そこで何らかのことで僕の情報が流れてサラ金でお金を借りられちゃったというようなときに、事が起きて、この条例が僕を守ってくれるということになりますか。その１条１条のことじゃなくて、この条例全体の考え方として、僕の権利を保護してくれるとうたっているわけで、か弱い私を保護してくれる条例になり得るんでしょうか。","respondent":"山田広報広聴課長","answer":"条文にかなりのセキュリティがあってどうこうは別にして、今のような事態が出てきた場合は、私どもはこの条例に基づいてその不正な情報取得者に対する措置という条例があるわけですから、こちらをもって措置をしてまいりたいというふうに考えてあります。","voiceIndex":185,"id":"exchange-075"},{"speaker":"土井委員","kind":"確認","question":"今の議論を聞いていると、先ほどから要するに本人確認情報という言葉自体の定義がいろいろされているんだけれども、はっきりしないもんだから何か新しいものが出てきたと思われちゃうんで、本人確認情報というのは、今言っているコード番号と情報を含めた全部のことでしょう。ですよね。そこははっきりしなきゃいかん。だからそれに答えるようにしてあげなきゃいけないんじゃないのと思うんですよ。","respondent":"田中情報システム課長","answer":"ちょっと技術的なところでご説明しますと、先ほど見ていただいたサーバーの中にはゲートウエイサーバーといって、既存の今の住民票３２万の区民の情報が入っている、５情報が入っている部分があります。","voiceIndex":191,"id":"exchange-076"},{"speaker":"土井委員","kind":"確認","question":"データがあります。これを確認情報と言うんですね。それでこの本人確認情報がセンターに集まってきますね。そこまでは全部集まっているんです。全国そこに集まっているんですね。そうすると例えば北海道から全国のやつ全部取れるわけですかというところを皆さん思うわけでしょ。今のさっきの話との兼ね合いで。","respondent":"冨田戸籍住民課長","answer":"もう既にご案内だと思いますけれども、９３事務、法律で決まっているわけですけど、その事務をやる上で本人の居住確認をする必要がある場合だけ、全国センターのほうに照会がかかります。","voiceIndex":193,"id":"exchange-077"},{"speaker":"土井委員","kind":"質問","question":"要するに北海道のあるまちからまちへ、私なら私が行って、００２番のやつを出してくださいと言ったときに、その００２番がどう回ってどうやってそこに００２番のデータが出てくるのかという仕組みをとりあえずみんなが理解しないことには、どこでどう漏れるのかという話にならないよという意味での質問だったと思うんですよ。だからそれにまずしっかり答えていただかないと前に進まない。","respondent":"田中情報システム課長、冨田戸籍住民課長","answer":"そうするとその住民票の窓口にある端末から、当然品川区のデータのあるサーバーにアクセスして、そこで住民票を書き出す、そこの端末にですね。サーバーにアクセスして。そういうことになります。こっちの情報を北海道に送る。広域交付で住民票を交付する。それとは別に、９３事務については全国センターのほうに本人確認情報だけの請求を行うという二本立てになっていて、アクセスの仕方も違っているです。","voiceIndex":195,"id":"exchange-078"},{"speaker":"土井委員","kind":"意見","question":"要するに私がどこかのまちへ行って「住民票ください」と言うときは、品川区のほうに直接問い合わせがあって、品川区から直接そのデータがそちらのほうに送られます。いいですね。それでいいですね、まず。ここに必要なのは、国が事務を行ったり、県が事務を行ったりするときに、年金支給がどうだとか、高齢者のあれがどうだとかというデータをここからいただきますよと。それでいいんですね。","respondent":"冨田戸籍住民課長","answer":"それは全国センターのほうに各自治体から本人確認情報を送って、そこがはめ込んで、そこに国等が照会をかける。照会があれば回答をする。それが一つですね。","voiceIndex":198,"id":"exchange-079"},{"speaker":"土井委員","kind":"質問","question":"となりますと、今言った品川区から都のほうに、ここはいろいろセキュリティを決めて専用回線的なというんですかね、専用回線と称する回線を通って、ここからセンターのほうにも同じような形で行きます。そのルートはわかる。横の、北海道の何々町から品川区に問い合わせがある、この回線は何ですか。","respondent":"冨田戸籍住民課長","answer":"同様に専用回線です。通信のやり方としては同じです。","voiceIndex":200,"id":"exchange-080"},{"speaker":"土井委員","kind":"意見","question":"回線ということは、どこを通るかわかりませんけども、全国どこ通ってきたって回線ありますからね。アメリカへ一たん行ってから来たって同じ回線でつながっている、そういうことなんだろうと思いますね。そういうことでしょ。回線というのは、専用回線と称する回線をどんどん伝わっていって向こうへつながっていると、こういうふうに解していいわけですよね。","respondent":"田中情報システム課長","answer":"インターネットのような形の回線ではありませんので、当然それぞれの端末から電話局なりに行って、そこから直接電話局間の専用回線が張られるという形になりますので。","voiceIndex":202,"id":"exchange-081"},{"speaker":"土井委員","kind":"質問","question":"中間でやめます。１回目は終わりにします。専用回線ということの意味合いも最終的にはお聞きをしなきゃいけないので、専用回線とは何ぞやというのをお伺いしたいわけです。タイムシェアをしているのか、周波数シェアをしているのか、何かでシェアをして使っているわけですよね。そこに問題点がないのかという話です。","respondent":"田中情報システム課長","answer":"住基ネットの専用回線は非常に特別なものですので、普通の回線のように、いろいろ共有して、シェアして、そこの一定の帯域をそれぞれ使っていくとかというのではなくて、これしか使わないという特別なネットワークを全国的に張ったということでご理解ください。","voiceIndex":204,"id":"exchange-082"},{"speaker":"嶋委員","kind":"質問・要望","question":"先ほど戸籍住民課長のほうから９月１３日付の一応区民がこうしてほしいとかあったということなんですが、今現在、区のほうはこのような情報というか、皆さんの要望はどこでまとめていらっしゃるのでしょうか。","respondent":"冨田戸籍住民課長","answer":"その臨時電話にかかってきた件数および広報広聴課のほうに寄せられた件数を合計したものが１，３１５件ということで、先週末の９月１３日現在の数字を先ほど申し上げたんですけれども、臨時電話につきましては９月２０日でおしまいですので。","voiceIndex":206,"id":"exchange-083"},{"speaker":"嶋委員","kind":"質問","question":"じゃ、区役所に電話すれば、そちらに回していただけるということでしょうか。","respondent":"冨田戸籍住民課長","answer":"住民からの問い合わせの中身がどの程度交換ができるかがあれなんですけれども、戸籍住民課の住民票係あるいは住基ネット担当のほうにつなげると思います。","voiceIndex":210,"id":"exchange-084"},{"speaker":"嶋委員","kind":"意見","question":"それと今の住民票は今までも第三者が見ることができて、例えば金銭貸借関係の書類を出せば、今まででも住民票が第三者が自由に見られていたと思うんです。その方たちというのは今後もそういうのは、利害関係がある方たちは住民票は見られると思うんですが、そこでやっぱりコードとかというのも全部わかってしまうのかどうか。","respondent":"冨田戸籍住民課長","answer":"私どもとしては、不当な請求でなければ、これは対応せざるを得ないということです。ただ、閲覧できる項目というのがありまして、これについては氏名、住所、性別、生年月日だけです。住民票コードは当然オープンにはしておりません。","voiceIndex":212,"id":"exchange-085"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味ではセキュリティがあるといっても、今までどおりこの４項目に関しては見られてしまうということは全然変わらないということですか。","respondent":"冨田戸籍住民課長","answer":"閲覧に関しては従来と特別変わりはございません。従来どおりです。","voiceIndex":214,"id":"exchange-086"},{"speaker":"嶋委員","kind":"質問","question":"もう一つ。今いろんな事情て住民票をそのまま置いて、虐待とかいろんな部分で分離しなくちゃいけない部分で、住民票をそのまま置いて、その地から離れるという部分、学校関係とかいろいろあると思いますが、その場合にネットワーク的なものがどういうふうになっていくのかなというのを教えていただけますでしょうか。","respondent":"冨田戸籍住民課長","answer":"今のお話は、基本的には公開が原則ですけれども、それはあくまでも一般的な段階ということですので、例えば特別な被害を及ぼされる恐れがある事態にあるとか、あるいは警察のほうから被害届が出ているとかいうような場合には、それはそれに応じた対応はしております。","voiceIndex":216,"id":"exchange-087"},{"speaker":"嶋委員","kind":"質問","question":"サービスを渡していく自治体として不参加のところはあと５年後１０年後というときに、いろんな意味で差が出てきて、今品川区の場合はこのまま続けていますけど、不参加のところというのは５年後１０年後というのはすごく差が出てきてしまって、住民へのサービスの質に差の出てきてしまうんではないかと思いますが、品川のほうは今つないでいるからいいんですけど。","respondent":"冨田戸籍住民課長","answer":"今年度につきましては住民票の写しをつけた形で申請、届け出をする事務、その際に住民票の写しにかえて、行政機関内で確認ができないということになりますので、従来どおり住民票の写しをつけて申請をするということになります。来年からは広域交付は当然受けられない。","voiceIndex":218,"id":"exchange-088"},{"speaker":"藤田委員","kind":"質問","question":"まだ今のところ条例に入る前に皆さん質問されていますので。そういうタイミング、もう少し慎重な姿勢があっても私はよかったんではないかなというふうに思って質疑の内容を聞いていまして思うんですけど、その辺もう一度、区民に対しても条例を出したわけですから、しっかりとした体制じゃないと、先ほどのような千何百件ものいろんな心配がどんどんと問い合わせが来ると。これからも恐らく来ると思います。","respondent":"山田広報広聴課長","answer":"現在国会の中で継続審議ということになっていて、１０月の国会でこれも審議されるというふうに新聞報道にありました。最近きょうの新聞情報では、経済国会ということを最優先として比較的個人情報保護法、有事法案等、また継続になるのではないかみたいな一部報道もあります。","voiceIndex":220,"id":"exchange-089"},{"speaker":"藤田委員","kind":"意見","question":"これはあくまでも品川区の考えであって、他の自治体で例えば不正があった場合、そこは及ばないわけですよね。そういう面で今私がまず法律をつくるべきじゃないかということを私は言いたいわけですね。過料等も規定していますけどね。その辺を幾らつくっても及ばないことについてはやっぱり慎重に考えていくところじゃないかなと私はそういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":222,"id":"exchange-090"},{"speaker":"土井委員","kind":"確認","question":"これの関係で、このネットが特にセンターに集めていくという部分がなぜ必要なのかというところにかかわるんです。それとこれと何関係あるんだと言われるといろいろあるんですけども、それは確認したいと思うんですけれども、今までだって年金の何とかの調査のために、どういう人がどれだけ対象の方でいらっしゃるかというのを国が把握をしなきゃならなかった。現にしていたはずですね。今までどうしていたか。","respondent":"冨田戸籍住民課長","answer":"法施行後はこの添付が不要になる。そのかわり担当セクションが全国センターのほうに照会をかけて本人確認をするというのが今回の一つの大きな目的です。","voiceIndex":223,"id":"exchange-091"},{"speaker":"土井委員","kind":"確認","question":"要するに個別の区民である法人も含めた皆さんが問い合わせをしたときに、それに対する答えは、今までは住民票を添付をするという形でやっていましたよ。だから要らないよということ。ナンバーさえ言えばいいよと。書かせるんだろうけどね。いいよと、確認はしますよと、こういう形になります。国等からのやつはどうなるんですか。国等で例えばいろんなのは今まで問い合わせはなかったんですか。","respondent":"冨田戸籍住民課長","answer":"これは法律に基づいた照会ですので、それなりの回答はさせてもらっていますけれども、基本的には今回９３事務と言われておりますのは、資格を取得する事務、あるいは年金とかの福利厚生事務について９３事務について行ったものです。","voiceIndex":225,"id":"exchange-092"},{"speaker":"土井委員","kind":"意見","question":"７０、六十幾つになったらやめようやと、この間で徴兵やろうやというようなデータを集めたいと仮に国が思って照会をしたら出てくるような仕組みにも使えるわけですよ。ですよね。その９３事務というのは今限られているわけだけども、これは今言った認証にかかわる問題なんだろうけれども、少なくとも今はそういう形での問い合わせは応じないことになっているんですよねということ。","respondent":"山田広報広聴課長","answer":"通常これ言われているのが、国の行政機関が利用するのが８割、それからあと都道府県、それから市区町村も使えるという部分に広がっているもので、別表でそれぞれ定めておりますので、すべて国の機関だけではないということだけはご理解いただきたいと思います。","voiceIndex":229,"id":"exchange-093"},{"speaker":"林（宏）委員","kind":"意見","question":"品川区は大井町でサービスセンター、それから各地域センターでいろいろなものが取れるように今なっていますよね。あるいは証明をする。その辺の区として、今度は外じゃなくて、内側として区としては、その辺のいわゆる先ほど来言う回線の部分、それから職員のセキュリティの部分はどういうふうになっていますか。","respondent":"田中情報システム課長","answer":"そういうセキュリティになっておりますが、住基ネットの来年８月以降の部分については、地域センターでも取れるようにするのかどうかということについてはまだ課題になっておりまして、今検討中ということです。","voiceIndex":231,"id":"exchange-094"},{"speaker":"林（宏）委員","kind":"確認","question":"そうするとそれは現段階では決定していないという部分なわけですね。どっちにするか。それからもう１点、番号が来ているわけですね。品川区の場合は既に、一人ひとりに。区民じゃない人が多いから知らないでしょうけど。品川区の場合を言っているわけです。それを確認しておかないと。届いている。その番号を忘れちゃったらどうするの。だれが責任を持ってくれるの。","respondent":"冨田戸籍住民課長","answer":"住民票コード番号を忘れてしまった場合は、役所のほうにおいでいただいて、住民票の写しを取っていただきます。そこにその際に住民票コードつきの住民票の写しを。","voiceIndex":233,"id":"exchange-095"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、番号って一人歩きしそうじゃないですか。非常に今の手続きで番号を知りうるとすれば。","respondent":"冨田戸籍住民課長","answer":"委任状の場合もあり得るんですけれども、その場合は委任状、委任された方、ご本人の確認をする。同じようにパスポート、あるいは本人を確認できるものですね。ご本人と、それから委任された方自身の本人確認をします。","voiceIndex":237,"id":"exchange-096"},{"speaker":"林（宏）委員","kind":"確認","question":"いわゆるさっきから言っている林宏という個人の権利を守ってくれるといういろんなことの確認をしてきたけど、林宏の何としても番号を知りたい、その番号を知ることによって何か利益を得られるものがあるということになって、林宏の番号を知ろうと思ったら知れるわけだよね。","respondent":"冨田戸籍住民課長","answer":"なおかつ、通常は住民票コードのないものを発行する。ただしどうしてもということですので、使い道とかそのあたりはお伺いすることになりますけれども、無原則にコード番号つきのものを出すということにはなっておりません。","voiceIndex":239,"id":"exchange-097"},{"speaker":"林（宏）委員","kind":"確認","question":"今のところなんだけど、それぞれの個人番号を知りうる手段というのは、非常にあやふやだと思います。一切番号ついていませんか。転居届は番号ついてない。要するに今ちょっとこだわっているのは、番号が外へ出ていく恐れがどこであるかというのを確認したいんだけど。","respondent":"冨田戸籍住民課長、伊藤委員長","answer":"これ記載しないと、行った先で住民票コードの入力ができないということになりますので、転出証明書についてはコード番号がつきます。これは正副委員長の提案ですが、一たんきょうは打ち切りまして、あしたの総務委員会でも引き続き審議をして、当然共産党からの修正案も出ておりますので。","voiceIndex":241,"id":"exchange-098"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":65977,"voices":247}},{"id":"h14-20020925-6","meetingId":"h14-cm09","date":"2002年9月25日","dateIso":"2002-09-25","committee":"区民委員会","time":"午前１０時０５分～午後２時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"件数が２０％ダウンという話がありましたけれども、ということは、借りる人が少なくなったということは、景気がよくなったということでしょうか。","respondent":"市川産業振興課長","answer":"この半年ぐらいの経緯で説明をしますと、今年の３月までは、私どもが取り扱っている区の窓口の制度融資をとってみますと、前年に比べてプラスの傾向でずっと推移をしてまいりました。","voiceIndex":7,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"今、金融機関に行って話を聞きますと、倒産はどうですか、ある銀行に行くと、「うちの関係した中で、今月は何個ぐらいありましたよ」などという話を聞くんですけれども、その中で信用保証協会の保証をつけて貸しているところが倒産しているんですね。そうすると、ますます借りられなくなるのかなという気がするんですけれども、その辺の状況はつかまえているんでしょうか。","respondent":"市川産業振興課長","answer":"今お話がございました、信用保証を受けているところの倒産が目立つというのは、こげつきを信用保証協会がかわりに金融機関に弁済するという代位弁済の率がここのところ上がってきているということがよく報道されておりますけれども、この一番大きな原因は。","voiceIndex":9,"id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"これは一部だけのことならいいんだけれども、今の話を聞いていると、体力があって、模様眺めをしているならいいけれども、これはどうにもならない、区内の小企業だと借りらなれいというふうに私などは思うんですが、サラ金相談といいますか、そちらのほうはどんな状況ですか。","respondent":"市川産業振興課長","answer":"一時詐欺まがいのことが続いた、２年ぐらい前の時期ですけれども、東京都のほうも随分敏感になりまして、定期的に相談状況の報告を求められたときがあるんですが、そういう動きも今のところございません。","voiceIndex":11,"id":"exchange-003"},{"speaker":"本田委員","kind":"質問・要望","question":"今の景気に対する危機感というのがいろいろな面で見えて、政府がどういう手を打つのかということが注目されているような状況ですね。ですから、１１月から始まるこの年末の融資対策につきましても、枠の拡大を図って、できるだけ借りやすいように工夫されているのは歓迎しますし、そういう実態というものをぜひつかんでやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それを５００万円１本にしてあげれば、１０万円の返済でやっていけるわけです。これをなぜ考えてくれないのかなというのが疑問なんですけれども、前にお聞きしたときに、保証料の補助の問題が絡んでくるということを言れたことがあるんですが、その辺に関しては、そこで新たな規定、保証料の補助を減らせば対応できるのではないかなと思うんですけれども、その辺のご見解はいかがでしょうか。","respondent":"市川産業振興課長","answer":"それと、予算が、その辺混乱なく認めていただけるかどうかということもあります。そこのところをクリアできない問題ではないとは思ってありますので、さらに検討を進めていきたいと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ考えていただきたいと思います。保証料に関しても、保証料の補助をもらうから借りるのではなくて、資金を使いたいということがメインですから、そこの補助額が減ったにしても、利用することによっての資金回転、商店でしたら、商品を仕入れて、利益を上げていくという形で、それが活性化していくのではないかと思うので、ぜひご検討をお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"三上委員","kind":"質問・要望","question":"比較的低いほうということであるので、それはよかったと思います。こういった状況下にあって、借りる側というのを極力ゼロに近い金利であればあるほどありがたいというのは、だれが考えても言えることです。それだけに、どこのところが適当なのかということになると、難しい判断になるでしょうけれども、それによっては金利だけで考えられる、そういった方向に考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"今度のノーレジ袋運動はうまくまとまっていると思います。これは５日からですよね。何か我々委員会の人たちに対してセレモニーはないんですか。","respondent":"市川産業振興課長","answer":"形をとっているというか、そういう方式をとってやるわけですけれども、１０月５日にそれぞれの商店街で実施をされることになるんですが、そのオープニングの仕方も、それぞれの商店街の状況に応じてやっていただくということで、今のところ１０月５日にお話がある商店街は。","voiceIndex":25,"id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"私も５日に何かあるんだろうと体をあけて待っているんです。実は戸越銀座銀六にもエコ回収機が入っているんですけれども、銀六商店街にも置いているんですが、それとの整合性がどんな形になっているのか。","respondent":"市川産業振興課長","answer":"ここ２年近くになりますけれども、あれはペットボトルだけを粉砕する機械ですが、今回は、先ほど環境課長から説明いたしましたように、ペットボトルと飲料用の空き缶回収をワンセットで置くものですが、当然、銀六商店街、新しい機械が入った時点で。","voiceIndex":27,"id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"そのリース料について金額が幾らになるのか、それをお知らせいただきたいと思います。ですから、品川区はそれについてはどのくらい補助をするのか、多少の補助では、これは考えたら、ちょっと手を出せないなという感じがするんですが、そこらあたりの見解を聞いておきたい。車の通りがあるということも考えたら、そういったところに懸垂幕を考えられると思うんですけれども、どうなんでしょうか。","respondent":"市川産業振興課長、金井環境課長","answer":"私のほうから、最初の２点について説明をします。回収機のレンタル費用ですが、結果的にはペットボトルと空き缶を入れまして、１カ月１３万２，０００円ぐらいの金額です。これは業者が当初示した金額の約半額です。中原街道、保健所のことかと思いますけれども、私どもが考えておりましたのは、基本的にちゃんとレールといいますか、あるところをいろいろ探してやってきたわけですが、保健所にはそういったものがなかったような気がするんですが。","voiceIndex":29,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"レンタル料、私も高いということははっきり言ってきて、これがネックになるでしょうということを言われてきましたけれども、そういう意味では、金額が１３万円ということで、随分安くしたものだなと感じました。どうせやるなら、そこまでやってもらいたい、これはお願いしておきたいと思います。保健所のＰＲでも当然すべきものというのはたくさんあるんじゃないかと私は思うんです。とうでしょうか。","respondent":"金井環境課長","answer":"たしか懸垂幕が設置するようにはなっていないと思いますけれども、委員のご意見につきましては、保健高齢事業部に十分お伝えをします。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"商店街の関係で、１０５の商店街のうち２３の商店街しか入れなかった状況、これから取り組みということもあるんですけれども、現在の段階で商店街が取り組まなかった理由が分かれば教えてもらえませんか。","respondent":"市川産業振興課長","answer":"方法論そのものもよく理解されていないということがございまして、先ほどの三上委員の説明のときにも申し上げたんですが、まず第一陣をスタートさせて、一歩踏み出していいかどうか、ちゅうちょしている商店街に、第一陣のスタートの様を見ていただいて。","voiceIndex":34,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"意見","question":"同じ商店街の中でやっていて、コインがもらえる店、もらえない店、さっきのステッカーはありますけれども、凄く難しい問題も絡んでくるんじゃないかと思うんですが、それが１点。非常におかしいなという気がするんですけれども、スーパーとか、コンビニエンスストアの対応というのは、まだ結論は出ないかもしれないんですけれども、今後どういうふうに考えていくのか、その２点をお願いいたします。","respondent":"市川産業振興課長","answer":"スーパーですでに実施をなさっているところは、最終的には何らかの形でレジ袋に対する消費者の意識の喚起をしていただくことに同調していただけるならば、それで一つはよろしいかと思うんですけれども、まだそういうことに取り組んでいない事業所については。","voiceIndex":36,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"確かにコンビニエンスストアというのは、チェーン店だから非常に難しいということは分かりますけれども、その辺努力していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"自然環境調査ということですけれども、代表的なところということですけれども、戸越公園の隣に文部科学省の国文学研究資料館があるんですけれども、あそこは自然が残っていて、きゅりあんからも行けるんですけれども、公園としてはまだ開放されていないですけれども、そういうところは調査に入っていないんですか。","respondent":"金井環境課長","answer":"基本的に区の公園が一番利用しやすいということと、調査がしやすいということが１点あります。","voiceIndex":44,"id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"調査目的に、ヤモリ、イシガメ、トカゲ、モグラとありますが、ヘビも相当数いるんですね。戸越公園にはおそらくいないと思いますけれども、そういう意味では、自然環境を調査するなら、そこを抜かすというのは、私はどうしても不自然が気がするんです。中間報告ですから、今からでも追加できると思います。やる気は全然ないということですか。","respondent":"金井環境課長","answer":"国のほうでもしあれでしたら、ちょっとお話を聞きまして、いいということであれば、費用の問題もありますけれども、その辺が可能であれば、検討をさせていただきたいと思います。","voiceIndex":46,"id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"検討をしてもらうようにお願いします。あそこにはいろいろな小動物がいると思うんです。この機会ですから、なおさら調査をしていただければと思うんです。なかなか調査の機会はないと思いますので、そういう意味では、ひとつよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-017"},{"speaker":"三上委員","kind":"質問","question":"今全国的に問題になってきているというのは、外来種の動植物、動物もあるでしょうけれども、植物的な部分が、動物というのは、魚とか、ペットが放し飼いされるということでよく問題になっているのがありますけれども、こういうようなものについての調査をする考え方はないんでしょうか。だから、そういった面の調査というものもやるべきだと私は思うんですけれども、どうなんでしょうか。","respondent":"金井環境課長","answer":"そうしたことも含めて、まとめの中で検討をさせていただきたいと思いますが、基本的には植物調査で分かるはずです。","voiceIndex":49,"id":"exchange-018"},{"speaker":"三上委員","kind":"質問・要望","question":"特にセアカゴケグモという、そういうような人間の生命にも影響するようなものもあるということの実態というのは調べたほうが、区民の皆さんに注意を促すという、お知らせしていくということがあってもいいと思いますので、そういったあたりもきちっとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"直接自然環境調査に含まれないかもしれないんですけれども、魚介類調査の中で、目黒川、勝島運河、京浜運河、天王洲運河でやられている中で、水質的なものというのは、別の部分の調査をしているから、今回は同時に並行してやったということはないわけですか。","respondent":"金井環境課長","answer":"水質調査は、私どものほうで、運河も含めて、目黒川、立会川も含めて年間６回ぐらい実施をしております。これは別個にきちっとやっておりますので、これはあくまでも魚介類の調査です。","voiceIndex":52,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"水質の汚染と、こういう魚介の関係というのは結びつけて考えていくのかなと思います。前に新聞に出ていたんですが、目黒川にエイが上がっていたんです。その新聞を偶然見たんですけれども、そういう状況からしても、水質がきれいになっているかどうか、一緒にできなかったのかなと思ったんです。","respondent":"金井環境課長","answer":"川鵜がいたり、魚が上流まで上がってきております。夏が若干ＢＯＤが高くなる可能性がありますけれども、ボラ、ウグイなども、これは川の魚ですけれども、そういった魚もいるようですので、かなり水質的にはよくなってきている状況にあります。","voiceIndex":54,"id":"exchange-021"},{"speaker":"三上委員","kind":"質問","question":"職員に聞いて、初めてここだと言って、分かった。庁舎内だけでもそれをやるのに、職員の皆さんは分かっているかわからないけれども、それだったらそれで、役所の中でやっているということをなぜ公にできないんでしょうか。そこのところが私は不思議でしようがないんだけれども、環境清掃事業部でぜひこれはやってもらいたい。廃乾電池の処理だってやっていたわけでしょう。","respondent":"宍戸ＩＳＯ担当課長","answer":"収入役室の廃乾電池の回収の件ですが、環境全般をある程度取りまとめている部署といたしまして、収入役室のほうと、今のご意見を踏まえて話し合いたいと思います。","voiceIndex":63,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"清掃の雇上車両に関して、まだ占めているのか、大分減ってきているのか、その辺も教えてもらえますか。","respondent":"中山清掃リサイクル課長","answer":"大型の車両については技術的にＣＮＧが難しいと言われておりますが、一般的に走っている２ｔ車以下のものについては、ほぼ半数を超えて、今年度中にも七、八割がＬＰＧ、もしくはＣＮＧという形の低公害車化されるというふうに伺っております。","voiceIndex":67,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"本会議の中で松澤議員のほうからも質問が出ておりましたけれども、区としてのＤＰＦ車両の助成という問題は、確かに東京都は今年度限りで終わってしまいますけれども、終わってしまったって、来年の１０月に使えなくなってしまうのをどう考えていくのか、助成も考えるべきではないかという思いがあるんですけれども、と同時に、東京都に対しても。","respondent":"金井環境課長","answer":"基本的には前の年までにある程度予算措置もされて、きちっとやるというような計画がなされているような話もお聞きをしますし、また同じような話になるんですが、ご要望の趣旨はよく分かると思うんですけれども、大変短い期間の中でそういったものを考えて。","voiceIndex":69,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東京都が年度内に終わってしまうと、さあ、どうしようかというときに、逆に、４分１の助成ができるとか、それに対する新たな特別な融資制度みたいなものを考えることができないのかなということを、今日は要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"}]},{"id":"topic-02","title":"平成１４年請願第１６号、都市計画税の軽減措置の継続につき意見書の提出を求める請願および平成１４年請願第１７号","agenda":"平成１４年請願第１６号、都市計画税の軽減措置の継続につき意見書の提出を求める請願および平成１４年請願第１７号","exchanges":[{"speaker":"本田委員","kind":"質問","question":"土のう利用ですけれども、防災無線でお知らせがあったり、テロップで放映されて、あらかじめ状況が分かって、どの辺に水が出るかというのはみんな知っていますから、ここを止めておきたいということで、立会川などを見まして、土のうが大変役に立ったようですが、中にはどこから土のうを持ってくればいいのか、どういうふうにすればいいのかわからないという住民もあったようでして、その辺円滑に活用して。","respondent":"久保田防災課長","answer":"今後は広報車については、土のうの場所等も示したような形で、より分かりやすいような周知の仕方をやっていきたいというふうに考えております。","voiceIndex":91,"id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"土のうが足りないとか、なくなっているとか、そういうことはないんですか。ちゃんと間に合うんですか。必要だと言った人のところに土のうがいくような準備はされているんですか。","respondent":"久保田防災課長","answer":"それで何度か補充しております。新たに砂を買いまして、土木事務所のほうで土のう袋をつくりまして、従来からあった土のう置き場のほうにこれを補充しているという活動を続けております。","voiceIndex":93,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"これは特別区民税ですよね。そのほかに東京都の都市計画税とか、そういう東京都でやっている都税三税とか、また、国の所得税とかという、そういう減免とかということはないんですか。","respondent":"松崎税務課長","answer":"基本的には申請主義ですので、今回は品川区の場合は例外で、申請ではなくて、職権をもって１０４件と承知していますが、おそらく相談をされて、申請をすれば、減免の対象にしていただけるというふうには聞いてあります。","voiceIndex":99,"id":"exchange-028"},{"speaker":"三上委員","kind":"確認","question":"申請主義というのはよくわからないけれども、今回品川区がやった例外というのが、それを普通やってくれればもっとありがたいと区民から喜ばれるのかなと思うんです。品川区からお知らせがいっているわけでしょう。そうすると、国と東京都もそのような措置というのがとられている、それは確認してもらったわけです。そういったことの連携というのをやってくれるとありがたいと思うんですけれども。","respondent":"松崎税務課長","answer":"ただ、平成１１年のときももっと大きな規模の水害がございまして、そのときも都税事務所とは連携をとりつつ、減免については適正な処置をしてきている経過がありますので、今回も同様にやらせていただいております。","voiceIndex":101,"id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"ご相談ください」という、国のほうはどうか、そういうのをやってくれれば、区民に密着した品川区役所という評価を受けるんじゃないかと思うんですけれども、今後そこらあたりも、件数的に何万件も何千件もあるわけじゃないですから、こちらから、こうしなさいということでなくて、東京都も減免が行われることに決定しましたというようなことが１行でも書いてあげられる、ですから。","respondent":"松崎税務課長","answer":"今後私どもで発送する封書の中に、都税なり、国のそういうようなことを一言でも書けるようなものを入れていきたいというふうに考えております。","voiceIndex":103,"id":"exchange-030"},{"speaker":"三上委員","kind":"提案","question":"すでにきのう終わって、結論が出ているから、発言をしていいのかどうかわかりませんけれども、全国的にということだったんですが、きのうの今日ですから無理だというのは分かりましたけれども、東京都内の自治体ではそういったことは現実に条例提案していないところはないということで、理解していいんですね。","respondent":"太田保険年金課長","answer":"そういうことです。","voiceIndex":108,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この中で、徳島のＡＷＡおんなあきんど塾事業は説明を聞くという形ですか。それとも先方で、今日いただいた資料の中でもメンバーの方が入っておりましたけれども、そういう方たちともお会いするという形ができているんですか。","respondent":"事務局","answer":"ただ、今のところはまだいい返事をいただいていないので、向こうの職員から説明を受けるという形になるのが基本線かと考えています。","voiceIndex":129,"id":"exchange-032"},{"speaker":"三上委員","kind":"意見","question":"方向ということになるのかどうかわかりませんけれども、私の経験上から言ったときには、１人１項目とかというテーマを決めると、そのテーマについての考え方というのはいろいろあるわけですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-033"},{"speaker":"本多副委員長","kind":"意見","question":"できれば、そういった方向がいいかなと思うんです。したがって、後で正副委員長に一任というのは必要ないんじゃないか。まとめというよりも、議事録をそのまま報告書という扱いにして、編集という意味では、文言については、当然報告書ということは整理はしますけれども、発言した部分については、そのままを報告書に出すのがいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"たしかおととしの区民委員会は、今本多副委員長がおっしゃったような形でやったと思いました。議事録をそのまま使って、後のまとめは正副委員長でやっても、前文を付けるとか、写真を入れるとか、それでやったと思ったんです。それの形のほうがいいと思います。ですから、委員会の中で皆さんからコメントを出してもらって、それでできるんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34999,"voices":139}},{"id":"h14-20020925-7","meetingId":"h14-cm09","date":"2002年9月25日","dateIso":"2002-09-25","committee":"厚生委員会","time":"午前１０時０３分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１点お伺いしますが、床面積が大分大きくなったと思うんですけれども、それで定員の比較を見ると、１２名増えるということですが、床面積の増えた分にこの１２名というのは見合っている数字だとお考えでしょうか。","respondent":"金子保育課長","answer":"例えば、ホール等ももちろん保育室とは認可上申請できませんけれども、ホールあるいはホールの下の廊下等についても十分子どもたちの食事するスペース、あるいは午睡するスペースとして活用できますので、数字以上には保育として使えるスペースは多くなりますが。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと何点か聞きたいんですけども、一つは、プールというのは何かここに書いてないんですけれども、大分子どもたちがいっぱいになるんですけども、プールというのはどういうふうに考えておられるんでしょうか。","respondent":"金子保育課長","answer":"第１点目のプールのお尋ねですけれども、固定したプールを置いてある保育園が非常に多いですけれども、固定したプールですと、それ以外の季節、プールは６月ないし７月から８月いっぱいぐらい標準的に扱っておりますけれども、それ以外の時期にはあまり使い道がないということで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"プールのところは簡易プールで、この園庭のところに置くようになるんですか。大きさというのは大体どんな感じになるんでしょうか。","respondent":"金子保育課長","answer":"プールの大きさですけれども、今現在まだ確定はしておりませんが、幼児用、乳児用を分けて、それぞれのところに置いていこうというふうに考えておりますので、園庭の部分もなるたけ広く使えるような格好で配置していこうというふうに工夫していきたいと考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"もう一点なんですけども、延長保育のところの場所なんですけども、今日も朝ＮＨＫかなんかで、夜の保育のをやっていたんですけども、この環境、延長保育、今回は１０時までなんですけど、なかなか夜まで預かっていると、子どもたちのところも家庭とやっぱりちょっと違うようになって落ち着きがないとかというふうに言われることがあるんですけども、ここのところで。","respondent":"金子保育課長","answer":"延長夜間保育の運用の仕方のお尋ねですが、とりあえず延長保育室のスペースとして、この畳のところを考えておりますが、人数によりまして、例えば延長の時間帯、７時半ぐらいまでですと結構な人数が想定されますし、それ以降、８時半なり１０時というのは。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"最後なんですけど、今回、実施予定の新たな特別保育事業のところで、１０時までの延長と病後時、休日と、そういう特別保育もやるようになっていますけども、全体として保育、駅型の保育園ですから、いろいろな利用法にこたえると、そういう内容になってくるかと思うんですけども、基本的にはそういう方向でずっと保育を目指していくのか。","respondent":"金子保育課長","answer":"西大井保育園の今後の運営の展望というようなお尋ねかと思いますけれども、先ほども申し上げましたとおり、私どもとしましては、非常に利便性の高いＪＲの駅の近くということで利用者の方にも利用しやすいんではないかということで。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"厨房等をしっかり用意してあるんですけども、これからのいわゆる保育所の給食等については、外へというような考え方もあろうかと思うんだけども、ここでこういうふうなしっかりしたものをつくってきているという状況は、どういうふうに、いろんな保育所があるんですけども、先取りしていくよというような考え方で絵をつくったらよかったのかなというような思いがあるんだけど。","respondent":"金子保育課長","answer":"ここの部分につきましては、既存の認可保育園がありましたので、第一の考え方としては、認可保育園を改築するということなので移転させたというふうに考えておりますが、認証保育所につきましても、選択肢の一つとしては考えましたが。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"その辺がちょっと変えられるものなら、もう少し配慮していただければなという思いがあるのと、それから、認証保育所というのが新たに東京都でいろいろつくられてきていて、どっちがいいとか、そういうふうなことが出てこようかと思うんだけど、一つ改築します、新しくしますというときが、また逆にチャンスだったのかなというような思いがするんで。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、まず第１点の定員の部分ですけれども、私どもとしては、低年齢児をできるだけ拡大する方向で考えていったわけですけれども、建物の設計していく段階での制約というところから、特に南側が、ちょうど左の斜め下のほうが図面上南になるんですけれども。","voiceIndex":17,"id":"exchange-007"},{"speaker":"築舘委員","kind":"質問・要望","question":"３点お伺いしたいと思います。休日保育の、既に２園やっているということですけど、商店街の方とか、そういう方が多いかなと思うんですが、どういった方が利用しているのかということと、今後ここでやる場合に、駅前だということもあって、需要が増えるのかどうかという、先ほどのお話もありましたけども、その辺の見通しをお聞かせいただきたいということが１点。","respondent":"金子保育課長","answer":"それから砂場に関しては、ご指摘のとおりの問題があると思いまして、私どものほうでも、いろいろ新しい考え方も取り入れながら努力しているんですけども、一般的には使っていない時間帯については、シートをかぶせて動物のふんから守る等々の対策を施しておりますので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"築舘委員","kind":"質問","question":"地区公園というのが約６００平方メートル、保育園に隣接というか、くっついてありますけども、これはどういった公園になるんですか。担当外になっちゃいますけど、保育園とうまく利用できるような形の公園になっているのかどうかということをお聞かせください。","respondent":"金子保育課長","answer":"１枚目の裏のほうの地区公園と書いてあるところですけれども、公園については、私どもも散歩等々で十分利用していくものというふうに運用上考えておりますが、園庭とこの公園の地盤のレベルが１メートルほど差があるんですね。","voiceIndex":21,"id":"exchange-009"},{"speaker":"金高委員","kind":"質問・要望","question":"この図の中で、正面の歩道の部分がありますけども、これは地図で見ると、歩道のメートル数がわかりますでしょうか。ちょっと所管が違うような感じがするんですけれども、わかりましたらば。","respondent":"金子保育課長","answer":"ここの部分につきましては、道路との境界から５メートルセットバックして設定しているというのがもともとのベースの設定でございまして、まず樹木が立っている部分というのが、その手前を含めて歩行者が通行できる部分で。","voiceIndex":23,"id":"exchange-010"},{"speaker":"金高委員","kind":"意見","question":"そうしますと、保育所のほうの駐車場のスペースが１台分だけあるわけですけれども、先ほどの説明ですと、いろいろと食材とかそういう搬入の場所でもあるという説明ですけども、ここで言いますと、相当歩道が広くて、そこから入っていく、なおかつここに樹木があるので、ここの死角になりはしないかということと、それからここが出入口ということですので。","respondent":"金子保育課長","answer":"植栽につきましては、今想定でかかれている部分ですので、死角がなるたけできないような格好で、これについても意見を言っていきたいというふうに考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"辻副委員長","kind":"質問・要望","question":"そこの今の駐車場の車路の部分で、よく車が出てくるときに、ブザーみたいなのが鳴るじゃないですか。車が出てくるときにね。だから、そのときにブーブー、出るあのブザーというのは、警報させるためにやるんだけど、すぐ直近が０歳児の部屋なんで、その辺と今、金高委員が話したように、歩行者の安全を確保するための、どういう方策があるかというのをよく検討して。これは要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"ヘリカルコースについては区民だけなんですか、区に在勤の人は難しいのかな。こちらに関係しているよというような人たちも、例えば職場でこういうことをやらせたいとか、中・小・零細企業でそういうところがあると思うんですけど、そういう形で検診みたいな形をとらせたいというような考え方を持った場合は、できるのかできないのか。","respondent":"田中健康課長","answer":"私どもの区民健診、がん検診、一応区内在住の方です。在勤等の方は、職場でいわゆる職場検診として受けられる方もいらっしゃると思うんですが、私どもが対象としておりますのは、今のところ区内在住の方に基本的にさせていただいてあります。","voiceIndex":34,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと何点か伺いますけども。それともう一点が、喫煙者とハイリスク者というのは、ハイリスク者というのはどういうふうに規定をしておられるのか、その点をちょっとお伺いしたいと思います。","respondent":"田中健康課長","answer":"現在の見込みですけども、肺がん検診者の0.５％から１割というあたりが今回、１０月からですから半年なので、今年度中は一応２７０人程度の方を見込んで予算を組み立ててあります。それからもう一点、ハイリスク者ですが、いわゆる喫煙指数ということがあります。","voiceIndex":36,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"喫煙者とハイリスク者というところなんですけど、そこのところがちょっと何かまだよくわからないんですけど、よく言われているのが、本人もそうなんだけど、家族とか、いわゆる副流煙の影響というのがよく言われているんですけど、このハイリスク者、希望により喀痰検査というふうになっているんですけど、例えば本人が希望すればいいのか、それとも一定基準があるのか。","respondent":"田中健康課長","answer":"５，７００名程度の方が昨年度に実績で１年間に受けていただいておりますので、それの１割の半期分という考え方です。それから、ハイリスク者という言い方というのは、医学的な言い方を含めまして、喫煙数の６００以上の方ということで一応言われているそうです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"築舘委員","kind":"質問","question":"今までは一般コースで精密検査を受けて、その後にヘリカルコースというんですか、ヘリカルＣＴ検査というのを受けられたわけですかね。それで、その受けられている方というのがいると思うんですけど、あえて今回ヘリカルコースというふうにしたのは、どういうふうな意味ですか。","respondent":"田中健康課長","answer":"肺がん検診、先ほど申しましたが、失礼しました、数字がちょっと間違っておりました。平成１３年度は５，１８２人の方が受けられてあります。このうち、精密に流れる方が４７６人でございまして、この段階でヘリカルＣＴ検査を今までも受けていただいている方があります。","voiceIndex":42,"id":"exchange-016"},{"speaker":"築舘委員","kind":"質問","question":"そういった意味では、ヘリカルＣＴ検査で大体すべてわかるということで、それでその後、異常だなといったら病院に行って、より精密なしっかりした検査を受けるということでよろしいんですか。","respondent":"田中健康課長","answer":"これでほんとうに所見的な結果が出ましたら、そういう意味ではより早く医療機関にということで、そういうご案内も差し上げていただくように、今回お話し合いをしています。","voiceIndex":44,"id":"exchange-017"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ただ、こういう形でいくと、有料無料というか、その辺が区負担分というのがあるときに、ほんとうに真に必要な人と、それからある部分アバウトに、だから、有料ですからいいんですけど、それでもある部分負担が出てくるわけですから、そういうことから考えると、ある部分、問診というか、最初の段階でいきなり問診だけであなたはいいんじゃないですかというわけにはいかないから。","respondent":"田中健康課長","answer":"ただ単にマンモグラフィー、ヘリカルという形で、こういうコースをつくれたことが、今後がん検診全体をやはり精査する一つの機会だというふうに受けとめてありますので、また、その辺は次のステップを踏みたいというふうに考えてあります。","voiceIndex":46,"id":"exchange-018"},{"speaker":"辻副委員長","kind":"意見","question":"要するに、何でも受けてみればいいやというんじゃなくて、０次というか、早期発見よりももう一つ前のいき方というもののあり方というのは、これは大きくこれから課題になるかと思うので、ひとつよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-019"},{"speaker":"金高委員","kind":"質問","question":"本人負担のところでちょっとお伺いしたいんですけども、一般コースとヘリカルコース、それぞれ有料、無料になっていまして、１年の間に両方受診することはできないというふうになっておりますけれども、例えば一般コースの場合ですと、区民健診の通知が来て、行きましたといったときに、医師会のほうに行けば医師会でもってすべてできるんでしょうけど、例えば普通の民間の病院に行って受診した場合には。","respondent":"田中健康課長","answer":"その内容ですけども、区民健診とそれぞれ胃がん、肺がん等々の検診、皆やり方、場所が違います。ですから、私どもとしましては、区民健診も年１回、がん検診それぞれについても年１回区としては検診のご用意をしておりますというのが基本的な考え方です。","voiceIndex":49,"id":"exchange-020"},{"speaker":"金高委員","kind":"意見","question":"例えば私の場合ですと、４月が誕生日ですので、４月に案内が来るんで、私は６月にいつも行っている、ずっと利用している民間の病院で全部チェックをしているわけなんですね。例えばこれが１０月に来ましたと。もし、これから私自身が１１月に行きたいといった場合に、申し込みしますと、医師会のほうは全然私のデータがないわけですね。自分でもって、個人で金を払って。そのときの費用とか何かはどうなのか。","respondent":"田中健康課長","answer":"ですから、こちらに行かれて、もう一度がん検診のヘリカルコースをというのは、年に２回ということで、がん検診が２回のバッティングをするですので。","voiceIndex":51,"id":"exchange-021"},{"speaker":"金高委員","kind":"質問","question":"内容がちょっと違いますが、先ほどの喫煙者とハイリスク者についてということで、先ほどの説明で、喫煙指数というふうに言っておりましたけど、ちょっと私たばこを吸わないもので、その辺の指数の見方、例えば１日何本か、あるいは何箱かという話なんですけど、大体具体的な、先ほど６００以上が実際にハイリスク者に入るということなんですけど、アバウトでいいんですけども、大体１箱、あるいは２箱。","respondent":"天野品川区保健所長","answer":"胃の検診は民間でお受けになって、医師会でお受けになったのと、ちょっと違うと思うんですけれども、医師会でお受けになれば、そこで区民健診で無料でできますけど、民間だと、やはり検査、そこでお金を払わなくてはできないわけですよね、胃の検診。","voiceIndex":53,"id":"exchange-022"},{"speaker":"山路委員","kind":"質問・要望","question":"もう一点は、現在吸っている人を対象に４００とか６００という数だと思うんですよね。過去に３０年吸っていて、この５年、１０年は吸っていない、そういう方たちのニコチンの解毒剤というんですかね、その辺はどういう効果が、全くなくなっているか、それともあるか、その辺をちょっと教えていただきたいと思います。","respondent":"寺西品川区保健センター保健サービス課長","answer":"それからもう一点、二、三十年吸っていたけれど、このごろはやめているんだけど、どうだろうかということですけど、がんというのは、やっぱり２０年とか３０年というふうに期間で起こってくるものですから、四、五年休んでいるからといっても、やはりちょっと心配されて。","voiceIndex":56,"id":"exchange-023"}]},{"id":"topic-02","title":"改めて行政視察","agenda":"改めて行政視察","exchanges":[{"speaker":"辻副委員長","kind":"意見","question":"これは向こうに行って聞けばいいんでしょうけど、滋賀県の一番最初の説明があったときに、運営主体が抜けている。普通だったら、福祉法人の何とかというんだけど、これはどういういきさつ、何かいろいろいきさつがあったんでしょうし、それも一つ聞いてみる課題なので、福祉事業部長としては、ここら辺のことを何か、こういう種類ですね、メリット、デメリット……。","respondent":"小沼福祉事業部長","answer":"いろんな経過がおそらくあったと思うんですが、これは推測になるのであまり詳しく申し上げるべきことでないと思いますけれども、そこのところで社会福祉法人でいくのか、あるいは財団法人、社団法人等を含めていろいろ滋賀県特有の検討する場面があったんだろうと思います。","voiceIndex":72,"id":"exchange-024"},{"speaker":"須藤委員","kind":"意見","question":"調査報告の仕方については、正副委員長に、ここでやっても個々の意見がいろいろ出てこようかと思うので、お任せをさせていただいて、我々それで対応していくというような形をとったほうが整理しやすいと思いますので、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-025"},{"speaker":"辻副委員長","kind":"質問","question":"だから、例えば私がむれやま荘を山路委員と２人で書いたとしても、これについて職員配置はこうだ、特徴はこうだった、設置目的とかこういうのはほぼこれに沿った形でまとめて、それは担当がまとめて、そこに今後の課題とか、あるいは要するに品川区との関係から見たときに、どういう点が参考になって、どういう点が、この点は我々についても参考になるのかなとか、そういうのがあるじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-026"},{"speaker":"須藤委員","kind":"意見","question":"行政視察の意味合いということなんで、委員会としていろいろ調査研究した後、また、委員のメンバーでいろんな討論をすることはよいことだと思いますので、できましたら、今の形で整理をしていただいて、それぞれ感想なり今後の課題等出てこようかと思うので、それをどうやって品川区に生かせるかというようなことも、またそこで発言なされたり、いろいろ出てくると思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":29559,"voices":79}},{"id":"h14-20020925-8","meetingId":"h14-cm09","date":"2002年9月25日","dateIso":"2002-09-25","committee":"建設委員会","time":"午前１０時０６分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"一つは、今の立坑鋼材のリースですが、立坑そのものはそのまま残るわけですね。現場でお話を聞いていると、要は高台からの水圧で流し込む方式みたいですけれども、実際に目黒川そのものが高い水位にあるときに、そのものが機能していくものなのかどうかというのがわからないものですから、その辺をお聞かせ願いたいと思います。","respondent":"矢部下水道河川課長","answer":"２番目の目黒川の排水の部分ですけれども、委員ご指摘のとおり目黒川の水位が上がったときは、高台部からの水が押し出るような形で目黒川に出てまいりますので、高台部はかなり高いところですから、そこの水位差をもって目黒川に押し出すという形になります。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"今のお話だと、当然目黒川が高い水位にあるときは、目黒川そのものの水圧があるわけですね。そうなると、それこそ５０mmの排水の話ではないですけれども、ああしたものと同じように逆流するようなことも雨量によっては考えられるのではないかなと、今の説明ですとそんな感じがするんですけれども。","respondent":"矢部下水道河川課長","answer":"ただし、上のほうが水位が上がって、目黒川の水位分につきましては確かにたまりますけれども、それより高い部分については水圧が当然かかりますので、押し出す形で目黒川に出てまいります。ですから、上流から入った雨については、どんどん押し出されていくという形になります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"バイパス管の中は、水が残ったらポンプで汲み出してドライにしていくというご説明があったんですけれども、荏原調整池はかなり汚泥とかであとの掃除に費用がかかると伺ったんですけれども、ここの方式だと汚泥だとか残土とかそういうものはどういうふうになるのか、またその処理がどういうふうにしていくのか教えてほしいと思います。","respondent":"矢部下水道河川課長","answer":"ここの維持管理につきましては、最終的に水道局で排水してもらいますので、その辺の話になるかと思うんですが、通常立坑のところからポンプで吸い上げて出しますので、下にたまる部分についてはかなり少ないのかなと感じています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"意見","question":"よく浸水する地域の方々からすると、この対策が待ち望まれているわけですけれども、午前中のご説明だと、今年度中に完成というご説明だったんですけれども、何とか早くこれが使えないかというところで、上流の工区が完成した段階で、できたところだけでも暫定の貯留ができないかという声がかなり上がっていて、その辺のお考えをお聞かせください。","respondent":"矢部下水道河川課長","answer":"今現在、下水道局でその辺の最終的な対応が可能かどうか検討していただいておりますので、その辺の結果が出ましたら、またこの場でご報告させていただきたいと思います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"こういう大きな部分は委員会で報告があるんですけれども、区民の皆さんに直接係わるところですけれども委員会に報告がないので把握しきれないところがあるんですけれども、その辺の兼ね合いもなるべくこの委員会で報告をいただけないかなと思っているんですが、その点に対してはいかがでしょうか。","respondent":"矢部下水道河川課長","answer":"大型の工事につきましてはもちろん建設委員会で説明しますけれども、どこまで説明するという規定がございませんので、かなり大きな工事については説明しますけれども、今回については下水道局だけの対応でいいのではないかという判断の中で、委員会には報告しておりません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"部分的な工事ではあるんだけれども、都の雨水クイックプランというのは品川区よりももっと大きな段階で、ここにそういう設備をつくったら少しでも改善されるのではないかと、いろいろ知恵を出してやってくださるんですけれども、地域の方にするとそこしか見えなくて、やっぱり全体の大きなプランを知った上でのご説明、もちろん平塚のところだと戸越幹線に係わる水害を軽減するためのものですけれども。","respondent":"矢部下水道河川課長","answer":"次回の住民説明会に、私どもも参加しようと考えています。ただ、下水道工事という立場の中で、品川区がどこまで参加して説明すべきかというところで、難しい判断があるかと思うんですけれども、なるべく皆さんに情報提供はするように努力したいと思います。","voiceIndex":17,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"これは１年置きに品川区は独自でやっているんですけれども、昨年の建設委員会の中で、セミナーで皆さんの相談事ですとか、そういった内容についてホームページに掲載できないかという質疑があったようですけれども、その辺がどうなっているか教えていただければと思います。","respondent":"田村住宅課長","answer":"先ほどご指摘のあったように、そのやり取りに出席できない方にも参考になるだろうということで、大分前になりますけれども、やり取りの概要についてまちづくりのホームページに掲載するようにしたものです。","voiceIndex":27,"id":"exchange-007"},{"speaker":"林（和）副委員長","kind":"意見","question":"城南５区共同開催のマンション管理セミナーですけれども、これは何年からやって何回目なのか、それから品川区も例年やっているということですけれども、何年ぐらいやっていて何回目になるのか。","respondent":"田村住宅課長","answer":"品川区単独での開催ということで、これは１年遅れまして平成１０年度から品川区が単独で開催しているということで、初回が平成１１年２月に開催しておりますので、昨年の３月に開催したので４回、今年度は来年２月か３月に開催予定で、そこで５回目です。","voiceIndex":31,"id":"exchange-008"},{"speaker":"田中委員","kind":"意見","question":"既に西大井駅周辺でも、過去にそういうことの対策をということがありましたけれども、また増発によって問題が地域から出て来ようかと思っているんですが、今後のことなので今後の対応は状況を見ながら具体的には対策を練っていただくことだろうと思いますが、現段階でのお考えは。","respondent":"伊佐都市計画課長","answer":"もう１点としては区道の補助２０５号線という都市計画道路の整備という課題もありますが、こちらもあそこを立体交差にするにあたっては非常に構造的にも、またセットバックしても、あそこはなかなか整備できる状況にないということで今後の研究課題ですが。","voiceIndex":41,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3736#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":19890,"voices":58}},{"id":"h14-20020925-9","meetingId":"h14-cm09","date":"2002年9月25日","dateIso":"2002-09-25","committee":"文教委員会","time":"午前１０時１１分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問","question":"私の間違いだったらごめんなさい、もしこれは間違っていたらと、ちょっと伺いたいんですが、「生徒たちが４年間通い続けるためには」と、ここに４年間とうたってあるわけですけれども、３年で卒業できる学校もあるんじゃないのかなと思うんだけれども。定時制でも。違っていたらごめんなさい。数字の部分は。","respondent":"青木指導課長","answer":"確かに一部３年で修了できる学校もありますが、大半が４年間ということで、この４年間を使ったというふうに私は今お伺いしていたんですけれども。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"賛成ですが、ちょっとだけ取り扱いで。無理かとは思うんですけれども、これはある意味で時間との勝負みたいなところがあるんですけれども、例えば今日の午後、そんなことを言ったら印刷から何から、撤回。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"}]},{"id":"topic-02","title":"平成１５年度新１年生の学校選択","agenda":"平成１５年度新１年生の学校選択","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"第二日野小学校は１クラスにして、例の４ブロックのうちの一つの学校選択でやるということなんですけれども、ちょっとその、正式には何でしたっけ、西品川・五反田ブロックというんでしたか、ちょっと忘れちゃったんだけれども、その範囲の学級数と生徒数ですか、現在の１年生でいいんですけれども、わかったら教えていただきたいというのと、それから。","respondent":"谷田部学務課長","answer":"しかしながら、年度途中で転入転出等の関係もありますので、この辺も過去の転入の数等を見込んで、ある程度、１５のうち何人ぐらい転入の方を見込んで用意しておくかということも私ども考えなくてはならない部分です。","voiceIndex":18,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"少ないのも困るけれども、あまり多くなって、ほかから引き寄せちゃって、そこの地元の学校が少なくなるということもまた心配で、非常に複雑な心境ですけれども。わかりました。以上で結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"昨日、３点にわたって質問をした範囲内でお答え願えればと思うんですが、一括して全部言いますので、足して答弁をいただければと思います。お答え願いたいということが一つです。それから３点目は、学級数などの学校規模ができ上がりましたから、必要な用地面積、それから全体の容積などは、床面積などは概算決まってくるんじゃないかと。以上、３点です。","respondent":"富田教育改革担当課長、青木指導課長、鷹倉庶務課長","answer":"それらの保護者対象の説明会等でのご意見をいただいた、ご質問をいただいたりした中で、小中一貫校の準備委員会でも検討を進めまして、小中一貫校の学級数。現在は、その当該校との関係で、教育課程部会で検討した内容と、それぞれの学校で検討していただく内容と。小中一貫校の用地につきましては、既にお話し申し上げているとおり、学校として約２万平方メートル程度の延べ床を考えてあります。","voiceIndex":23,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"ということなんですけれども、全体として合意の方向に近づいているととっていいんでしょうか。それから、教育課程の問題で、学力あるいは規範、倫理観の問題で、合同会議研究で詰めているというんですが、大体いつぐらいにこれは仕上がるのか、今後のあれを示してほしいことと、私は、途中でもいいから、この文教委員会に早い段階で示してほしい。現在の到達点について。","respondent":"富田教育改革担当課長、青木指導課長、鷹倉庶務課長","answer":"先ほど説明会の状況についてご報告をいたしましたけれども、例えば７月に第二日野小、日野中、また先週は第一日野小で説明会を開いたわけですけれども。そうした意味で、到達点というのは、今の時点でどうこう示していくのかということについては今後検討し。街区全体でという面積のお話でございましたが、全体１００・１００ですので、大体１万平方メートル、正確に言いますと１万１。","voiceIndex":27,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"それで、今後のこの問題で、基本的には最低限日野中学区の三つの小学校、第二日野小はちょっと当事校ですから別かもしれないんですけれども、ＰＴＡと、日野中学校のＰＴＡの合意を前提にするというスタンスなのかどうなのか、再度聞きたいことが１点です。ですから、その辺はどうかというのを再度お尋ねしたいと思います。最初の１、２の点について、お答えを願います。","respondent":"富田教育改革担当課長、青木指導課長","answer":"各小学校でも説明会を開いていく中で、各それぞれの校長先生方からもこういう小中一貫校に負けない教育を我が校でもやっていきたい、その上で、それぞれの学校を出て、小中一貫校に中学校から入っても大丈夫ですよと。３年間の中で徐々に準備をしていくわけですので、そうした内容についても、今後重点的には研究はしてまいりますけれども、急激に変わるような形で新入生を混乱させるようなことは絶対にないというふうに考えております。","voiceIndex":31,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"これで終わります。教育課程の問題については、来年学校選びをどうするかということについて、新入生で学校を選択する上でのあれが必要ですので、入ったらこうだというのではなくて、なるべく早い今の段階でわかる範囲のものを出していただきたいということが一つ。全区的に見ると。一応意見だけ。この点は一たん終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-008"},{"speaker":"中島委員","kind":"質問・要望","question":"１点だけいいですか。先ほど署名運動ということで沢田委員のほうからお話があったんですが、地元の日野中学校が移転したくないという署名があるというふうに、今お話の様子からは伺うんですが、そういう内容でしょうか、実は私は相談を受けまして、南大井の大森のすぐそばなんですが、そちらからこういう小中一貫校の建設に対する反対の署名を求められて、これは一体どういうことなんですかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"私が答えるのが。いいですか、委員長。当たっているかどうかわからないんですが、私はあまり署名の中身はＰＴＡがやっているのでよくわからないのが実態なんですけれども、ＰＴＡを中心として地域でやっている署名と、それから、そうではなくて、もうちょっと全区的に小中一貫校ではなくて３０人学級をという二つの署名があるようです。ですから、今言われたのは後者のほうのじゃないかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-010"},{"speaker":"中島委員","kind":"確認","question":"そうですか。すみません。そういう署名が全然関係ない地域のところで出ているということがあると、日野中学校とは違うのかなというふうに、不思議な現象だなというふうに思ったものですから、ちょっと確認をしてみたところなんですが、ただ、私自身もいろいろな方と小中一貫校に対して話をすることがあるんですが、非常に期待の声が多いということは述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-011"},{"speaker":"高星委員","kind":"質問・要望","question":"そういうふうに細かく課長のほうからこの場では報告する必要もないのかもわからないけれども、ただ、僕は大きな視点でとらえるならば、あの彼が大きな声で質問して、彼が言っていることはほとんど保護者の方を代弁している声だなというふうに理解したものですから、そのことの考え方があったら、ひとつお聞かせいただきたいと思います。","respondent":"指田教育次長","answer":"そういったところにおいて、最終的に私は、この第一日野小のときの説明会のときの終わりとして、私のほうから発言をさせていただきました。確かにそういったところでもって皆さんのご心配される向きはわかります。環境が。","voiceIndex":38,"id":"exchange-012"},{"speaker":"高星委員","kind":"質問・要望","question":"だから、例えば地元には第一日野小というちょっと古い、今年になって１２５年にもなるんですよ。だから、そのときに、向こうに行ったときに、品川区全域から子どもたちが集まってくるようなところに、どうやってそれをつくっていくんだろうというのが心配されている向きもかなりおるということも、環境の中に入っているんだということをちょっとご理解をしていただきたいなというふうに思います。","respondent":"指田教育次長","answer":"ただ小中一貫校で、今近隣の学校長が言っている、先ほど富田課長のほうから説明しました中身において、その特色ある学校づくりのところの部分で、沢田委員との話の中で、これはこういう意味だと思うんですね。すなわち、特色ある学校づくりをやっています。","voiceIndex":40,"id":"exchange-013"},{"speaker":"高星委員","kind":"確認","question":"これで終わります。だから、僕はもう一度確認したいなというふうに思うのは、やっぱり同じ義務教育の中で、区別、差別というふうに見てとれるような事象は絶対起こさないというふうなことだけは確信を持って言ってもらいたい。","respondent":"指田教育次長","answer":"ゆめゆめそういうふうな考え方は持っておりません。ただ言えることは、この間、我々プラン２１を進めていくに当たって、学校を変えよう、お互いに切磋琢磨しよう、この言葉というものは基本的には持っているつもりでおります。","voiceIndex":42,"id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけいいですか。教えていただきたいことがある。第二日野小で、先ほど教育内容というお話があったんですが、第二日野小が研究開発学校に指定をされていますが、この研究開発の内容というのは何でしたか。何について指定を。教えていただきたい。","respondent":"青木指導課長","answer":"小中一貫教育です。それがテーマで、その内容でそれぞれの学校が小中一貫校を目指してのカリキュラム開発に取り組むということが指定の内容です。","voiceIndex":44,"id":"exchange-015"},{"speaker":"石田委員","kind":"意見","question":"ぜひ、それが３年間ということで指定をされていると思いますが、そこの点を重々踏まえていただいて、先ほど第二日野小も４０人になるだろうか、非常に第二日野小なんかのキャッチフレーズとすれば、一人一人が宝物みたいな形の、少人数の中であって、そこに子どもを行かせたいと言っている父兄が今度の２年生からずっと上にいるわけだけれども、そこの中に今度４０人という新入生が入ってきたとしたら。","respondent":"青木指導課長、指田教育次長","answer":"その点につきましては、日野中の保護者の方たちとも私は話す機会があったんですけれども、そうした少人数制のよさというものを大事にしてほしいということなんですけれども、もちろんそうした意味で。もちろん基本的なスタンスである例の５月でしたか、基本的な小中一貫校のコンセプトというもの、この考え方は当然お示しをして、こういう学校をつくっていきたいんだという話は。","voiceIndex":46,"id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"でなければ、どういう特色を出せ出せと言っているのは、地区内の４０校、１８校について、いろんな条件においては差別はしないけれども、そこについての区別はあるよ、それで生徒はそこに通ってくる、中学校に通っていくわけですから、その辺がどうもごちゃごちゃになってしまってちゃんと整理がされていないんではないかなという気がするんですけれども、これは私の持論なんだけれども、その辺のところが。","respondent":"指田教育次長","answer":"これはお話し合いの中において、やはり説明をする中において、日野中の生徒は行かせてほしいという強い願い、学校選択の基本的なあり方からするとどうなのかなというところがありますけれども、それについては、やはり同意を得るためには、一つの過渡的な整理かなと。","voiceIndex":49,"id":"exchange-017"},{"speaker":"鶴委員長","kind":"質問","question":"よろしいですか、私から関連して３点ご質問ですが、桜井議員の一般質問の、この小中一貫校については、私の記憶によると、中止という立場から論を展開されていたんではないかと、たしか中止に間違いありませんですね。それで、今までの説明の中で、どことどこの通学路が心配だ、だからどうしてほしいというふうな意見まで出てきていたのか、いないのかということを知りたいんですね。","respondent":"富田教育改革担当課長","answer":"具体的に通学路のこの部分というようなご指摘は、説明会の中では出ておりませんで、通学路の街路灯を明るくしてほしい、また安全確保の体制をとってほしいというご意見が出された学校も、中にはあるという状況です。","voiceIndex":51,"id":"exchange-018"},{"speaker":"上山副委員長","kind":"質問・要望","question":"私のほうから２点ちょっとお尋ねしたいんですが、ほかの委員から触れられた関係で質問させていただきたいんですが、カリキュラムの関係なんですけれども、なかなかまだ決まっていないと、それはそういうことだから決まっていないということだと思うんですが、以前ちょっと確認だけなんですけれども、何か９年なんですけれども、４・３・２みたいな話が出てきたこともあったやに聞いているんですが。","respondent":"指田教育次長、青木指導課長","answer":"そういうときにも、また議会からのご意見等を踏まえて、今後どういうふうに学校改築を進めていけばいいのか、この中で問題点、課題は整理していきたいな、こういうふうに思っております。４・３・２の、そのいわゆる学年のまとまりというんですか、その子どもたちの発達とか学年とかというのをどういうふうに学年として組んでいくのかというご質問かと思うんですが、現在、その４・３・２というような区切り。","voiceIndex":57,"id":"exchange-019"},{"speaker":"高星委員","kind":"質問","question":"委員長、すみません、一つ短いのをいいですか。この間の第一日野小の説明会のときも出ていてちょっと気になっていたんですけれども、僕もわからないから教えてもらいたいなというふうに思うんですけれども、学務課長になるのかな、要するに、文教地区だとか風致地区とかという地区指定がいろいろありますよね。ちょっとわかったら教えてもらいたいなと。フォローとも関係のない、単なる質問なんだけれども。","respondent":"谷田部学務課長","answer":"今のお話ですと、私どももそこまで今十分わかっていませんので、また次回、別な機会がありましたら。","voiceIndex":60,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"時間のないところで申しわけないんですけれども、来年のこの義務教育国庫負担制度の見直しがかなり新聞に報じられて、教員２分の１の国庫補助が何年かで削られていくという話が大きな問題になっていまして、これは区費との兼ね合いで、区は直接関係ないけれども、やっぱり影響は相当出てくるんじゃないかなと思っているんですけれども、そこらで品川区がつかんでいることがあったら。","respondent":"指田教育次長","answer":"２３区の教育、例えば指導室課長会、あるいは部長会、教育長会、そこでも何も報告の一つもありません。そういう中において、あくまでもこれは新聞報道で読む内容でしか私のほうもわかりません。","voiceIndex":71,"id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"遠山文部科学大臣が経済諮問会議の場で、平成１４年から平成１８年にかけて５，０００億円の教員の給与分を暫減的になくしていく、後退していくということで、ただ今度の概算要求には盛り込まれなかったというようなこともちょっと聞いているので、少し延びたのかどうなのかということはあるんですけれども、それにしても、あまりにも大きな問題になるんじゃないかなというのが不安だったのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":31024,"voices":78}},{"id":"h14-20020925-5","meetingId":"h14-cm09","date":"2002年9月25日","dateIso":"2002-09-25","committee":"総務委員会","time":"午前１０時０５分～午後４時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５２号議案、平成１４年度品川区一般会計補正予算","agenda":"第５２号議案、平成１４年度品川区一般会計補正予算","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"これは、政策に係わる部分なんですけれども、これらはどういうふうな予算で、こうした政策を考えているのか、ちょっと教えていただきたいと思うし、あわせて、今、株式会社都市整備公社の社長はどなたなんでしょうか。それから、１７ページの認証保育所の関係なんですけれども、これの運営主体はどこなんでしょうか。そうした特別教室の関係は、今後どういう考え方なのか、教えていただきたいと思います。","respondent":"市岡企画財政課長","answer":"幾つか候補地、あるいは提案させていただいている内容もありますが、現在時点では固まっていないので、今回の予定の見合いの基金が５，０００万円で、それ以降については、次の見合いで考えていくです。それから、都市整備公社の社長は濱野助役です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"すみません、先ほどのグループホームの関係ですけれども、５，０００万円というのは、全部基金ということなんでしょうか。そうすると、今のお話ですと、これからも第２、第３の用地取得も考えているとなると、限度額というのか、際限ない補助金を出すというのもちょっとおかしいし、きちっとした要綱なり、ルールなりというものを考えていくべきだと思うんですけれども、そこはどうなんでしょうか。","respondent":"市岡企画財政課長","answer":"したがいまして、今は、いわゆる民間保育所としては、年齢別で見るといろいろなばらつきがありますけれども、そういう開発動向絡みで、新しく区民になられた方、あるいは、入居された方の保育需要については。","voiceIndex":9,"id":"exchange-002"},{"speaker":"桜井委員","kind":"意見","question":"グループホームをつくることについては、積極的な意味もあるし、ぜひこれは望まれていることなんです。今の質疑では、なぜ株式会社都市整備公社かというのが、ちょっとまだ不透明な部分が、率直に言ってあるんです、私の中に。今回の予算のところでは、これでとどまっておきますけれども、いずれまた別の機会で聞きたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"緊急は別として、それ以外は、繰越金が確定して、繰越金の中でやりくりというか、事業を興したという説明をされていたんだけれども、繰越金の処理というか、扱い方というのか、これぐらい出てくるのならば、こういう事業を補正で組み立てていこうと、そういう考え方をこれからも続けていくのかどうか。繰越金のとらえ方を、ちょっと説明してください。","respondent":"市岡企画財政課長","answer":"かつて、税等が伸びていた時代には、補正のときの財源として、当初予算で見込んでいたよりも税収が伸びた部分を充てていたということもございましたので、あくまで、繰越金を補正の財源として充てるというのも、幾つかの選択肢の中の一つであろうと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"そういうときに、例えば、ちょっとうがった言い方をすると、教育委員会は教育改革に頑張っているから、今回、補正３億円繰越金が出たから、教育委員会で何か考えようとか、あるいは、まちづくり事業部が、さっき見させてもらった屋上庭園でいろいろ頑張っていると、こういう余剰金が出てきたから、じゃあ、この時期の補正について、来年の今ごろの時期に土木関係の事業に充てていこうじゃないかとか。","respondent":"市岡企画財政課長","answer":"しかし、具体的に今充当するような事業がないけれども、二、三年、あるいはもう少し長いスパンで見れば、その累積がいろいろな形でどこかで報われてもいいんじゃないかと、こういう考え方もありまして、それを言わばしっかりに帳簿につけて。","voiceIndex":14,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"事業部内積立とか、事業部の帳簿とか、具体的にはないんでしょうけれども、企画のほうでそういう意識を持つということだろうと思うんです。それに対して、区のほうでは、何かものが言えないんですかね。","respondent":"市岡企画財政課長","answer":"認証保育所についても、東京都が認証するから、認証したものの２分の１を持たされるという考え方ではなくて、認証に当たっては、個々の問題としては必ず区の意見を貫いて、必要性。","voiceIndex":16,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"もう一つ聞きたいんですが、主体的には東京都のほうが施策を打ち出す、あるいは国の方針に沿って都道府県がそういうものを打ち出していく。もし、今までも言ったことがあれとすれば、ちょっと例として聞かせてほしいし、これからいわゆる区の第三次長期基本計画をしていく中で、そういうことが可能なんだろうかというのを聞かせてください。","respondent":"市岡企画財政課長","answer":"土木関係では、国土交通省が土木の国庫補助金の包括化ということを、先年来言っておりまして、これは公園、これは道路、これは橋梁ということではなくて、ある地区の中で優先順位の高い整備計画を立てれば、区の予算順位づけに従って補助採択をされる。","voiceIndex":18,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"最後に。こういう考え方はできないだろうか。無償で対価を求めないで、どうぞ、こういう人たちのために使ってくださいというのは、大変な金額ですよ。こういう方たちの気持ちにひとつ応えるという意味では、１，０００万円より２，０００万円のほうが生きた基金になるとすれば、気持ちに応えて、区として同じ額を出して基金にするという考え方はどうかなと、いかがですか。","respondent":"中尾根企画部長","answer":"今、委員のご提案で、意味はよくわかりますけれども、そういう考え方で、実は、私どもは、同じ額を基金に積むということではなくて、そういう寄附をしてくださった方に対して、名前つきの基金をするという発想は、もともとありました。","voiceIndex":20,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"提案","question":"お名前を残すことを、僕は消せと言ってないんです。という意味で、その人のお気持ちに応える区の気持ち、もしそこに１，０００万円を入れとすれば、税金なんだから区民全体の気持ちとして、何々基金の効果を上げるために同額を増やすということは、決してむだにはならないし、名前も消さないしということで、その方の気持ちが倍に生きるという意味で、お考えになったらどうですかと提案させてもらったんです。","respondent":"濱野助役","answer":"予算制度というのはいろいろ制約もありますので、お気持ちは十分理解させていただき、区としてはそういう考え方です。","voiceIndex":22,"id":"exchange-009"},{"speaker":"桜井委員","kind":"確認","question":"すみません、１点だけお答えいただかなかったことを思い出したんです。特別教室の国の補助金のことだけ、もう一度確認したいんです。","respondent":"市岡企画財政課長","answer":"制度はありますが、実際には非常に採択率が低いので、採択されないというのが現実です。","voiceIndex":24,"id":"exchange-010"},{"speaker":"藤田委員","kind":"質問","question":"今の１，０００万円の寄附の件ですが、私は、それを受ける子どもたちに、やはりそういう真心で運営をしていくんだということで、中には返済が滞っている人とかいるわけですね。返済するのは当然ですから、その子どもに窓口できちっとやっぱり、そういう真心の財源で皆さんにお貸しするんですよという姿勢があってもいいんじゃないかなと、ちょっとひと言申し添えます。","respondent":"市岡企画財政課長","answer":"これまで、豊町、平塚、八潮と３カ所ありまして、今回、この補正で５カ所目になります。いずれも、考え方としては、地域の方々の活動する場がなかなかありませんので、そういう拠点をつくることによって、いろいろ児童センターの事業に地域の方に参加してもらうおうと。","voiceIndex":26,"id":"exchange-011"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、旗の台の複合施設のところでは、そういう活動の部屋というのを新たに設けるわけでしょうか。今、あの施設はもう満ぱいで使っていらっしゃいますけれども、その辺の判断はどうなんでしょうか。","respondent":"市岡企画財政課長","answer":"今回の二つもそうですが、この補正を入れた５カ所は、いずれも、例えば旧倉庫であるとか、昔の管理人室であるとか、上手にデッドスペースを使って、そこの内装改修でやっていく。極力、現有施設の有効活用ということで考えているです。","voiceIndex":28,"id":"exchange-012"}]},{"id":"topic-02","title":"きのうからの続きの第５３号議案、品川区住民基本台帳ネットワークシステムに係る個人情報の保護に関する条例","agenda":"きのうからの続きの第５３号議案、品川区住民基本台帳ネットワークシステムに係る個人情報の保護に関する条例","exchanges":[{"speaker":"桜井委員","kind":"確認","question":"その根拠のことで質問をしたときに、違法とか、違法でないとか、その辺の判断も含めて、適当でない、有効でないというんでしょうか、そういう意味合いのことをおっしゃいましたよね。その後、９月１２日の東京新聞なんですけれども、中野区の区長も、漏えい防止が確認できないということで離脱をしましたよね。","respondent":"山田広報広聴課長","answer":"住民基本台帳法の中にさまざまな法令として入っている安全措置について、これを信用できるか、できないかというところの確認というのは、それぞれの自治体の、杉並区で言えば、杉並区の解釈の形でもとになったかと思います。","voiceIndex":34,"id":"exchange-013"},{"speaker":"桜井委員","kind":"質問","question":"ですから、国は国としての指導を、当然おやりになるんでしょうけれども、きのう議論になった、要するに法に触れるのかどうかという点では、私は触れないと思うんですよ。そのことを言ったんです。ですから、そういう点では判断をされるという点で、違法かどうかと品川区が判断するのはおかしいんじゃないかと、そういうことなんです。","respondent":"中尾根企画部長","answer":"要するに、３６条の部分で、それが杉並区なり、中野区の区長は、非常に重要なことだと、要するに法律の核心だという受けとめ方だから、この１条の部分についての確信がないから断絶すると、こういうご判断なんだと思います。","voiceIndex":36,"id":"exchange-014"},{"speaker":"桜井委員","kind":"質問","question":"そうであれば、わかります。それで思うのに、個人情報保護条例が３，３００の自治体で、品川区はできていますけれども、全部できているのかどうかというのを、ちょっと聞きたいんです。というのは、今言ったように、いろいろな地方自治体の窓口に行って、情報を得るわけですから、そのことも一つ聞きたい。","respondent":"山田広報広聴課長、中尾根企画部長","answer":"最初に、個人情報保護法が、地方ですから、条例なり、規則なりということになるわけですけれども、規則も含めますと、３，２８８ある団体のうち８０.１％が何らかの形で持っているというのが、９月３日。冒頭の、なぜゆえにこうも対応がいろいろあるのかというご質問ですが、対応は二つしかありません。その回線を断絶しているのか、回線を通じて事務を行っているのかです。断絶しているのは、三千何百の自治体のうちのたった四つです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから私は、きのうから論議になったプライバシーというか、言葉を借りれば、個人の保護となると思いますけれども、そういう点からすると、きのうちょっと言いかけたんですけれども、もう１回改めて聞きたいのは、今の個人情報保護法を、やっぱりぜひ国で制定してほしいということを早急にやっていただきたいと思うんです。そこのところを、もう１回、確認をしたい。","respondent":"山田広報広聴課長、中尾根企画部長","answer":"それと同時に、杉並区が、いわゆる調査の中で、来た方にアンケートを取って、アンケートを取ったと、そういう形でおっしゃられていることもありますけれども、いわゆる住民基本台帳ネットワークについては、法令に定められたものを。個人情報保護について、やっぱり国で早急に、そのことについてきちんとすべきだと、この考え方については全く同感ですし、これまでにとってきた区の方針、態度につきましても、特に過日の区長会の中では、杉並区と中野区の区長は。","voiceIndex":41,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"心配ごとはまた別の機会に言うこともあろうと思いますので、ここで一つ聞いておきたいことは、国民にすべてナンバリングしたということは、いろいろなやり方があるでしょうし、現状で、欧米ではそのようなやり方をしていないわけですから、基本的にどんなやり方があって、なぜ、日本はこういうやり方をとったのかということを、説明できますか。","respondent":"田中情報システム課長","answer":"一生同じ番号でずっといくんです。自分で勝手に変えられるとかということではありません。そういうふうに全国民に振るというのは、社会保障番号をとったり、もしくは韓国ですとか、北欧でもあるんですが、住民登録の番号という形でやっています。","voiceIndex":44,"id":"exchange-017"},{"speaker":"塚本委員","kind":"意見","question":"社会保障番号は、アメリカの国民すべてが持っているわけじゃないんで、日本国民である以上、住民票登録をして番号をもらわないと、行政サービス、国民としての権利というようなものを保証されないということが、かなりの角度で言えてきちゃうわけです。ほかの国の制度とは、そこのところが違っている。登録に、ある種の任意性が許されているというふうに理解していいのか、その辺をところをちょっと。","respondent":"田中情報システム課長","answer":"任意に自分が意思表示して登録してくださいということではなくて、すべて登録されています。そのかわり、非常に独立した権限のある機関が、プライバシーをきちっと守るという法制度が確立されているという形になっています。","voiceIndex":46,"id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"もう１点は、財団法人地方自治情報センターでしたか、なぜその機関があるのかということ。あまり情報のハードの点に詳しくないので、できればどういう意味があるのか。ある一定のルールがあれば、この機関がなくても、自治体と国との責務が分かれておれば、直接やり取りしてもいいのではないか。なぜ、その組織が必要なのか、あるいは、そういう仕組みを考えついたのか。","respondent":"冨田戸籍住民課長","answer":"指定を受けたところで、関係の情報処理をやるということなんですけれども、住民基本台帳ネットワーク自体が、都道府県知事が、その業務について、特定の団体に業務を委任できるという規定がございまして。","voiceIndex":50,"id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"説明はわかっているんですけれども、なぜそういうものを選んで、それが果たしてベターなのかどうかということを聞いているんです。","respondent":"田中情報システム課長","answer":"そのデータを、ユーザー側の国が、それぞれ４７都道府県にアクセスしないでも、すべて１億２，０００万のデータが入っているサーバーに簡単にアクセスすれば、すぐに見れるということで、統一で考えてそういうふうになったのであります。","voiceIndex":52,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"ということは、直接につながっていれば、国がどういう情報を、どの時点で引っ張って行ったかというのを、こっちが管理できるわけですよ。途中にあったら、どうなのかわからなくなるわけですから、わかるようにしてあるんだと言いますけれども、責任の範囲が超えていってしまうわけですから、技術的には、そういうことは可能なわけでしょ。中間に集約する必要がどこにあるんだということを聞いているんです。","respondent":"田中情報システム課長、中尾根企画部長","answer":"国に直接すぐにデータを送るとか、国が管理しているわけではありませんので、基本的に、自治体の委任を受けて、自治体自身がやっている情報を、国が見させてくださいと来るだけですので、その辺のところは。このパターンと、ある意味では同じです。したがいまして、電算機をとことん活用するんだということであると、分散ではなくて、当然ながら、ものの考え方は集中となります。","voiceIndex":54,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"分散と集中というのは、安全と非常にリンクしている話ですから、集中が危険だという一つの要素は大変あるわけですから、そういう意味で聞いているんです。きのうの土井委員の質疑の中で、自治体間の住民情報のやり取りは、両方でやっているわけでしょ。これ以上聞いてもしようがない、わからなくなったら土井委員に聞きます。","respondent":"田中情報システム課長","answer":"住民票の設定と、来年８月以降の広域交付は、１件、２件を交付先の市町村と住所地の市町村とやり取りをやるわけですが、何百万件という生存死亡の情報を、社会保険、共済年金等の現況届けのかわりで処理するということになると、それはもう３。","voiceIndex":57,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"これで打ち切りますけれども、このセンターの機能を国が持っていればいいじゃないですか。それで、我々と直に、品川区の情報は国が常にアクセスしているんだということになれば、我々だって、このアクセスの仕方はおかしいということを言えるようになるんではないですか。なんで間があるんですかということです。","respondent":"中尾根企画部長","answer":"ただ、住基ネットということで、住民基本台帳だから、この権限は国はなくて、どうしても自治体だと。したがって、そこに設けられた、法制度もクリアしてやったのがそのセンターだと、このようにご理解いただきたいと思います。","voiceIndex":59,"id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"それは、先に法がありきでなくて、全体の安全性や責任の所在を考えたときに、これがベストではないという考え方もあります。そういう意味での検証をどこかでやらなきゃいかんというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-024"},{"speaker":"土井委員","kind":"質問","question":"したがって、やはりこの条例では書き得ないのかもしれませんけれども、いわゆる公務員の守秘義務に係わるものについて、少なくとも品川区の皆さんはしっかりやっていただいていると思うんですけれども、これをどう維持をしていくのか、これからもどう担保するのかということが、まずもって必要ですし、さらに、全国のすべてのこれに係わる公務員の皆さんにも。","respondent":"田中情報システム課長、山田広報広聴課長","answer":"３点目のセキュリティ関係の担保のところですが、当然、技術的なことを含めて、閉じられたネットワークの中で、いろいろ扱う、運用する職員を含めて、きちっと対応していくということで、規定整備等を含めて行っていますし。あわせて、品川区にとりましては、まず品川区情報公開・個人情報保護条例第３条の中に、「実施機関の職員は、職務上知り得た個人に関する情報をみだりに他人に知らせ、または不当な目的に使用してはならない。","voiceIndex":64,"id":"exchange-025"},{"speaker":"土井委員","kind":"意見","question":"そんな中で、この条例については、ご説明にありましたように、品川区が、現状の法体系の中でできるものは何だろうかということの中での、ぎりぎりのところが入ってきていると認識もしておるわけですけれども、やはり、先ほどから議論にもありましたけれども、本来的には、品川区だけではなくて、全国の自治体、あるいは。","respondent":"中尾根企画部長","answer":"それをクリアしない限りサービスはできない。例えば保育園にしろ、最初に申し込んだときに、年収から、家族構成から知ることになります。保育を預かるほうにすれば、その子どもがどのように成長するか、いい成長のためには家族の状況が、ある程度わからなきゃいけない。","voiceIndex":67,"id":"exchange-026"},{"speaker":"藤田委員","kind":"質問・要望","question":"これまでも再三出てきています地方自治情報センター、これの位置づけなんですけれども、これをちょっと教えていただきたいんですが、独立した機関になっていると、私は思うんですけれども、どういう人たちが情報センターの職員になっているのか。設立の目的、それから、運営というのはどういうふうになっているのか、ちょっとそれを教えていただきたいと思います。","respondent":"田中情報システム課長","answer":"地方自治情報センターにつきましては、旧自治省と地方公共団体の３団体の関係者でつくられておりまして、一応、財団法人ということになっております。運営は、評議員というのがありまして、２年の任期なんです。","voiceIndex":69,"id":"exchange-027"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、心配されているのは、国が目的外使用をしようとした場合に、それはだめだとか、それはいいとかという判断は、だれがするんですか。","respondent":"田中情報システム課長","answer":"管理者は特定されていますので、管理者が判断することになりますが、当然、法律に決められた内容で委任されていますので、それ以外の法律に定められていない機関、省庁や業務につないだり、情報を提供したりすることはできないと考えています。","voiceIndex":71,"id":"exchange-028"},{"speaker":"藤田委員","kind":"質問","question":"特定されたその管理者というのは、どういう立場の人なんでしょうかね。政治的に何か問題があった場合の判断というのは、だれがどういう判断を下すのか。もちろん評議員等が議論して、最終的には管理者判断なのか、その辺がよく見えてこない部分があるんですけれども。","respondent":"田中情報システム課長、冨田戸籍住民課長、中尾根企画部長","answer":"国が、法律に違反して請求してきたら、都道府県が指定情報処理機関に業務を委任していますが、違法な請求があったものにこたえるかというと。そうしたことを行った後、実際にどういう形で情報の提供を受けるかというと、特別の機器を設置して、指定された業務の従事者。違反したときというご質問ですが、当然ながら、設置主体は都道府県ですから、したがいまして、具体的にも情報保護に関する事項等を調査、審査する審議会。","voiceIndex":73,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"何点か、角度を変えて聞いていきたいんです。言われているように、いろいろ細かくはあるんだろうけれども、理由の大きなものは、国の個人の情報保護の法整備、それを法的に整備してくれれば接続しますよというのが、ほとんどの見解です。それがされていないというのが現実です。例えば、全国の三千幾つの自治体なり、４７都道府県の地方自治体、それぞれ全部の自治体で条例になりますよね。","respondent":"中尾根企画部長","answer":"国は使う側としての、自分たちでの情報の範囲になりますから、例えば、この条例で、違反したら情報をあげないということはできますけれども、使い方をどうしろということまではできない。そういう差がどうしても出てくる。守備の範囲の違いがあります。","voiceIndex":77,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"一つ一つの公務員の行動というか、各自治体の職員の行動について、不正アクセスというか、決められた以上の事務の情報を取るとか、決められたこと以上の作業、活動を公務員がしたことについては、例えば厚生労働省とか、いわゆる省庁はほとんど東京都にあるわけですけれども、東京都の条例で、公務員の作業というか、やったことについて、ちょっと言葉を柔らかく言うと、取っちゃいけないものを取った。","respondent":"中尾根企画部長","answer":"通常、普通に考えれば、使う省庁側が、自分たちみずからが得た情報について、こういう使い方をします、こういうことはしませんと、はっきり言ってもらうと、初めて安心するわけですね。そこのところが通常です。","voiceIndex":79,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"センター、財団法人については、どうですか。","respondent":"中尾根企画部長","answer":"財団法人のセンターそのものについての、その種のことであるとか、セキュリティの問題は、まさしくこちらが委託する側で、その仕事をさせている側ですから、きちんとこちらの指示どおりにしていただかなきゃならないし、指示は出さなきゃいけないという関係はあります。","voiceIndex":81,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"片や国家公務員の規制はされているわけですよね、従来の法で。守秘義務であるとか。そうすると、守秘義務というのは、もう既に国家公務員を縛ってあるという中で、今回の住基ネットを稼働させることによって起こり得る心配事、公務員に不正なき仕事をさせるというための法整備というのは、どういう文言が考えられるんですか。既にあるんでしょ。","respondent":"田中情報システム課長","answer":"先ほど、広報広聴課長がご説明したように、行政機関については、行政機関個人情報保護法がありまして、いろいろなデータの保護について規定しています。","voiceIndex":83,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そこが一番だと思うんですよね。じゃあ、限られた資格を持つ人しかアクセスできない、あるいは情報を求めることもできないし、出すこともできないというような縛りをかけて、例えば、ここにいらっしゃる２０人ぐらいの中でも３人だけですよと、それ以外は一切手を触れられませんよというような縛りのかけ方は、区ではやっているんですか、それとも国ではやっているんですか。","respondent":"中尾根企画部長","answer":"危惧しているところは全く同じです。ただし、そういう意味からすると、同じ情報の中でも、やっぱり価値を高めて使おうと思えば、思うほど、そのことについてはシビアに考えていかなきゃいけないと、私どもこのように認識しています。","voiceIndex":85,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"意見","question":"だけど、片や必要だと、日本中の全自治体が言っているわけですよね。ずっと住基ネットの話の周りを話したんだけれども、この条例に係わる部分の話に入っていかないと、住基ネットそのものがいいとか、悪いとか、法が整備されていないとか、しているとかいう話を、結構、きのうからやってきたんで、委員長にお願いだけれども、こちらにできるだけシフトをしていくように、皆さん協力してお願いしたいと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-035"},{"speaker":"塚本委員","kind":"提案","question":"せっかくのご提案ですけれども、取り扱いのゆくえがわかってから、そういう段取りになると思います。きょう決まれば、それに越したことはないんですが。それの扱いを含めて、今のご提案の日時になるのか。私どもも、この件に対する見方というものは、党内で議論しまして、一定の方向性を決めておりますので、そういうものも含めて、委員長のご提案をいただければなおありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-036"},{"speaker":"川西副委員長","kind":"質問","question":"共産党からはこういう文書で出ていますので、説明をしていただくだけで、中身はある程度把握できるんです。そうすると、今、塚本委員の発言というのは、どういうふうにとったらよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"提案","question":"さっきから言うように、今まで住基ネットというものについて、いろいろ心配事、理事者と討議をやったわけで、区長提案の条例案に触っていかないと、共産党の修正案のところには行かない。そうすると、おのずと、ある程度の議論が進めば、共産党の修正案に進む。今までは、住基ネットそのものの話が主たる話題だったので、委員長に、こちらの条例に触れていっていただきたいと言っただけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-038"},{"speaker":"桜井委員","kind":"質問","question":"議事運営で、きょう、委員長のほうで、４時ごろをめどにというお話でしたよね。今の話をもう少し審議を続行して、もう少し経った時点でもいいのではないかと思うんです。きょう、ある程度見通しがつけば、それはそれでいいし、もうちょっと残された課題でやろうとなれば、それはそれでまた判断するということで、もう少し審議を続行したらいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-039"},{"speaker":"川西副委員長","kind":"意見","question":"もう一つ、きのうからの発言の中で、条例の中身に入る前にという前段の議論が多いんですけれども、具体的な中身に入るべきですよ。","respondent":"伊藤委員長","answer":"まとめていきますと、あくまで１０月１０日というのは、危機感からと先ほど説明しましたけれども、きょうの議論の中である程度のものが出れば、進めていく。","voiceIndex":96,"id":"exchange-040"},{"speaker":"塚本委員","kind":"提案","question":"委員長の指示に従いまして、提案された条例について、我々も意見といいますか。それから、盗んだか盗んでないかということを検証することが非常に困難であるということ、その価値、それを求める人がかなりいる、それを悪用する人がかなりいるということ、いろいろな背景を含めますと、今までの規範でいいのかどうかという心配を、私ども強く持っております。その方向で臨みたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-041"},{"speaker":"桜井委員","kind":"質問","question":"区民の皆さんから、自分の情報はどう管理をしていこうか、そこがポイントだと思うんですけれども、その点を一つ聞きたい。切断をする前の段階で、もちろんいろいろな調査をして、いろいろ調べたり、そういうところで最終的な判断として切断というわけですけれども、こういうふうに切断という必要な措置まで考えられた背景というんでしょうか、そこのところを聞きたいと思います。","respondent":"山田広報広聴課長","answer":"これは、区が所有する自己情報については、第１５条で開示の請求ができるという規定、なおかつ、今回、初めて出てきた電磁的なものに対する対応についても、同じような条例の中の施行規則第７条の第１項第２号の中に、「磁気ディスクの記録されてものについては、出力して閲覧と。","voiceIndex":100,"id":"exchange-042"},{"speaker":"桜井委員","kind":"質問","question":"自己情報の開示の仕方ですよね。先ほど、お話ししましたように、区が持っているのは住民票台帳で、主として、今度のコード番号も入れて、指定処理機関まで行くわけですよね。そのこところまでいくと思うんですよ。しかし、今回は、ネットワークになったわけですから、いろいろなところからそういう情報がある。そこのところが、開示がどういうふうに請求できるかどうか、担保がどうなのか。そこなんです。","respondent":"山田広報広聴課長","answer":"品川区のレベルで言えば、品川区が送信した送信記録という形を持っていますから、今のことは、私どもの条例で対応できるということです。","voiceIndex":102,"id":"exchange-043"},{"speaker":"桜井委員","kind":"質問","question":"実際に、インターネットを見ていますと、住基ネットでアクセスロムを開示請求ということが再三ありまして、当然だと思うんです。しかし、今お話があったように、確かに、今の法の体系ではそこまではやっていないと。そういう私の考え方に対しては、いかがでしょうか。","respondent":"山田広報広聴課長","answer":"総務省が、各都道府県知事会を９月４日に開いたところでも、各県知事のほうからも、いわゆる同じようなご指摘がありまして、これは個人という部分ではなくて、各自治体においても、いわゆる知らしめてほしいというような要請があったと伺っております。","voiceIndex":104,"id":"exchange-044"},{"speaker":"藤田委員","kind":"意見","question":"不正情報取得者に対する措置ということなんですけれども、これはなかなか難しい。ところが、どうして発覚したのかというと、全部内部の告発なんです。今、時間もあれですので、塚本委員が考えがあるとおっしゃっていましたので、それはそれとして、きょうはおそらく時間的に無理じゃないかと思いますので、次の委員会等でも、それを尊重してやりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと条例そのものについて疑問というか、確認しておきたいことがあるんです。９条から成っているんですけれども、１、２、９を除くと、全部主語は区長になっているわけです。区長保護条例じゃないんだから。実際に、区長以外のセキュリティの責任者を含めて、全職員が住基ネットに取り組んでいく中で、こういう姿勢で、もう一度というのが見えないんだけれども、それはうたわなくて大丈夫ですか。","respondent":"中尾根企画部長","answer":"したがって、条例上であらわすのは、うちの法律と同じですから、そこの中には、内部の手続は細々と別に書く必要はありませんので、区長がやるということは、組織全体を挙げてやるということで、これはほかの条例でも同じことです。","voiceIndex":109,"id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問","question":"「区長は」ということに対して、意味はわかる。それを、区の職員もはっきり認識しておかなきゃいけないし、それが伝わらないところが、ほころびが出るということになるわけですから、絶えずそういうところから出るわけですよ。その心配を、まず訴えておきます。今度は、５条については、また違う趣旨というか、意味が盛られるくると、僕はとるんですけれども、１条、５条というのは、どういう関係にあるのか。","respondent":"山田広報広聴課長","answer":"第１条につきましては、頭のところで、「住民基本台帳ネットワークシステムの運用に伴い、区が保有する住民票の記載事項に関する情報の適正な管理」ということで、ここにあります区が保有する住民票の記載事項に関する情報と適正な管理の部分と同じ中身として。","voiceIndex":111,"id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"条例の案文として、同じ言葉が違う意味で使われる。意味は同じなんだけれども、というような気がすると指摘をしておきます。７条のほうは、(1)で、「安全性を侵犯する重大な不正行為を発見したとき」に、今度は、緊急時だから切断しちゃうという二つの対応が書かれているんですけれども、６条の滅失とか、き損というのは、緊急に当たらないんですか。","respondent":"山田広報広聴課長","answer":"なおかつ、緊急については、現在、安全確保のためさまざまな手段はとっているんですけれども、このような緊急な事態が出てきた場合、必要な緊急措置をこのようにとりますという具体的行為として、別枠で定めているです。","voiceIndex":113,"id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だとしたら、６条の(1)の文面は、ちょっと手遅れになるおそれがあるという心配。ここから報告を求めて、必要な調査を行っていく。漏えいということがあったら、不正行為があったと見なさないですか。６条で、これは漏えいがあったと、いやいや切断はまだ早い、調査をしなさいと、調査はどうなったか、報告しろとなっていくのと、緊急の切断というのと、タイムラグが大きすぎないかということ。","respondent":"中尾根企画部長","answer":"６条と７条の関係ですけれども、６条は調査するということですから、緊急との関係で、調査した結果わかってこの措置をするかもしれないし、調査なんか要らなくてわかった場合にもするという前提ですから、そこのところは。","voiceIndex":115,"id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"後段のところはわかりました。前段の６条、７条の部分で、さっき、広報広聴課長が説明されたのは、不適性利用に対する措置というのが６条だと、７条は緊急時の対応という説明だった。不適性のときは６条が対応する、緊急のときは７条が対応すると。不適性が瞬間的にわかる場合だってあるじゃないですか。としたら、瞬間的に７条適正というのができるようにしておかなきゃいけないんじゃないですかと。","respondent":"山田広報広聴課長","answer":"緊急時の対応の第７条の３号のところに、「前２号に掲げるもののほか、住民票記載情報を保護するため必要があると認めたとき」ということで、これは、なぜ設定したかといいますと、いわゆる不測の事態を想定してこの文言が入っております。","voiceIndex":117,"id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問","question":"だから、「ほかに」というのは、７条で瞬時に切れるんですかと。それは困るわけだから、出ないようにしていくという一つの役目を持っているんだけれども、出ちゃったときに瞬間的にやっても遅いぐらいなので、これを施行していく上では、少なくとも関係する管理職には、そういうことをきちんと統一したことを持っていてほしいなと思うんで、それをお願いします。","respondent":"濱野助役","answer":"条例の構成としては、要は、６条は外側の団体、機関との関係をあらわしています。７条は、ネットそのものをどうするか、スイッチを切るかとかいう意味のことで記載されています。","voiceIndex":119,"id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問","question":"最後にします。何か大量に情報を流してほしいとか、どういう内容があるかわからないけれども、プロが感じて、あれ、こういうアクセス、あるいは問い合わせはおかしいなといったときに、断れる、あるいは、電話なら、ちょっとお待ちくださいで音楽が流れる、ちょっと悠長な話だけれども、そういうふうに待たせられる仕組み、あるいは区としての対応が、この条例の中でできるんですか。","respondent":"田中情報システム課長","answer":"そういうところで確認されたら、速やかにシャットダウン等を含めた対応をとるということになっています。","voiceIndex":121,"id":"exchange-052"},{"speaker":"塚本委員","kind":"意見","question":"取り扱いですけれども、原案の質疑を終了して、順次としては、共産党の修正案の件になりますから、説明の取り扱いをしなきゃいけない。今、委員長のご説明は、案件の性質上、それも含めて次回にということだろうと理解しましたが、ひとまずは、共産党にご説明いただくというのがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-053"},{"speaker":"桜井委員","kind":"提案","question":"２番目の９条をというのは、単純に、条文を繰り下げるということですから、説明を省かせていただきます。「起算して１０日以内に送信の……」ということです。全体の意向としては、これまで論議をされてきておりますように、やはり、この間、地方自治体のところからも、区民の情報保護についてどういうふうに考えているのかという、そういうことを踏まえた上で、本修正案を提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-054"},{"speaker":"塚本委員","kind":"提案","question":"そういう意味で、本案件に対する私どもの対応として、一つには、議会の心配事と願いを込めて、付帯決議をつけてはどうかということを考えております。この２本のことを調整していただいて、総務委員会でお諮りいただき、議会の意思としていただければ、我々は望ましいと考えております。共産党の提案も含めて次回に持ち越し、本日は継続としていただければありがたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-055"}]},{"id":"topic-03","title":"平成１４年請願第１２号、品川区私立幼稚園保護者負担教育費軽減のための請願","agenda":"平成１４年請願第１２号、品川区私立幼稚園保護者負担教育費軽減のための請願","exchanges":[{"speaker":"嶋委員","kind":"質問・要望","question":"私も、子ども２人を４年間、近くの私立幼稚園に預けたときに、毎回、こういう形で署名運動した思い出があります。そういう意味では、前向きな配慮をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-056"},{"speaker":"桜井委員","kind":"質問","question":"もう一つは、今、２，８７２人というお話があったんですけれども、この人数は増えているのか。聞くところによると、経済的な負担というのか、そういうこともあって、公立幼稚園の需要というのか、入園者というのは増えていると聞いているんですけれども、やっぱり経済的な負担というところもあるかなと思うんですけれども、その点について、どのようにお考えになっているのでしょうか。","respondent":"古川総務課長","answer":"特に３歳児が１００人ほど増えている。その中でも、先ほどちょっとお話ししました預かり保育、「きんだぁくらぶ」なんですが、これを実施されている７園のうち、半分以上の園が、この２、３年で増えているのが顕著です。","voiceIndex":140,"id":"exchange-057"},{"speaker":"桜井委員","kind":"質問・要望","question":"実際に、就学前の保育なり、教育というか、それの区への要望というのは深いと思うんです。いろいろと意見交換をされているようですので、教育、保育の内容についても、大切な子どもたちに対しての施策としては、前向きに取り組んでいただきたいということを、意見として述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-058"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"二葉幼稚園で保育園をということも、非常に園の人たちは気になさっている。そういうことからすると、東京都、あるいは国とは別に、区として区の私立幼稚園の存続価値、あるいは存在理由というのをどういうふうに考えていらっしゃるのか。さっき、「区長は」というと、区の全体の意味を指すと言っていましたから、区はどういう変化をされているのかということを聞かせていただけばと思います。","respondent":"古川総務課長","answer":"今現実に、即効性のあるというものも、なかなか難しいというふうに、私どもは考えてあります。","voiceIndex":143,"id":"exchange-059"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"課長のおっしゃることを、区全体でお気持ちの中に入れていただいて、私立幼稚園の待遇を考えていただきたいなと思います。それと非常に合致してくる部分もあるわけですね、経営姿勢として。そういう意味からも、ぜひ、できることをやって、パートナーシップというのを一つのアイデアとして、優しい目で見てあげていただきたいというのを切にお願いしたい。要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-060"},{"speaker":"藤田委員","kind":"質問","question":"今、るる質疑がありましたけれども、私も、区としても幼児教育は、私立幼稚園が抱えている問題というものは非常に大きいものがあると思います。ここで一つだけちょっとお伺いしたいのは、私立幼稚園母の会連合会への助成も合わせてと書いてあるんですが、この母の会にも、何らかの形で助成をしているんでしょうか。その１点、ちょっとお聞かせください。","respondent":"古川総務課長","answer":"この請願の３点目ですが、母の会連合会へもですが、現実的には、母の会連合会に対する補助は実施してございません。先ほど申し上げましたように、一人ひとりがまた連合会を構成する保護者ですので、保護者への補助金なり、幼稚園、あるいは協会という形になります。","voiceIndex":146,"id":"exchange-061"},{"speaker":"藤田委員","kind":"意見","question":"こういうことをおっしゃる以上は、直接、金額的な予算的な措置の支援ではなくて、区の施設を利用した、そういう応援の仕方というのもあるんではないかと思うんです。何かお考えがあれば、お聞かせください。","respondent":"古川総務課長","answer":"母の会連合会そのものへの補助ということは、従来も実施してございませんし、今後も難しい側面がありますけれども、今、藤田委員のほうでおっしゃいました、必ずしもお金ではないというような中での研究は可能であろうと考えています。お金という面では、難しいと考えています。","voiceIndex":148,"id":"exchange-062"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"先ほど来、心情的な部分、それから物理的な部分、いろいろな方面からお願いをしたところで、ぜひ、この請願は採択をしていただきたいと思います。本日です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-063"}]},{"id":"topic-04","title":"中央防波堤の帰属","agenda":"中央防波堤の帰属","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"１点だけいいですか。下関市の関係ですけれども、さっきから議論になっている個人情報保護条例とか、セキュリティの関係というのは。別に委員長に質問しているわけじゃないですけれども、もし何か参考になれば知りたいなと、そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":68757,"voices":167}},{"id":"h14-20020926-13","meetingId":"h14-cm09","date":"2002年9月26日","dateIso":"2002-09-26","committee":"清掃・リサイクル特別委員会","time":"午前１０時０５分～午後０時１０分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"最初に、１の報告事項","agenda":"最初に、１の報告事項","exchanges":[{"speaker":"上山委員","kind":"確認","question":"ひやっと何回したら何回事故が起きるみたいなことが言われていますから、職員の安全教育、それから交通教育もやっているかと思うんですが、改めて、お考えをちょっとお聞かせいただけませんでしょうか。","respondent":"山口品川清掃事務所長","answer":"私ども運転関係での技能長、専門の職員もおりますし、また、２３区に清掃事業が下りて以来、清掃事務所長会等で、交通安全の対策委員会等もつくったりして、私もたまたま品川清掃事務所の所長ということで入っておりまして、事故対策検討委員にもなって。","voiceIndex":5,"id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"今後、品川区で言えば、各戸収集をやるだとか、そういう報告がされておりますので、人数的にはこのままの体制で大体いかれるというようなことも、この前に報告されておりましたけれども、今後、仕事がそういうふうに増えたりする中で、事故がないように願っていますけれども、そういうことも含めて、もう一度、そこのところだけお願いできませんでしょうか。これで終わりにいたします。","respondent":"山口品川清掃事務所長、松本環境清掃事業部長","answer":"各戸収集につきましては、先般以来、ご報告申し上げておりますように、収集に時間がかかるということはありますが、清掃車両の運行につきましては、車両に１人の運転職員がついているという形ですので、各戸収集によりましては。そういう意味では、今後とも注意喚起、あるいは、交通ルールの講習等を充実させていきたいと思っていますので、よろしくお願いいたします。","voiceIndex":7,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"内容について、参考までにお聞きしたいんですけれども、今回２件で、毎回こういった形で提出されるんですけれども、こういった事故に対して、それに対応する専門家というか、それは保険会社がやるのか、どういう形で交渉をされるのか、そういう背景を一つ聞きたい。詳しく聞ければ、初年度の登録がいつで、どういう車種だったのか。","respondent":"山口品川清掃事務所長","answer":"示談の成立までに大変時間がかかるという部分ですけれども、申しわけございませんが、今回の例でいきますと、実際には、相手方の損害額は、委員のおっしゃるとおりですが、相手方の損害額が４８万７，３０５円。","voiceIndex":10,"id":"exchange-003"},{"speaker":"横山委員","kind":"意見","question":"随分金額がかかっているなという印象から、聞かせていただいたわけです。やはり今言うように、ベンツじゃしようがないですね。国産のちょっと古いものだったら、ここまでの補償したら車が買えちゃうような額だし、そんなことをちょっと疑問に思ったんで。そうすると、保険会社の専門家同士で決めているということですね。はい、わかりました。参考までに聞かせていただきましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区って、すごく細かい道路とか、狭い道路が多いし、駐車している車をよけながら、通っている人の安全確認をしながらという大変な作業だと思うんです、清掃車が通るのは。その面で、もちろん交通安全の確保というのは大事だと思いますけれども、さっきもちょっと上山委員が触れましたけれども、作業の効率との関係で、職員の側から出ている意見がもしあったら、聞かせていただきたいと思います。","respondent":"山口品川清掃事務所長","answer":"前段の、報告第２１号の流れというか、中身の問題ですが、私ども現場職員は、常々、地域によって、それぞれ収集しているわけですが、不燃ごみに可燃ごみが入っていれば、再三申し上げておりますけれども、中身をある程度確認させていただいて、排出者が特定できれば。","voiceIndex":15,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"確認","question":"確認の第一義的責任は収集車にあるということですけれども、私もよくごみ収集の現場を見ると、ほんとうに忙しい中に、ぱっぱっと点検しながら積み込んでいるんです。作業の効率と密度のところで、ちょっともう１回。特に何も感じていらっしゃらないのかどうか、その辺を。個々のところは、さっきの話では、研修でということで、特にないというお話だったんですけれども。","respondent":"山口品川清掃事務所長","answer":"それなりの工夫をしながら収集していると考えております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そこら辺のところの見極めを、どのように指導をされていて、また、それを出した方がわからないという話なんですけれども、基本的に、聞き取り調査をすればわかるような状況だと思うんですが、そこら辺のところがわかったのか、わからなかったのか教えていただきたいというのが１点。先ほどちょっとお話があったから、そこの点を確認をしたいと思うんで、そこら辺だけ教えてください。","respondent":"山口品川清掃事務所長、中山清掃リサイクル課長","answer":"前段もご説明しましたように、４缶ほど中を開けまして、中身がビニールですとか不燃ごみが入っていたので、十数缶、収集職員としては同じであろうということで、積み込んだために。各戸収集の今後の展開に伴う人員等の配置の関係のご質問でございましたけれども、今年度、間もなく１０月１日からという形で、約７，０００世帯で、両清掃事務所３カ所ずつで回収するものにつきましては、現在の態勢の中で。","voiceIndex":19,"id":"exchange-007"},{"speaker":"石田副委員長","kind":"確認","question":"もう一度、確認のためにお伺いをしておきます。先ほどの答弁の中で、十数個あって、１個に入っていましたと。４個ぐらい確認したけれども、すべてが確認できなかったと。そういう答弁の中で、６回の中では難しいということなら、現体制ではできなくて、人を増やせという話になってしまうわけで、今まで、清掃リサイクル課のほうで言っている答弁とは大きく違うわけなので、ここだけは、再度確認をしたい。","respondent":"中山清掃リサイクル課長","answer":"所長が申し上げたように、基本的には、そういうものについて注意、喚起をし、交通事故しかり、作業上の事故しかり、基本をきちんと踏まえて、安全運転、安全作業手順というものを踏まえてやっていくように周知することで、本来防げるものだと認識しております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問・要望","question":"それはわかりました。そういう形で進めていただきたい、職員にも、そういう形でやっていただきたいと思います。これは、清掃車と出ているんだけれども、ごみの収集車という話もあるんだけれども、活字にする場合、ほんとうはどういうのかということを聞かれて、私は非常に困っちゃったんだけれども、それをちょっと教えていただきたい。","respondent":"中山清掃リサイクル課長","answer":"こういう資料づくりの際に、より的確な表現があるのかということについては、ほかの資料の扱い等も見ながら研究をしていきたいと思います。","voiceIndex":24,"id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"今の話というか、確認でちょっとお聞きしたいんだけれども、直接報告第２１号、２２号には関係ないんだけれども、今、出てきた話で、答弁の中で、品川区の今後の収集のあり方として、５年をめどに全地域で各戸収集を行っていきたいと、これはもう区の最終的な目標なんですか。これは大きな方針だと思うんで、そこだけちょっと聞かせてください。","respondent":"中山清掃リサイクル課長","answer":"先ほど申し上げたのは方針ですけれども、基本的には、そのような形でやっていきたいと考えておりますが、今、委員もおっしゃったように、地理形状から、どうしても個別収集になじまない部分、あるいは、モデル事業の中でも出てまいりましたけれども、実際に住民の方から。","voiceIndex":26,"id":"exchange-010"},{"speaker":"横山委員","kind":"意見","question":"方向的にはわかるんですけれども、区民に尋ねれば、楽したいから各戸収集をしてくださいというのは、当然出て来る言葉ですよね。それに甘んじてやっていくと、私は、大変なことになるんじゃないかなという部分もありますので、今、お答えがあったような形で進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-011"}]},{"id":"topic-02","title":"続きまして、報告事項(3)、廃棄物減量等推進員の活動状況","agenda":"続きまして、報告事項(3)、廃棄物減量等推進員の活動状況","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"いろいろあると思いますけれど、一人で全部やっちゃうといけないので、１点、２点だけ。今、コンビニ等で店頭回収を１８６カ所でやっているということですけれども、これを公共施設に拡大してもらえないでしょうか。だから燃えないごみですよね。それから、回収の１kg当たりの単価のことなんですが、これはどうしても東京都資源回収事業協同組合品川支部にやってもらわなきゃいけないのか。お願いします。","respondent":"中山清掃リサイクル課長","answer":"３点目の単価のことですが、実は、シルバー人材センターへの委託につきましては、前回、ご説明した拠点回収等の選別というのはシルバー人材センターに委託をしてやっていただいておりますが、大量に出てくるものを一気に選別にして機械にかけていく作業となると。","voiceIndex":36,"id":"exchange-012"},{"speaker":"川西委員","kind":"質問・要望","question":"集積所の拡大については、今の１８６カ所の分布図も一回検討していただきたいと思います。うちに帰れば要らなくなっちゃうでしょ。今、若い世代と言っては悪いんだけれども、５品、夕食の料理があれば、３品ぐらいはああういものを買ってきて用意するぐらいに変化してきている。ですから、あれから始めたらいいと思うんです。マヨネーズのびんまで拡大しないで、ぜひ細かい工夫をお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"嶋委員","kind":"確認","question":"一つ確認をしたいんですが、やはりペットボトルの店頭回収の件なんですが、ここには、「スーパー・コンビニ等事業者が回収ボックスを設置し」とあり、その後に、「不特定多数の区民がペットボトルを回収ボックスに投入した後、区が回収する方法」と書いてあるんですが、スーパーよりコンビニが多いので、大変嬉しいことなんですが、逆に、コンビニの入口に行ったときに。","respondent":"中山清掃リサイクル課長","answer":"その辺は、店舗ごとへの周知の仕方ですけれども、例えば清掃事務所等でも、収集ルートをつくる際に、コンビニエンスストアと担当が接触する場面がありまして、資源はきちんと、ごみを持って来ないようにという誤解のないようなわかりやすい周知をするような形は。","voiceIndex":39,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"しかし、品川区といろいろな状況、規模が同じとよく例に出されている北区と比較すると、北区では４万９，５００カ所もあると書いてあるんで、どういうふうになっているのなかなと、北区に伺いたいと思っているんです。私がさっき申し上げたように、品川区は決して少ないとは思っていないんですけれども、分布状況としてはどうなっているか、ちょっと伺いたいんです。","respondent":"中山清掃リサイクル課長","answer":"品川区の集積所というものは、以前は、例えば９，０００カ所とかだったんですが、これも日々動いておりますので、約ですけれども、１万５００に増えております。","voiceIndex":41,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"したがって、その方は、どうしても燃えないごみ、燃えるごみに出しちゃって、分別収集に参加できないと言っていられたんです。あるんであれば、どういうふうな検討をされつつあるのかを、ちょっと伺いたいんです。","respondent":"中山清掃リサイクル課長","answer":"その間に、コンビニエンスストア等に、空白のあるポイント等については、何らかの対応ということも踏まえて考える必要があろうかと思います。","voiceIndex":43,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、品川区だけに求めるのではなくて、いろいろな排出、あるいは製造する立場のところへの働きかけというものも、ほんとうにしていかなきゃいけないんじゃないかと思いますので、そういう点での、当委員会としての役割として、そういう方向にも持って行けるように、ぜひとも委員長のところで、ご指導をしていただきたいと思いますが、その点については、いかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"個別具体的なものとしては、先ほどのコンビニエンスストアへの対応という部分もありますけれども、片や２３区全体、あるいは、都、国を通じての協会への働きかけ、法の趣旨の徹底を含めた動きというものはやっておりますので、この辺は。","voiceIndex":45,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"課長の説明では、やってはいるということで、そのとおりだと思うし、何回かこういう委員会を通じても、いろいろ私たちも要望をしていますので承知しているところですが、なかなか動きとして見えにくく、自治体の責任のところにかぶってきている状況が、やっぱり依然としてありますので、極めて残念だなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"委員長のご発言がございましたので、それを受けてといいますか、お伺いしたいんですが、私が間違った理解か、極めて個別的な問題になってしまうかもしれないので、その点を、ちょっとご了承いただきたいんですけれども、２番目のペットボトル店頭回収の中で、スーパー・コンビニ等とありますが、「等」の部分で絡むんですが、私の知り合いの酒屋が、それまでは、びん、缶。","respondent":"中山清掃リサイクル課長","answer":"ただし、やはり事業活動に伴って出される資源物を、やむを得ず事業者がルート構築できないために行政が収集するという場合については、やはり一定の、「一定の」というのが、ごみと同様でいいのかということはありますが、費用負担はお願いせざるを得ないのかなと。","voiceIndex":49,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"資源回収の循環をよりよくする上では、回収拠点を増やすということが、非常に効果的だと思われますので、確かに、酒屋をはじめ、自己処理という部分の責務といいますか、責任も負ってもらわなきゃいけない部分だろうと思いますが、その辺をどう判断するのかだと思います。という観点で、お伺いしたんです。ちょっと最後に。","respondent":"中山清掃リサイクル課長","answer":"ただ、そうすると、自分のお店のほうで売られるものとの区別をどうするかと、非常に難しい面もありますので、そういう微妙なケース等については、個別にご相談に応じなきゃいけないと思います。","voiceIndex":51,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"今回のテーマである、資源回収をより促進するという観点からすると、個人的な意見ですが、お店で販売されたものも含めて、回収しやすい環境にしたほうが、この趣旨には沿うだろうなと思いますので、その辺を含めてご検討をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-021"},{"speaker":"上山委員","kind":"質問","question":"非常に初歩的な質問でお恥ずかしいんですが、ペットボトルの店頭回収にかかわってお尋ねしたいんですが、２番目のペットボトル店頭回収量および回収方法とありますので、この説明とのかかわりなんですが、5)のところで、「一定の量になったら再資源化利用（容器包装リサイクル法）に払い出しする」ということで、費用負担を持つということで、例えば平成１３年度で言えば。","respondent":"中山清掃リサイクル課長","answer":"行政は、これに対しては、負担割合は１％だけという形です。払い出した後の９割９分は事業者によりリサイクルするという形になっています。","voiceIndex":54,"id":"exchange-022"},{"speaker":"上山委員","kind":"意見","question":"どんどんつくったらどんどん金ばかりかかってくるので、業界も含めて、国民全体で、見直しなどを含めて、ほんとうに国民的な課題として考える必要が、今、改めてあるのかななんて、ちょっと感覚的な意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"川西委員","kind":"質問","question":"今の関連で。再生品の需要と供給の関係はどうなっているのか。ペットボトルの再生品がいろいろ出回って、買うようにはしているけれども、限界がありますね。その辺の今後の見通しとか。工場って、近くにないですか。横須賀のこれはそうですか、すみません、その辺についてお聞きします。","respondent":"中山清掃リサイクル課長","answer":"ただ、これは世界的にはトップの数字だというふうに、国は言っております。かつて１割いくかいかないかが、今は４割です。ここ１、２年のうちに５割を超えさせたいということで、国は考えているところです。","voiceIndex":57,"id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"粒状は見たことがあるので、洋服になったり、ボールペンをつくっているところはどこにあるんですか。","respondent":"中山清掃リサイクル課長","answer":"その後は、いわゆる原料の再生場所ですから、いろいろな企業でつくられております。全国各地かなりのところに行っているということなります。","voiceIndex":59,"id":"exchange-025"},{"speaker":"横山委員","kind":"質問","question":"３ページの下のほうにある支援で、要するに古紙の現在の問屋価格は幾らですかね。７円で、それを上回ったり、下回ったりして、仮に下回った場合は３円を限度に支援するということで、ここのところずっと毎年うなぎ上りに上がってきている、それの補助だと思うんです。","respondent":"中山清掃リサイクル課長","answer":"古紙の中でも、種類によって実は違ってきておりまして、典型的な新聞紙で言えば、今は、１kg５円になっています。私どもも四半期ごとに相場を調べて、契約を変えるようにしておるんですが、実は、それ以前はもっと下がっておりました。","voiceIndex":61,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"意見","question":"きょうは、すごく勉強になったなという気がします。回収業者への支援額とか、こういうことも知らなかったんで、すごくいろいろなところでお金が動いているなという思いがしたんです。お金の動きが、ほんとうに見にくいなと思っているんです。だから、その辺をちょっと比較できるように。","respondent":"中山清掃リサイクル課長","answer":"ただ、もう少しこのプロセスの中で幾らぐらいかかっているか、容器包装リサイクル法でどうかとか、このぐらいの資料はつくれるかと思いますので、その辺は、もう少しわかりやすく、今後つくっていきたいと思います。","voiceIndex":63,"id":"exchange-027"},{"speaker":"本間委員","kind":"質問・要望","question":"大体、６時半ぐらいから始めて、約１時間程度ですが、そうしますと、問い合わせる業者は、７時以降じゃないとやり取りできない。これについてのアドバイスを、ちょっといただきたいということがあります。それから、二つ目は、空き缶の部分の実績を見ますと、回収量が下がっていると受けとめらよろしいのかどうか。それは、回収量が減っているのかどうか。この２点について、お伺いします。","respondent":"中山清掃リサイクル課長","answer":"１点目の、集団回収等で払い出しするときの判断ですけれども、私どもであっ旋した事業者の電話等についてはお伝えしているところですが、今言ったように、時間的に間に合わないようなケースということになると、なかなか難しいんですが、おそらく昨今ですから。","voiceIndex":66,"id":"exchange-028"},{"speaker":"本間委員","kind":"質問・要望","question":"２番目の部分はやめておきます。１番目の部分は、携帯電話があるということがあっても、一番いらいらするのは、相手と連絡が取れない状態なんです。もしあれでしたら、こういう方法もあるじゃないかという部分は、逆に親切な指導をしてあげたらよろしいのではないかと思いますので、要望としてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-029"},{"speaker":"石田副委員長","kind":"質問・要望","question":"すみません、１点だけ。ほんとうにこれがリターナルびんかどうかという確認が、ビールとお酒の２種類ぐらいはぱっとわかっても、各メーカーのこのびんだけはリターナブルしていますとか、いろいろ持っているんですけれども、その選別を、どのぐらい指導されているのか。そこに選別している人に、どういう指導をしているのかというのが１点。","respondent":"中山清掃リサイクル課長","answer":"１点目の割合については、今手元になくて、ヤードでやっている本数がわかれば、別途お知らせしたいと思います。","voiceIndex":69,"id":"exchange-030"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ言っておきます。今、おっしゃったことは大切で、今言ったびん商とか、酒屋でも、必ず回ってないぐらいですが、例えば、これは生きびんですというポスターがあったりするので、そういうのをぜひ区で、業者に言えるのか、どこでお金を出してもらうかという問題はあるけれども、それを各戸に配るとか。それだったら、生きびんは酒屋にお持ちくださいと。その点だけ、それは要望にしておきます。","respondent":"中山清掃リサイクル課長","answer":"例えば、インターネットのホームページによる周知だとか、比較的やれるものなんかを工夫しながら、今の趣旨を踏まえてやろうと思います。","voiceIndex":71,"id":"exchange-031"},{"speaker":"辻委員","kind":"質問・要望","question":"今、まさしくそれなんですよ、ホームページ。というのは、時期で動く問題については、それで間髪を入れずにやる。だから、先ほど聞いたでしょ、きょうは雨でだめですよというのは、中心にする人はいるんですよ。新しい活動の中に、そういう形の利用の仕方というのを、実際に講習でやっていただきたい。これも、時間がないので、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"嶋委員","kind":"質問","question":"ちょっとすみません、よろしいでしょうか。先日、９月４日付の朝日新聞を見ましたところ、品川区のＩＳＯ１４００１の取得で、４，８００万円の削減効果があったと載っておりましたが、もし感想があれば、アピールなどありますでしょうか。すばらしいことなので、ぜひ。","respondent":"松本環境清掃事業部長","answer":"所管の区民委員会ではご報告を申し上げたところです。よろしくお願いします。","voiceIndex":81,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5674#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":37218,"voices":83}},{"id":"h14-20020926-16","meetingId":"h14-cm09","date":"2002年9月26日","dateIso":"2002-09-26","committee":"街づくり特別委員会","time":"午前１０時０５分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"この第３地区の計画については、以前のまちづくり委員会、あるいは都市計画審議会などで発言させてもらいましたけれども、改めて条例上で明記をするということなんで、多少重複するかもしれませんけれども、質問をさせていただきたいと思います。とりあえず２点。","respondent":"南雲都市開発課長","answer":"就業人口それから夜間人口ですけれども、この東口第３地区において、まず就業人口は、現在の大まかな試算として３，２００人という数字が出てきました。","voiceIndex":6,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっとその権利床、保留床割合というのは、開発の条件が容易なのか、困難な方向に全体の開発は向かっているのかというのを示すものになるわけで、中地区は、だいたい３割強と言うからわかりませんけれども、権利床が増えれば増えるほど厳しいという状況になるわけです。わからないならわからないでいいんですけれども、わかったら教えていただきたいと思います。","respondent":"南雲都市開発課長","answer":"これも現時点ではまだ確定しておりませんが、まず東口第３地区、今回都市計画を定めております時点で、一緒に開発をしておりますティクスという会社があります。こちらを含めたもので５，２００台。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのことによって出てくるＮｏｘだとかＣｏｘが一体どれぐらいになってくるのか、ヒートアイランド現象に寄与するのがどれぐらいになっているのかという、１つ１つと同時に、都市計画なんですから全体でそれが環境にどういう負荷を与えていくのかということを考えなければ、いわゆる合成の誤謬で、１つ１つはいいかもしれないけれども、全体を見たらば取り返しのつかない環境破壊。","respondent":"南雲都市開発課長","answer":"全体的に考えますと、この開発を行ってオフィスビルを建てる、これは全体を量を増やすというよりもコンパクトにまとめるということで、機能的な建物にコンパクトにまとめていくことによって。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"例えば今年の夏、３０度を超える真夏日というのは例年で３８日なんですけれども、今年は５３日になっているんです。これの割合が年々ひどくなってきているわけですから、私は都市再生でこれ以上環境に負荷をかけるような開発というのはここで思いとどまって本来なら見直さなければ、ビルは助ける、人間は住めない、みたいなことになりかねない。一応私のほうの質問はそこまでで、とりあえず終わります。","respondent":"岩野まちづくり事業部次長","answer":"それが敷地の内外で１万１，０００平米という緑地ができるということがありますので、そういうことを勘案し、そのほか省エネルギー的な装置も幾つか導入していますので、そういうことを通じまして、今のヒートアイランド等の環境問題にも対応しています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"私はついでだから言いたいと思うんですが、私の近所のマンションの方から、上へあがって見てくださいというので、そのマンションから海のほうを見たんです。だから、そういう点は、個々の問題で６０平米の緑地が１万になったとかというんじゃなくて、やっぱり全体としてのシミュレーションをやって、プラスマイナスどうなのかということをやらなければ、私は責任を持った答弁だとは思いません。","respondent":"岩野まちづくり事業部次長","answer":"今、とりあえず東口の第３ということでもって数字がございましたのでご報告しただけでございまして、これは東口の第３ばかりじゃなくて、先ほど課長のほうからも答弁しましたけれども、東五反田、それから大崎の西口を通じて。","voiceIndex":14,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと重複するかもしれませんけれども、お許し願いたいと思います。この資料の表の中で、建築面積の最低制限が２００平米で敷地面積の最低限度が約５００平米と、もう少し説明を加えていただきたい。どういうイメージなのか、それについてご説明いただきたい。","respondent":"田平建築課長","answer":"建築面積最低２００平米、敷地面積は最低５００平米、つまり２００を５００で割り返していただくと、簡単に言ってしまえば建ぺい率４０％の建物が想定できるという意味です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"塚本委員","kind":"意見","question":"別の話を聞くけれども、当該地区の道の取り分けなんですけれども、取り分けが同時進行するわけじゃないですけれども、一番大事なのは道をしっかりつくっておいて、工事車両等が近隣に迷惑かけないようにということが大事なことだと思いますけれども、一番心配しているのは環６の跨線橋のところの取り合わせが概略図を見ますと、現状でもあの辺は知っている人じゃなきゃ入っていけないようなところでして。","respondent":"南雲都市開発課長","answer":"ただ、それだけでは南側の環６へのアクセスができませんので、今回の第３地区の開発の中でも環６との車のアクセスの改善ということで、この図面でいきますと、環６の下のところの車道の部分、これを整備するということになっておりますが。","voiceIndex":21,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"今の説明で後段の部分は、環６とのアクセスということですけれども、色が塗ってあるところは一方通行、北から南へ抜ける道ですね。線路際のほうに逆方向に一方通行という格好であると思いますけれども、要するに道路の状態は再開発が始まっても基本的に変わりはないということですか。それを確かめたいと思います。","respondent":"南雲都市開発課長","answer":"後者についてはここは狭いということで、上にぺデストリアンデッキをつくりまして、歩行者と車は分離するという考えで、この図面では青の点線部分、ここが歩行者専用のペデストリアンデッキを上空に架けるです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"現場からいうと、今でも非常に狭いところで、あそこに工事車両が出入りすることに、北から南に環６に出てくるというのは非常に困難であるというふうに思います。しかし、これだけで、あるいはぐるっと抜ける道を、また東五反田２丁目のほうに抜けるということは、これは既存の道ではないわけですから、再開発の進捗を待たないといけないということだろうと思いまして、いろいろ心配を持っておられる。","respondent":"南雲都市開発課長","answer":"ということで、この地区内、各開発に伴って、幹線となる道路、橋などを整備しながら、将来的には目黒川を渡る橋というか通路をもっと充実していくという構想を検討しております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"私が聞いたのは、計画に直ちに参加しない地域もあるもんで、そこがネックになっているだろう。特に環６とのアクセスについて今後問題となるだろう、それに対する対応策を改めてお聞かせいただきたい。","respondent":"岩野まちづくり事業部次長","answer":"お手元の図面でもって、ニューシティのほうとそれから東口の第３、これをやって目黒側に沿った通りが通行できるようになれば、今の部分のご懸念もかなりの程度軽減できるということでございまして、今その間に千代田グラビアがございまして。","voiceIndex":27,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"ある程度わかりましたけれども、いずれにしても環６とのアクセスは余りよろしくないという面があるので、何か対策をお考えになったほうがいいのではないかと思います。千代田グラビアさんとつながると言いましたけれども、ここのところもやはり同時進行のような形になればベターであるのは間違いないわけですから、ご努力をお願いしたいということを要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"桜井委員","kind":"提案","question":"だから、今の時点で開発組合の組織状況というんでしょうか、入会状況というんでしょうか、それを聞きたいのが１点と、それから、借家の方が６０名、あの回ったときにアパートが幾つか見受けられましたし、そういう方々がどういうふうな状況なのかという実態、それが権利者関係。都市再生特別措置法に基づいて。それとの関係は全くここは従来どおりという理解でいいのかどうかを教えていただきたいと思います。","respondent":"南雲都市開発課長","answer":"この中で、工場などを営業されている権利者は７権利者ほどありますが、このうち１社が現時点で対応をまだ考えているということで、そのほかにつきましてはもう既に工場機能を移転してあるところなどがありまして、権利床の床に権利を変換することを希望しているということで。","voiceIndex":30,"id":"exchange-012"},{"speaker":"桜井委員","kind":"提案","question":"先ほどの総事業費と補助金ですけれども、これは当初の提案されていたのと違うような気がしているんですけれども、最近、１０２億の補助金になったのはいつからなんでしょうか。それから、先ほどの保留床の関係なんですけれども、３社というのは大林組と日本舗道と旧住都公団という理解なんでしょうか。不動建設ではない、３社というのはもう１度確認をしていただきたいと思っています。","respondent":"南雲都市開発課長","answer":"工場を営業されている方の対応ですが、この代替地というのは具体的に代替地をあっせんしているということではなくて、今後その工場をおやりになっている方との協議の中で、その方の意向によって代替地が必要であれば準備組合のほうでそういうものも探してあっせんする。","voiceIndex":32,"id":"exchange-013"},{"speaker":"桜井委員","kind":"質問","question":"さっきの事業費のことが漏れていたので、もう１度聞きたいんですけれども、アセスの対象になっていないまでも、さっき言った住宅がつくられるということによっての影響、そういうこともきちっと考えていく必要があるんじゃないかということも質問したんですけれども。","respondent":"南雲都市開発課長","answer":"事業費ですが、事業費というのは実際に設計が全部完了した段階で確定するもので、これは現状では見込みということで、今回都市計画を定めるということで、東京都との都市計画の協議が定まりまして、その時点で、その想定される設計内容をもとに見積もりを行った結果です。","voiceIndex":34,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"これは、今後いろいろなところで、ミニ開発的にあるという意味では、それこそまとまった土地を共同住宅、共同ビルを建てるとかという形で行われていくということになると、そういうものができ上がった段階でそういう現象が起きてくるわけですから、そういうことを解消させていくためのきちっとしたそういう方針ということを取り組んでいかない限り、解消はされないということであれば。","respondent":"南雲都市開発課長、田平建築課長","answer":"この施設の計画では、今後具体的な施工を行っていくわけですけれども、この中でも、資源の消費を削減するということ、それから環境への負荷を削減するということで、省エネルギーですとか。区全体のあり方の問題については、みどりの条例の改正が動いている。今後の法律や改正の動向を見ながら考えていく要素の１つではあると思っていますが、現段階での条例規制についてはこのようなものでお願いしたいというふうに思います。","voiceIndex":37,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"だから、そういったところについての新しい技術というものがどうなのかということについても、貪欲な限りの研究心を持ってもらいたいし、そういう意味にあっては、新しく導入する部分についても、そういったものははっきりと、新たにこういうふうな形で文書にして、条例には載っていないけれども、こういった形でこうしますよというようなことがわかっていくような今後の建築指導なり。","respondent":"岩田管理工事課長","answer":"これが近隣の建物にどういう影響があるのかということはまだまだこれからの研究課題になっていますので、そういったいろいろなメーカーの動きとか、他官庁の動きというのも我々、今注意深く見ておりまして。","voiceIndex":40,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"よろしくお願いしたいと思います。それは日進月歩の時代ですから、技術というものはどんどん変わっていくかもわかりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-017"},{"speaker":"北野委員","kind":"質問","question":"この中に再開発の地区計画、今、整備計画というのが出ていますけれども、建築基準法との兼ね合いの中で決めていかれるのかどうかわからないんですけれども、この内容の決め方、最高建物とか、建ぺい率の最高限度とかいうところの決められ方がどういうふうな形で決められていくのかをお伺いしたいと思います。","respondent":"田平建築課長","answer":"１点目の条例の提案時期というお尋ねですけれども、大崎第３地区で例えれば、６月に都市計画決定を終えたと。ある意味でそれに直近の時期の定例会にかけていくことによって、一刻も早く条例で担保できますから。","voiceIndex":44,"id":"exchange-018"},{"speaker":"北野委員","kind":"質問・要望","question":"告示された直近でなるべく早く着手ということで今回出されたことは理解しましたけれども、７月５日の街づくり特別委員会の中では、既にこの大崎の第３地区のイメージ図が出された中で、結局今回出された中にも予定図として出されたわけですが、これが実際には案という形で決められる、こういう形になっていくとは限らないとは思いますけれども、既にこういうものがあって、それはもう建つものですから。","respondent":"南雲都市開発課長","answer":"それからもう１つ、空地についてですけれども、この地区は従前は工場などが建っていまして、高さの低い工場などの建物が密集していて、空地も余りないという状況なんですが、このカラーの配置図にありますように、この地区に新しくできます建物は。","voiceIndex":46,"id":"exchange-019"},{"speaker":"北野委員","kind":"質問","question":"総合設計の中にもあるわけですから、そういう手法はわかります。しかし、ここにこういう建物ができて１つのまちづくりと考えたときに、狭い意味だけでも、この緑がここの中で本当にこの熱量を発生する自区内処理というか、地域内処理というか、そういうことも想定された緑のつくり方、エネルギーの省エネの仕方というのもやはりこれからは考えていくべきではないかと思いますけれども、いかがでしょうか。","respondent":"南雲都市開発課長、岩野まちづくり事業部次長","answer":"都市計画の中で省エネルギーに関することは定められておりまして、今回定められた都市計画ですけれども、建築物の整備の方針ということの中で資源の有効利用、建築物の省エネルギー化を推進し。ただ、それが具体的にどういう効果があるのかというような、いわゆる定量的な分析というのはまだやってございませんので、これから事業を進めていく中でこの緑化がどういう効果があるのかといったことも含めて。","voiceIndex":48,"id":"exchange-020"},{"speaker":"北野委員","kind":"質問・要望","question":"ありがとうございました。行政の部分でどこまでかかわるのかというのはあるかもしれませんが、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"４点にわたって反対の意見を述べたいと思います。これが２点目。それから、最後ですけれども、２００３年問題で再開発をしたところには入ってくるという答弁がこの間あって大丈夫だということを言いましたけど、そうしたら中小ビルがあくじゃないですか。今度２００３年問題で、バブル時代の倍の建物が来年建ち上がってくる。以上、４点の立場から反対をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"桜井委員","kind":"質問","question":"この２ページの地元の対応の件でお尋ねしたいんですけれども、地元の皆さんのご努力もあって対策協議会が設置されて、私どもも毎回呼ばれて傍聴的な形で参加しているんですけれども、特に今、到達点というんでしょうか、毎回５０名を超える方々が参加されて、そこでの話し合いの到達点を区側としてはどういうふうにとらえているかというのを聞きたいのです。前提の到達点のことはちょっと教えてください。","respondent":"中島街路事業担当課長","answer":"協議会が６回開かれていまして、これは地元の方たちが主催してやっている協議会でございまして、この間の事業説明会、補償説明会でもそうなんですけれども、地元の方が一番関心を持っていることはやはり補償の問題なんです。","voiceIndex":63,"id":"exchange-023"},{"speaker":"桜井委員","kind":"提案","question":"ですから、部署としての商工の部署、それから街づくりの部署がありますけれども、区政全体のところでこの問題を考えていくというふうにしていかないと、なかなか一部署だけでは解決しきれない要素があると思います。この問題はまた一定いろいろな形で提案もし、申し上げていきたいというふうに思っておりますけれども、引き続きいてぜひそういう体制も含めてお願いしたいなという要望とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"この一本橋のところは拡幅されて広くなる、それから大井町駅のところからも既にできているという状況なんですが、ちょっと１つ気になっているんですが、そこのガードのところも拡幅されるんでしょうか。","respondent":"中島街路事業担当課長","answer":"この区役所を抜けた２６号線にぶつかったところのガードですね。あそこは、今回の事業化区間には入ってございません。","voiceIndex":67,"id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"せっかく交通渋滞を緩和するために拡幅されるという計画だと思うんですが、あそこのところできゅっと狭くなった感じでどうなのかなと。今でもとても混雑していますよね。そういう部分をやはり考えていかなければいけないんじゃないかと思うんですが、どのようにお考えですか。","respondent":"中島街路事業担当課長","answer":"私どもは、今回の事業認可をとってありますけれども、次の公共の課題というのは、やはりあそこのガードを含めて、区役所の前の部分をなるべく早く整備していく必要があるのではないかという認識は持ってあります。","voiceIndex":69,"id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"そうした場合、今自分の土地を手離すときに法的ないろいろな問題が出てくるんじゃないかとか、売ってその次の場所が見つからないときに税金の問題とか、そういった問題を心配されている声も出ておりますが、こういうことに対しては、区としてはきちんと対処されるようになっているんでしょうか。","respondent":"中島街路事業担当課長","answer":"それと、税金の問題につきましても、譲渡所得という形になりますので税金の対象になるわけですけれども、これにつきましては当然税務署等と連携をとりながら、私どもでできる範囲のお知恵をおかしするということで。","voiceIndex":71,"id":"exchange-027"},{"speaker":"中島委員","kind":"提案","question":"本来であれば、道路ができなければそのままいられる方たちが、いろいろな生活の変化があるわけですから、最善を尽くしていただきたいということと、ここまで広がる、道路がきれいになるわけですし、大井町から正面にぶつかってくる商店街ということでは、先ほど桜井委員が言われたように、私も本当にここら辺の地域の大きなメリットになるようなまちづくりの計画を、区としても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-028"},{"speaker":"北野委員","kind":"質問","question":"物件調査実施件数というのが内訳３６件と出ていますけれども、借家人調査件数の１６件というのは、どういう立場の借家人なんでしょうか。","respondent":"中島街路事業担当課長","answer":"そういった意味では、例えば借家人の方はアパート住まいの方でも、普通の全部用意されたところに入るわけですけれども、特にそういった部分で後から何かをくっつけたりということはできないわけですけれども、そういった方の場合、荷物がどのぐらいあって。","voiceIndex":75,"id":"exchange-029"},{"speaker":"北野委員","kind":"質問・要望","question":"そうすると、ここが決まってしまうと、商店街と１５メートル道路の町並みが、自分たちが望んでいるものにならないのではないかというようなことをお聞きしているんです。そうしたときに、この道路の歩道に対しては、やはり１６３号線の沿道の方たちにはこういうものになるということはきちんと説明して了解を得たということで、本整備という立場に立ったのかということをお伺いしておきます。","respondent":"中島街路事業担当課長","answer":"確かにシンプルでいいなというのはあるんですけれども、私ども、１６３号線の整備全体で考えますと、歩道については明るめな色を使っていきたいという思いを持ってあります。その辺はこの間、商店街の方たちと話をしている中では同じ思いを持っているわけですけれども。","voiceIndex":77,"id":"exchange-030"},{"speaker":"北野委員","kind":"質問・要望","question":"やはり町並みというのが、商店街存続に向けても買い物しやすい雰囲気になったりもしますので。確かに借家人の方たちがどういうふうにしたらいいかというのも困っていて、実際に土地所有の方、建物を持っていらっしゃる方がそこに住んでいないから、なかなか交渉まで行きにくいということもあるので、ぜひ地元の方々の立場に立って進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"宅建品川支部との協定についてお聞きしたいんですけど、これは参加する方は減額するということは、宅建のほうがそっくりその部分が減ってしまうというふうに単純に考えていいのかどうか。その辺が制度でどうなってくるのかなというので。例えば、既に今でも申し入れしているよとなってしまうと、この６カ月の期限というのは非常に短縮されてしまう。そこら辺はどうなっているか。その２点だけお願いします。","respondent":"中島街路事業担当課長","answer":"私どもは申し出するときには、当然契約がいつごろになるかということを想定しながら、税務署と相談しながら申出日を決めていくですので、そういった部分では実際地権者との関係で、６カ月という期間がネックになったり。","voiceIndex":80,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと確認なんですけれども、申し出というのは、契約金額を提示した時点が申出日になってしまうのか、それよりもっとぎりぎりまで引っ張っていって、そこからでいいという、そうしないと売り主さんに迷惑がかかってしまう、その方が損になることは絶対にないというふうに考えていいかどうかということです。","respondent":"中島街路事業担当課長","answer":"そういうふうになることは、不利益になったりすることは一切ございません。","voiceIndex":82,"id":"exchange-033"},{"speaker":"桜井委員","kind":"確認","question":"１点だけ確認しておきたいんですが、今の１６３ではないんですが、いいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-034"},{"speaker":"桜井委員","kind":"質問・要望","question":"１点だけなんですけれども、ある再開発の地区にこういう問い合わせがあって回答があったので確認したいんですが、都市再開発法の中で組合設立以降事業が頓挫した場合、地方公共団体が代行するというふうに法律では書いてあるけれども、その確認をしたいんですけれども。わかる方、お答えいただけますでしょうか。実際そのことが実施されたところもあれば、教えていただきたい。","respondent":"南雲都市開発課長","answer":"ただ、その組合が事業を進められなくなった場合に、その事業を地方公共団体が引き継いでいく規定はありますけれども、ただ、実際にはそういうことが行われたということはまだないということで、実際はその前にいろいろな手が打たれますので。","voiceIndex":92,"id":"exchange-035"},{"speaker":"桜井委員","kind":"質問","question":"そうすると、都市再開発法の第何条に書いてあるのか、そこだけ教えてください。後で調べます。","respondent":"岩野まちづくり事業部次長","answer":"若干補足しますと、地方公共団体の代行につきましては、組合ができまして権利変換計画の認可がされた以降挫折したというのが代行制度の趣旨でございまして、ちょっと記憶に間違いがなければ、再開発法の第１１２条です。","voiceIndex":94,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6242#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":37939,"voices":97}},{"id":"h14-20020927-14","meetingId":"h14-cm09","date":"2002年9月27日","dateIso":"2002-09-27","committee":"行財政改革特別委員会","time":"午前１０時０５分～午後２時０６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"いろいろ作業を見せていただいたんですけれども、幾つかお聞きしたいんですけれども、雨水桝ですか、あの清掃ですとか剪定作業なんかを見せていただいたんですけれども、ああいう作業、個別の一つ一つの作業なんですけれども、例えば桝の清掃なんかですと、年間一つの桝を何回清掃するかとか決まっているんだと思うんですけれども、その見直しそのものも、まちづくりの中でやるのか。","respondent":"松代道路公園課長","answer":"その辺は、今までの経験上、それぞれに清掃回数を多くするところ、例えば月に１回するところ、それとかあと集中豪雨等で非常に被害等が出やすい、例えば今回も出ました西品川とか、そういったところを中心に大体路線がわかっておりますので、そういったものについては。","voiceIndex":3,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"例えば今の雨水桝を全面的に業者に委託をしたというときに、例えば職員、この間の作業の予定表ですとか計画ですか、作業の計画だとか実施とかといいますと、かなりそのときの天気ですとか必要性で、計画とはまた、実施はかなり臨機応変にやられているみたいですけれども、実質問題として委託をする場合には、当然例えば一つの桝を清掃してもらって幾らという、計算上はそうなっていくんでしょうけれども。","respondent":"松代道路公園課長","answer":"１点目の、臨機応変の作業に対する対応です。これは、今後十分に考えなければいけないという点だろうと考えています。将来的には３事務所、２班、２４名ということです。","voiceIndex":5,"id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"それで、どこをどういうふうにするということはこれから出てくるだろうと思うんですが、３番で、作業内容ということで、道路、公園、河川というところでいろいろな作業をするわけですけれども、それと、資料２にも４０にわたる作業が掲載されているわけですけれども、この中で委託ができない業種、今の段階で委託ができない。","respondent":"松代道路公園課長","answer":"ですから、これはケース・バイ・ケースで出てくるかと思いますが、この辺のことは、さらに今は単純な清掃等で委託化を図っておりますが、今後いろいろと講習を重ね合わせて、現場の維持管理に合う、また効率的に執行できるようなものを検討していかなければいけないだろう。","voiceIndex":7,"id":"exchange-003"},{"speaker":"原委員","kind":"提案","question":"その区民サービスと委託化をどこで接点を設けるかというところが非常に大事だと思うんです。行革の中で、今までいろんな形で提案、提言をさせていただいてやってきましたけれども、それはあくまでも民間サービスを落とさないでもって、その上でなおかつ身をそいでいくというところに力点が置いてあったと思うんで、その辺のところの考えをちょっと聞かせていただきたいと思うんです。","respondent":"松代道路公園課長","answer":"わかりやすいものは、当然スムーズに委託化が進むと思うんですが、ちょうど中間的なファジーな部分があろうかと思いますので、そういったところはそういった視点をきちんと押さえて、決して道路公園等の利用される区民の方に、以前とは随分変わったなと。","voiceIndex":9,"id":"exchange-004"},{"speaker":"原委員","kind":"質問・要望","question":"この作業そのものについては、区民と密着していて、非常に見える部分の作業なわけですよね。それともう一つは、さっき２４名、２４名という話が出ているんですけれども、その基準というのはどこから割り出して、先ほど２名を一つの単位にするからそうなんだというお話なのかどうなのかということも含めて、ちょっとお答えをいただければと思います。","respondent":"松代道路公園課長、桑村人事課長","answer":"１班だけではどうかということも検討しましたが、ある程度の、先ほど言いました緊急対応、災害、陳情、それと地域を広くエリアを持っております。今回は５出張所の部分を３事務所にエリア分けしております。その意味で、そのためには、区民サービスの維持という意味では、一定清掃作業等も半分以上、半分ぐらいですか、ふれあい作業所等にお願いをして、一定の成果が上がっているわけですけれども、ただ、そうは言っても、緊急時の対応だとか。","voiceIndex":11,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"同じで、実施はいろいろ、それは問題があるでしょうから、いろんな公園の現状で対応されて一定かと思うんですけれども、経験則の中で、先ほど課長の答弁の中でありましたけれども、それなら計画の立て方が何で同じなのかな、もう少し、例えば６月はこういうふうな、樹木がこうだから計画をこうしようとか、経験則があるんだったら。","respondent":"松代道路公園課長","answer":"前回、現地を見ていただいた後、若干ご説明をしたところですが、今のご質問の、１班、２班における計画と実施の中身ですけれども、確かに計画のところをご覧いただければわかりますように、路面清掃、集水桝清掃等々を基本に行ってあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"それからあとは、そのほかいろいろな事業があるんですけれども、今課長がおっしゃった経験則があって、それから、この時期にこういうのがあるということになるんだったらば、例えば私たちは当然委託の方向で賛成していくんですけれども、この内容ももう少し詰められるんじゃないですかということを言いたいわけですよ。だから、そういうようなことをもう少し考えているかどうかなという思いがあるのが一つ。","respondent":"松代道路公園課長","answer":"ただ、これに関しましては、一方で区民参加の維持管理というようなものをいろいろ検討し、模索していますので、地域の皆さんにもそういった目というのをぜひいただきながら、少しでもボランティアとか、そういった面も含めまして。","voiceIndex":16,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"民間だったら。例えば教育とか、それから保育園の場合の話は別ですけれども、この作業については非常に割りやすいし、数字にしやすい作業が出てくるわけですから、この延べ人数で９６１名の方に人件費を掛けて、それから道路関連事業とか公園関連事業を割り返していけば、多分委託する手前にもっといろんな数字的なデータがあったはずなんですよ。それにつながっていくと思いますが、いかがでしょうか。","respondent":"松代道路公園課長","answer":"そういったものを、今委員のご指摘のように、さらに今直営体制の中でやっている部分、ちょっと見えない部分、非常に数値化しにくい部分が現実としてあるんですが、それを委託化に振りかえる中での数字、そういったものはきちんと精査を今後ともしていきたいと考えています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"どちらかというと、公務員はそう見られてきた。でも、それをいろいろ指摘をされ続けた中で、委託の方向が見えてきた。それを、ですから平成１８年度以降どういうふうに対応していくのか、大きなこれは問題となってきます。清掃・リサイクル特別委員会ではありませんので、あまり突っ込みませんけれども、どうしても特勤手当の扱いを品川区はどう考えていくかということをお聞かせください。","respondent":"桑村人事課長","answer":"私どもとすれば、これはちょっとお答えになっていないかもしれませんけれども、その中で十分現場を見させていただいて、平成１８年の４月の段階にどう結論を出すかというのは、これから正直言いまして十分議論させていただきたいところだと思います。","voiceIndex":20,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"すぐ品川区独自で解決できるとは私も思っていませんけれども、ただ、とはいうものの、毎日ごみは出てくるわけだし、それをどう対処していくかというどうしても責任もあるわけですから、すぐに結論は出ないかもしれませんが、ただ今年はもう平成１５年でしたか、あと３年間の中で、まず組合が解散するかどうかはっきり見えてこないということとか、それから、身分がどこに所属するかということは。","respondent":"松本環境清掃事業部長","answer":"これは人事課長が申し上げたように、今検討中です。それと、その前に来る平成１５年４月から、新たに清掃現場に区の職員が配置されていきます。そのときの、同じ作業をやっているときの格差をどうするのかという課題がもう一つあろうかと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これはとても大きな方向転換でありますので、３年間のうちに十二分に議論をしていただきたいと思って、もちろん私ども議会からいろいろ指摘はしていこうと考えていますので。ですから、平成１８年を超えたその先の話になってくるんですけれども、品川区がほんとうにこの清掃事業のことを責任を持ってやっていくんでしたらば、それこそ大きな意味での行革の対象になっていく可能性は十分あるわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほど現業職員の委託化はどこまで委託できるのかという質問で、公務員としての範疇としての仕事があるという答弁なんですけれども、やはり答弁の中で出ていますように、緊急の陳情に対する処理ですとか、衛生的な、動物の死体処理ですとか、いろいろあるのは想像できるんですけれども、その、やはり委託化をできる範囲を伸ばしていただきたいという、そういう思いから。","respondent":"松代道路公園課長、岩田管理工事課長","answer":"ですから、今、委員がおっしゃたような趣旨は、きちんと委託化できるようなところで進めていくようなことを今後も検討してまいります。ただ、先ほど道路課長が申しましたように、災害時等とか緊急時対応のときのための、いわゆる手足となって動けるような部隊は若干名、やっぱり各国。","voiceIndex":25,"id":"exchange-012"},{"speaker":"本多委員","kind":"質問","question":"公園の管理ですとか、道路の管理、河川の管理とか、道路の高潮ですとか、河川についてはすべて全面委託をされておりますが、全面委託をしても、やはり区の行政の管理上の責任というのがしっかりと責任があるわけで、しかも、委託は全面的にできるということで、やはり行政というのは管理の面でしっかりすれば委託が十分に進められるのではないかなという思いで質問させていただきまして、区のその答弁の中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"金高委員","kind":"質問","question":"一つには人件費が当然入るでしょうし、それ以外に、職員の場合ですと人件費、それから通常経費としてのいわゆる抱えている人員ですから、当然社会保険料などを負担していく、あるいは管理費としてのいわゆる土木に関する材料費等すべてかかってのコストになっていくと思うんですね。あるいはふれあい作業所ですと、どちらかというと団体的な感じがあります。","respondent":"松代道路公園課長","answer":"委託の内容等です。今現在、委託を項目別に挙げますと、６６件ぐらい委託をしてございまして、年間６億６，０００万円ぐらい、細々したものも入れまして、いろいろと委託を図ってあります。","voiceIndex":29,"id":"exchange-014"},{"speaker":"金高委員","kind":"確認","question":"そうしますと、その委託した後のことでもって考えられることは、今現在委託している部分があるわけですけれども、実際の指揮命令系統といいますか、確かに契約しているということを絶えずチェック、今現在でもチェックしていると思うんですけれども、それがほとんど委託先にいるわけですから、その辺のチェックの仕方と、それから確認といいますか、それらについては。","respondent":"松代道路公園課長","answer":"委託の執行に当たりましての進め方ですけれども、一応通常の工事等とほとんど同じでございまして、こういったものをやってほしいということで数字を出しまして、それの作業内容の仕様を明記して、それを契約をするという形で、それを執行するに当たりましては、各事務所。","voiceIndex":31,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"前回お話が出ていたとすれば大変申しわけないんですけれども、確認ということで教えていただきたいんですが、まず、作業の実態の中で、運動施設を除いて１班４人体制でやっているというふうにここに書かれてあるんですけれども、ここで言う運動施設というのは、公園にある運動の遊具、鉄棒とかブランコとか滑り台とか、ああいう運動の施設そのものが業者が設置したり何かするから。","respondent":"松代道路公園課長","answer":"これは先ほど申し上げましたように、来年度の４月に全面的に委託をするように今進めておりまして、平成１４年度はその半数を委託化しております。来年の４月からはもうすべて委託化をしてまいります。","voiceIndex":33,"id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほど来から実態に即した効率化を図っていくという流れも考えておられるわけですから、そういう面で、ぜひお願いをしておきたいなと、こんなふうに思います。そこでですね、これは全面的に委託化されていった中で、今おられる方々の処遇というんですか、それはまたどんなお考えが出てくるかと思うんですけれども、こういうところでお尋ねしていいのかどうかわからないんですけれども。","respondent":"桑村人事課長","answer":"それで、この職員というのと、先ほどもおっしゃいました清掃のところで一定の職員が必要になって、区の職員が充てられるという中で、一定の検討の材料には十分入るというふうに私どもは思っておりますし、また両方の現場の方にもご相談しているというのが今の実態です。","voiceIndex":35,"id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"早い時点からそうすべきであった。戸越公園を視察させていただいたときも、なぜ正規職員がチェーンソー等々で生け垣の剪定をしなきゃいけないのか。あれは１日や２日で伸びる状態ではなかった。それで、ほかに特に気になった点をお伺いしておきたいんですけれども、財産管理の問題ですが、荏原清掃事務所にお邪魔しましたときに、神棚がありましたね。この神棚は、財産の位置づけはどうなっているんですか。","respondent":"中山清掃リサイクル課長","answer":"平成１２年４月に清掃事業が移管するに際して、事前に都区で財産の移管の協議をし、基本的に清掃事務所は、土地、建物すべて、備品調度も含めて各区の財産という形に移管されております。","voiceIndex":37,"id":"exchange-018"},{"speaker":"鶴委員","kind":"質問","question":"だから、その神棚というのは、区の財産の位置づけとして受け取ったときに、何も点検することなくそのまま受け入れたということなのかどうか。現在のあの神棚についてはどういう位置づけになっているのかという点をまずお聞きしたいですね。","respondent":"中山清掃リサイクル課長","answer":"財産上の物品として受け取ったということと、具体的な財産としての位置づけというのは別です。あれはあくまでも実態として置いてあるですから、いわゆる公的な財産ということではございません。具体的に言えば、私物の扱いになります。","voiceIndex":39,"id":"exchange-019"},{"speaker":"鶴委員","kind":"質問","question":"個別のものであるならば、ほかの施設にもそういう考え方で置けるということになりますね。それでよろしいんですか。","respondent":"中山清掃リサイクル課長","answer":"例えば車が納車される際にも、これはあくまでも職員が拠出しながらお守りをつけたりというようなこともやっておりまして、これも私物と言えば私物、しかし、そういう感情も含めて、すべて取り除くというのがいかがなものかという意味では、認めているというか。","voiceIndex":43,"id":"exchange-020"},{"speaker":"鶴委員","kind":"意見","question":"私物でも、今お話がありましたように、お守りとかそういうものは、個人でどう所持しようと、それは全然私たちがとやかく言う筋合いのものではないというふうに思いますね。要するに、そういう交通安全を祈願する、その心情は深く理解できるとしても、これはやっぱり峻別すべきことではないか。どういう見解におとりになるのか。気になる点なのでお尋ねをしておきたかったんですね。","respondent":"中山清掃リサイクル課長","answer":"十分、今のそういう問題というか、そのような委員のご指摘の点を踏まえたことについては、検討の課題であるということで検討していきたいと考えています。","voiceIndex":45,"id":"exchange-021"},{"speaker":"鶴委員","kind":"質問・要望","question":"それは十分、ここでは今、即答を求めたわけではありません。なぜかならば、最近頻繁に見かけることは、品川区の防災広場だとか、もしくは公園、実態的に秋になるとどう使われるか。書いてあるじゃないですか。それで許していくならば許していくということにもなるわけだけれども、やっぱりある程度のしっかりした物の考え方をしておかないといけないんではないかというふうに思うんですが、いかがですか。","respondent":"中山清掃リサイクル課長","answer":"繰り返しになるかもしれませんが、望ましい状況ではないということの認識を持ちながら、今の点を踏まえて検討の課題とさせていただきたいと思います。","voiceIndex":47,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"それで、突然その日、次の週とかその次の翌月から違う役職につくというのは幾らでもあるわけですから、公務員の仕組みと言いましょうか、何でこういう方々が、ずっと作業だったら作業しかできないのか、調理員は調理しかできないのか、それはもしかしたら、この方々が持っていらっしゃる能力を、その仕組みの中で縛っている可能性もあるかもしれない。","respondent":"桑村人事課長","answer":"その道については十分研究する必要がありますけれども、いろいろな、そういう意味では違う意味での能力を、実証を求められるような職種へですが、なかなか行くのが難しいというのが実態になってあります。","voiceIndex":49,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"確認","question":"いろいろその仕組みの中で難しいという答弁をいただきました。だけれども、本人がその希望をするんだったらば、そういう場を与えてあげてくださいという思いがありますが、その確認と、それから、今まで実例がないんでしょうか。こういうふうな、例えば現業から皆さんの事務職というんですか、それに行くとか。そういうようなことはなかったんでしょうかということをあわせてお答えください。","respondent":"桑村人事課長","answer":"それで、それについては、一定の実証がなければ、その後その仕事を続けていくのにどうなんだろうかというのは、やはり考え方としてあろうかと思います。","voiceIndex":51,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"意見","question":"いきなり今の仕組みを大きく変えることはできないと思います。だから、今の仕組みとか体制はわかります。ただ、その中でも十二分に持っている、いろいろな職員の個々の持っていらっしゃる技能とか裁量を発揮できるような仕組みづくりをしてくださいよということをお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、職種によってバランスが崩れるところも出てきますよね。そうすると、その方に対しては、今のようなお話の中で進めていく場合があるのかどうか、それとも全然違うところから、例えば東京都のほうから持ってきちゃうとか、何かその辺のところをうまくバランスをとっているんだろうと思うんだけれども、現状を聞かせていただけますか。","respondent":"桑村人事課長","answer":"そのような議論が決着をつかないままに、なかなか採用に入るというのは、やはり本気で議論しないというんでしょうか、そういうことになるので、それは一つの考え方をまとめたところで、採用なり、あるいはほかの職種から異動なりを考えていきたいというのが今の結論です。","voiceIndex":54,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"１点だけちょっとお聞かせ願いたいんですけれども、先ほど清掃の話なんですけれども、部長のお話の中で、現在の清掃職員と来年４月から区の職員を配置をしていく中で、給与差の問題が一つの課題になっているんだというお話があったかと思うんですけれども、その辺の来年４月ですから、そう遠い先の話ではないので、もう少し考え方として決まっているんではないかと思うんですけれども。","respondent":"桑村人事課長","answer":"それで、その意味で、大変この９月の時点でまだ方向をしゃべれと言われても、なかなか難しいところがありまして、今現状の中でどう折り合いをつけるかという検討をしているというのが現実です。","voiceIndex":56,"id":"exchange-027"},{"speaker":"藤田副委員長","kind":"質問","question":"私は、この４人１班の、この中身についてちょっとお伺いしたいんですけれども、これは仕事はこれからどんどん委託をしていく。今、我々現場へ行きました。確かに４人は必要ですよね。ところが、今そういう形を全部今度は委託で、業者に任せるわけですから、その今までの引きずった４人ではなくて、例えば４人を３人にするとか、６人で例えば緊急時にやるとか、区民からそういう苦情があればすぐ対応できる。","respondent":"松代道路公園課長","answer":"委員おっしゃるように、当然それは一つの単位ですので、作業内容に応じて緊急対応のときは６名とか８名とか、２名単位で必要なところに行くとか、そういったことは十分考えられますし、今現在もそういった内容に応じた部分の作業はやっているところもあります。","voiceIndex":58,"id":"exchange-028"},{"speaker":"藤田副委員長","kind":"質問・要望","question":"時間の関係で要望だけしておきますけれども、三つの土木事務所に行きました。これから地域の人があそこに行って、どういう花壇にするかというような、そういうような場ではないということを言っておきますので、ぜひこれは改築するなり、適当なところにもう少し移転してきちっとやるとか、そういう体制をつくるべきだと私は思うんですけれども、時間の関係で、要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-029"},{"speaker":"宮崎副委員長","kind":"確認","question":"何点か伺いたいんですけれども、この委託していく、そういう方向での議論がされておりますけれども、いろいろ心配な点もあるんですけれども、まず、やっぱり費用がどうなるかとか、あるいはそういう仕事をやった場合に、委託した場合に安定的にできるのかとか、そういういろいろな問題があろうかというふうに思うんですけれども、まずちょっと前提として聞いておきたいんですけれども。","respondent":"松代道路公園課長","answer":"それと、４０の作業、これはもうこういうふうに事例的に挙げたものですけれども、こういったものをきちんと、先ほど来申し上げておりますように、サービスの低下につながらないような形で実施していく、それはもうこれからさらに委託化をしていく中で。","voiceIndex":61,"id":"exchange-030"},{"speaker":"宮崎副委員長","kind":"質問","question":"今手元に職員を置いてやっているというのから、全部出してしまうとどうなんだというのが一番心配なんですけれども、ここら辺のところはどういうふうにお考えなのか、その点でさっき、いわゆる外注、委託したときの経費というのは、果たしてそういう無理がないのかどうなのかというところをどういうふうにお考えなのか、そこのところをちょっとお伺いしたいなというふうに思っております。","respondent":"松代道路公園課長","answer":"その方が、例えばＡさんという方がずっとそのものをするのではなくて、３交代だとか、内容に応じた形でいろいろと工夫されてやられています。","voiceIndex":63,"id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"質問","question":"いわゆる行政としての事業の蓄積といいますか、そういうものも含めてどういうふうに考えていくのかというのと、この今何社か相見積りをとって比べていますよということなんだけれども、これはあくまでも現時点での話ですから、将来的なところも含めての見通しというのが一体どうなっているんだろうということで、そこのところを質問したわけなんですけれども。","respondent":"中尾根企画部長","answer":"にもかかわらず、私どもが清掃するのは、１日のところでどこかで清掃をやればいいじゃないかというのが、残念ながら今の公務員の清掃のやり方なんです。なぜなら、それは制約があるからです。９時から５時というような時間の制約の中で自由にニーズに合わせてなかなかできない。","voiceIndex":65,"id":"exchange-032"},{"speaker":"宮崎副委員長","kind":"意見","question":"一般的には先ほども言いましたけれども、公務員と民間だと、大体公務員は給料は安いけれども安定しているという、そういうのがよく言われていましたけれども、例えば経済状況が変わったら、委託のほうが高くなる可能性というのがあると考えておられるのか、そういうことはまずないというふうに考えておられるのか、まずそこのところはどうでしょう。","respondent":"中尾根企画部長","answer":"したがいまして、そのサービスとコストの部分を常に選択して、てんびんにかけて判断をしていくわけですから、経済の状況で今労働費用が安いから、だから委託なんだ、高くなったら委託をやめるんだ、単純にそのような判断でするものではない、そのようにお答えしたつもりです。","voiceIndex":67,"id":"exchange-033"},{"speaker":"宮崎副委員長","kind":"意見","question":"これについてはいろいろな経済状況で逆転する場合もあるんではないかというふうに思うんですけれども、そういうところの見通しといいますか、そこのところはどういうふうにお考えなのかというところをちょっと聞いたんですけれども、答弁がなかったので、お願いしたいと思います。","respondent":"市岡企画財政課長","answer":"そういうふうに考えますと、相対的にはいろいろな事態が想定されるでしょうけれども、公務員のほうの状況も変わるでしょうし、それから民間の労働市場も、一言で言えばかなり流動化してきますので、単純なコスト比較を今しても、あまり意味がないのではないかな。","voiceIndex":69,"id":"exchange-034"},{"speaker":"宮崎副委員長","kind":"質問","question":"わかりました。コストは私も今の時点で比較しても意味はないと思います。ここの集水桝で言えば、例えばここのところは何回やると、あるいは清掃のレベルはこういうレベルでやってくれだとか、そういうものというのは当然つくるんだろうと思うんですけれども、いわゆる現場の感覚に任せるのか、それとも基準をきちっとつくってやっていかれるのか、そこのところはどうなんでしょうか。","respondent":"松代道路公園課長","answer":"現状の部分での、そのままの水準でいいのか、企画部長がご答弁申し上げましたように、ほんとうに区民が求めるサービスはどういうところか、それをきちんと見直して、アップするものもあれば、少し見直して低減するもの、その状況に応じてきちんと仕様書の中で明記して。","voiceIndex":71,"id":"exchange-035"},{"speaker":"宮崎副委員長","kind":"意見","question":"そうすると、基本的には今までやっている仕事のレベルを下げないところでの基準かということになろうかと思うんですけれども、そうなると、ますますこの、私はちょっとさっきの話に戻るんですけれども、委託を受けるところの経済、何と言いますか、受ける側のほうの事情というのもよくつかんでいかないと、状況が変わるとがらっと変わるとか。","respondent":"中谷まちづくり事業部長","answer":"そういう意味では、今後この清掃について限って言えば、委託先の確保はますます我々していかなくちゃいけない一つの、区の全体としての課題というふうに認識もしております。","voiceIndex":73,"id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"中身というよりも、資料２のこの５５２事業の評価を進めてきて、議会に出していただいたときのこの表のつくり方の問題なんですけれども、前回、平成１３年度の事務事業評価を見ますと、自己評価があって、１次評価があって、２次評価があって、それ以外にそれぞれに評価基準の点数をつけたものという資料をいただいているんですけれども、今回いただいたのは、もう評価と、それと実施方向だけということで。","respondent":"榎本行財政改革担当課長","answer":"それで、実際に平成１３年度につきましては、事務事業評価の仕組みを明らかにして示していくということで、ある程度細かくいろんなものを入れてありますけれども、実際上、区として公表したものにつきましては最終評価のみで公表しておりますので、その形式にあわせまして。","voiceIndex":80,"id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"これはお願いなんですけれども、平成１３年度の委員会の中で、このそれぞれの評価基準がどうであったかというのを入れたような中身の資料を出してほしいという論議があったように覚えているんですけれども、その結果として、こういう平成１３年度最後のほうに出てきた評価基準での、点数なんかも含めた資料が出たと思うんですけれども、この辺も含めた。","respondent":"榎本行財政改革担当課長","answer":"そういう形でのまとめは今後やっていく予定ですけれども、点数だけが入ったもので、ちょっとわかりやすいかどうかというものもございまして、執行実績と、それに伴うかかったコスト、それから最終的な事業の方向性というものでまとめさせていただきたいと考えています。","voiceIndex":82,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問","question":"それで、これは純粋にその事業が拡大する事業か、継続する事業か云々の評価はいいんですけれども、もっと費用対効果を厳正に考えていくと、ここに人件費を落とし込んで、例えば１０人の仕事で１０の仕事をしたら当たり前の話で、そうではなくて、そこまで踏み込んでいって、今拡大する事業だったとしても、ここにはちょっと人がい過ぎるよとか、その評価をなぜしないのかということを聞きたいのが一つと。","respondent":"榎本行財政改革担当課長","answer":"事業の評価単位として、細かくとればかなり細かくとる部分もありますけれども、実際上その部分がどの単位でとるのが有効かということで、いろいろ工夫を図っていきたいと思いますので、これがすべてということではなくて。","voiceIndex":84,"id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要はすべての品川区の事業に対してこれをやっていくんですかということをお伺いしていますので、そのことをお聞かせください。","respondent":"榎本行財政改革担当課長","answer":"先ほど評価対象事業を一定整理したですけれども、その中で、実際上あまり評価をかけても義務的に支出されてしまうような事業につきましては、中で努力して経費を安くするとか、ほかの手段で考えるとかという形は各事業課レベルではできないと思いますので。","voiceIndex":86,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、その住基ネットのところは、要するに公務員の責任の中でやってほしいという思いがありますので、その辺の確認をしてください。現在、東京都、清掃一部事務組合の施設になっておりますけれども、品川区にあるわけですから、あのし尿処理のコストとか、それから費用対効果ということを考えていくべきだと思いますが、その将来的な考え方をあわせてお聞かせください。四つくらい聞きましたですかね。","respondent":"榎本行財政改革担当課長","answer":"それは逆に外部の視点ですので、もっと事務事業レベルではなくて政策レベルでの議論という形になりますけれども、その中で十分検討していけるのではないかというふうに考えております。","voiceIndex":88,"id":"exchange-041"},{"speaker":"伊藤委員","kind":"確認","question":"参考までに、し尿の処理のほう、収集も含めてですけれども、既に民間の業者が都内で幾つかやっているそうですから、そうすると、この将来的に、あの処理施設がたしか八潮団地にありましたよね。委託化することはもちろん構わないんですが、そこの安全確保策の確認だけをしておかないと、おい、ちょっと待てという気になりますので、ご答弁をお願いいたします。","respondent":"中尾根企画部長","answer":"今までずっと説明したとおりのシステムはずっと維持されて、外部から入れないようになるはずですので、その部分はちょっと触れられませんので、除いているという考え方でご了解願います。","voiceIndex":90,"id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"先ほどの説明の中で、昨年とちょっと変えてある理由をということでご説明があったんですけれども、この評価基準なんですけれども、今回も基本評価基準と、それに加味して挑戦加点評価基準の３項目があるわけで、その両方を加味をしながら、この総合評価基準をつくり上げてきたというご説明なんですけれど、そうしますと、これはあくまでも行政単位で出された事務事業評価ですから。","respondent":"榎本行財政改革担当課長","answer":"その辺の、どういうふうな形でわかりやすく出していくかというところが、点数で出す形がどうかなということで、去年の段階では１回点数でお出しさせていただいたんですけれども、点数も並べてみますとなかなか難しいものもありますので、この辺につきましては。","voiceIndex":92,"id":"exchange-043"},{"speaker":"原委員","kind":"意見","question":"それはそれとして、考えに入れないのか何なのか、例えばこれを出されてきて、これは自分たちの評価だからこれでいいんだよというのか、あるいは今みたいな形でチェックが入って、これから事務事業評価のほかに、またいろんな評価が出されるわけですけれども、その辺のところがどういうふうに思われているのか、これはこれでもういいんだよと、この評価でこれでいいんだけれども。","respondent":"榎本行財政改革担当課長","answer":"それに対しまして、各委員ですとか、区民の方から、今度逆にこの評価に対してどうなのかという形での評価をさらに重ねていくという形が、この事務事業評価ですとか行政評価システムの中で使われているものですので。","voiceIndex":94,"id":"exchange-044"},{"speaker":"原委員","kind":"質問","question":"そうしますと、その評価の積み重ねの結果、行政側のほうとしてはＤ段階だったよ、あるいはＣ段階だったよというものが、例えば区民の意向とか、あるいは我々の意向が入った場合に、じゃあ改善しようじゃないかということで評価が上がってきたりという部分もあるわけですか。ちょっとその辺を。","respondent":"榎本行財政改革担当課長","answer":"もちろん、あくまでもここは行政が自己点検でした評価ですので、この後、実際にはこの評価は決定ではありませんので、実際上、事業が最終的に執行される段階には、区としての意思決定が入りますので、その途中の段階ではどんどん評価の積み重ねによって。","voiceIndex":96,"id":"exchange-045"},{"speaker":"原委員","kind":"提案","question":"今回の場合、点数ではないけれども、この二つの評価を総合して考えられる基準の中で総合評価を下したんだということですから、もう少し何か具体的に加味できるものがあれば、もうちょっと正確度が増すのかなというふうな気もしまして、何かというふうな提案はできませんけれども、ちょっとそのような考え方がありましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-046"},{"speaker":"堺委員","kind":"質問・要望","question":"委員長にちょっとお尋ねをしておきたいんですが、今ご説明をいただきましたけれども、この５５２事業の評価結果を一覧表にまとめていただきました。この中の個々のことについても、今ここで質疑を取り交わしちゃうんですか。仮にそうだとすると、ここに、ご覧いただいたとおり理事者は。ですから、これは所管別、事業。その辺のちょっと確認。その辺をちょっと教えていただきたい。確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-047"},{"speaker":"宮崎副委員長","kind":"質問","question":"それと、あと、最終的には評価が変わることがあるということなんですけれども、それと、今回はこの事業部経営会議も踏まえていますので、そうすると、これは事業部経営会議から、例えば先ほどの質問の関係でも、どこかに案として出したものであって、そこのあるところで、またもんでもらう、そういう位置づけになっているのかどうなのか、ちょっとそこのところがよくわからないので。","respondent":"榎本行財政改革担当課長","answer":"その後、区民公表の形をとりますので、区民公表いたしまして、区民からのご意見をいただくという形での公表をしていく予定です。これは平成１３年度も行いまして、その形で進めていきたいと考えています。","voiceIndex":103,"id":"exchange-048"},{"speaker":"宮崎副委員長","kind":"意見","question":"前の政策評価と事務事業評価との関係も何かあまりしっくり、私の中では腑に落ちていないんですけれども、このちょっと言い方が適切かどうかわからないんですけれども、事務事業、私は政策そのものがやっぱりこの事務事業のところにあらわれていて、ここのところは行政のほうでやるよと、あと政策のほうはまた政策評価のそういう仕組みでやるよとなると、何か整合性がとれないというか。","respondent":"榎本行財政改革担当課長","answer":"もちろんその基礎データとしては事務事業評価の部分を踏まえておりますので、行政内部ではこういう評価をしたけれども、外部の評価委員から見た場合にはどういうふうになるのかというご意見も踏まえながら、もっと大きな政策単位での評価を実施していくという予定でおります。","voiceIndex":105,"id":"exchange-049"},{"speaker":"宮崎副委員長","kind":"意見","question":"そうすると、今外部評価のところでは、個々の細かいところではなくて、大きなところでやるんだということなんだけれども、それでも事務事業評価を踏まえてのことなんだということですけれども、そうすると、外部評価のところでは、実際にどういう評価というか、意見をもらえているのかという、それ自体は公開されておりましたか。私はちょっと承知していなかったんですけれども、外へ出ていましたか。","respondent":"榎本行財政改革担当課長","answer":"まだこの政策評価につきましては、仕組みづくりを今ちょっと行っているということで、最終的にその評価結果が出るのは平成１５年度に入ってからという形になっておりますけれども、その仕組みの中で、そういういろんな実施計画ですとか、そういうものを評価単位としてとって。","voiceIndex":107,"id":"exchange-050"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そこのところがまだ出ていないということであると、やっぱりちょっと総合的に、私どもはやっぱりいろんなところの評価がどういうふうに出ているのかというは私は知りたいと思うんですね。これはぜひまだこれからだということですから、そこのところをぜひ目に見える形で早急に準備していただきたいなという、これは私の意見で、私のほうから要望しておきたいなというふうに思います。","respondent":"市岡企画財政課長","answer":"それに関連してですけれども、今この時期に特に事務事業評価について取りまとめをさせていただいてご報告申し上げているというは、これから平成１５年度予算に向けた編成が始まりますので、その前に、先ほど出ていました行政の自己評価という観点の責任を十分果たすべく。","voiceIndex":109,"id":"exchange-051"},{"speaker":"宮崎副委員長","kind":"質問","question":"経費削減は当然だと。現実問題として。そこら辺のちょっと絡み、ニュアンスがよくわからないので、それぞれの経費削減に努めるというのは、それはそれで当然なんですけれども、今、国のほう、あるいは東京都のほうの動きが非常に心配な点もあるものですから、その点での品川区の考えといいますか、そこのところがよくわからないので、ちょっともう一回そこのところをお伺いしたいというふうに思います。","respondent":"市岡企画財政課長","answer":"一番大事なのは、国や都の見直しがそれぞれ必然的なものであれ、その肩がわりを区がするという関係ではありませんので、区は区であくまで自主的な判断をしていく、こういう観点から自己評価を行う、こういうことです。","voiceIndex":111,"id":"exchange-052"},{"speaker":"宮崎副委員長","kind":"質問","question":"そういうところの、何と言いますか、先駆的な事業を進めていく、この場合の費用の考え方、これまでの既存の事業とのリンク、そういうものがどういうふうになっていくのか、例えばお金がなければなかなかできない、あるいはお金がなくてもやってみて、どこかから費用を、事業部制ですから、その事業部のところでとにかく費用をつくってもらう、そういう考え方でいくのか。","respondent":"市岡企画財政課長","answer":"ちょっと原点に戻りますけれども、この事務事業評価というものは、今のうちの体制で言えば、各事業部がいろいろ新しい施策を展開したい、あるいは規定の事業をこういう角度から見直ししたい、こういうときに、事業を執行している所管の部課だけではなくて。","voiceIndex":113,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":57852,"voices":119}}]);
